#[derive(Debug, Clone, Default)]
struct TranslatorObjectBinding {
    bindings: BTreeMap<String, TranslatorBinding>,
    unknown_paths: BTreeSet<String>,
    resolved_properties: BTreeSet<String>,
}

impl TranslatorObjectBinding {
    fn aggregate_binding(self) -> Option<TranslatorBinding> {
        let unknown = !self.unknown_paths.is_empty();
        let binding = merge_translator_binding_iter(self.bindings.into_values());
        if unknown {
            binding.map(|binding| {
                merge_translator_bindings(
                    &binding,
                    &translator_binding_from_namespace_arg(NamespaceArg::Dynamic),
                )
            })
        } else {
            binding
        }
    }

    fn remove_property(&mut self, property: &str) {
        self.bindings.retain(|path, _| {
            path != property
                && !path
                    .strip_prefix(property)
                    .is_some_and(|remaining| remaining.starts_with('.'))
        });
        self.unknown_paths.retain(|path| {
            path.is_empty()
                || (path != property
                    && !path
                        .strip_prefix(property)
                        .is_some_and(|remaining| remaining.starts_with('.')))
        });
        self.resolved_properties.retain(|path| {
            path != property
                && !path
                    .strip_prefix(property)
                    .is_some_and(|remaining| remaining.starts_with('.'))
        });
    }

    fn path_is_unknown(&self, path: &str) -> bool {
        self.unknown_paths.iter().any(|unknown| {
            let applies = unknown.is_empty()
                || path
                    .strip_prefix(unknown)
                    .is_some_and(|remaining| remaining.starts_with('.'));
            applies
                && !self.resolved_properties.iter().any(|resolved| {
                    resolved != unknown
                        && (unknown.is_empty()
                            || resolved
                                .strip_prefix(unknown)
                                .is_some_and(|remaining| remaining.starts_with('.')))
                        && (path == resolved
                            || path
                                .strip_prefix(resolved)
                                .is_some_and(|remaining| remaining.starts_with('.')))
                })
        })
    }

    fn binding_for_path(&self, path: &str) -> Option<TranslatorBinding> {
        let exact = self.bindings.get(path).cloned();
        if self.path_is_unknown(path) && !self.bindings.is_empty() {
            let dynamic = translator_binding_from_namespace_arg(NamespaceArg::Dynamic);
            return Some(
                exact
                    .map(|binding| merge_translator_bindings(&binding, &dynamic))
                    .unwrap_or(dynamic),
            );
        }
        exact
    }

    fn has_binding_at_or_below(&self, path: &str) -> bool {
        self.bindings.keys().any(|candidate| {
            path.is_empty()
                || candidate == path
                || candidate
                    .strip_prefix(path)
                    .is_some_and(|remaining| remaining.starts_with('.'))
        })
    }

    fn mark_unknown(&mut self, container: &str) {
        self.unknown_paths.insert(container.to_string());
        self.resolved_properties.retain(|path| {
            if container.is_empty() {
                return false;
            }
            path != container
                && !path
                    .strip_prefix(container)
                    .is_some_and(|remaining| remaining.starts_with('.'))
        });
    }

    fn merge_alternative(mut self, alternate: Self) -> Self {
        for (path, binding) in alternate.bindings {
            self.bindings
                .entry(path)
                .and_modify(|current| *current = merge_translator_bindings(current, &binding))
                .or_insert(binding);
        }
        self.unknown_paths.extend(alternate.unknown_paths);
        self.resolved_properties = self
            .resolved_properties
            .intersection(&alternate.resolved_properties)
            .cloned()
            .collect();
        self
    }

    fn assign_path(
        &mut self,
        property: &str,
        operator: AssignmentOperator,
        exact_target: bool,
        assigned_binding: Option<&TranslatorBinding>,
        assigned_object: Option<&Self>,
    ) {
        let replaces_value = exact_target && !operator.is_logical();
        if replaces_value {
            self.remove_property(property);
            self.resolved_properties.insert(property.to_string());
        }
        if operator != AssignmentOperator::Assign && !operator.is_logical() {
            return;
        }
        if let Some(binding) = assigned_binding {
            self.bindings
                .entry(property.to_string())
                .and_modify(|current| *current = merge_translator_bindings(current, binding))
                .or_insert_with(|| binding.clone());
        } else if let Some(assigned) = assigned_object {
            for (nested_path, binding) in &assigned.bindings {
                let path = format!("{property}.{nested_path}");
                self.bindings
                    .entry(path)
                    .and_modify(|current| *current = merge_translator_bindings(current, binding))
                    .or_insert_with(|| binding.clone());
            }
            self.unknown_paths
                .extend(assigned.unknown_paths.iter().map(|nested_path| {
                    if nested_path.is_empty() {
                        property.to_string()
                    } else {
                        format!("{property}.{nested_path}")
                    }
                }));
            if replaces_value {
                self.resolved_properties.extend(
                    assigned
                        .resolved_properties
                        .iter()
                        .map(|nested_path| format!("{property}.{nested_path}")),
                );
            }
        }
    }

    fn subobject(&self, property: &str) -> Option<Self> {
        let prefix = format!("{property}.");
        let mut result = Self::default();
        result
            .bindings
            .extend(self.bindings.iter().filter_map(|(path, binding)| {
                path.strip_prefix(&prefix)
                    .map(|path| (path.to_string(), binding.clone()))
            }));
        result
            .unknown_paths
            .extend(self.unknown_paths.iter().filter_map(|path| {
                if path == property {
                    Some(String::new())
                } else {
                    path.strip_prefix(&prefix).map(ToOwned::to_owned)
                }
            }));
        if self.path_is_unknown(property) {
            result.unknown_paths.insert(String::new());
        }
        result.resolved_properties.extend(
            self.resolved_properties
                .iter()
                .filter_map(|path| path.strip_prefix(&prefix).map(ToOwned::to_owned)),
        );
        (!result.bindings.is_empty()
            || !result.unknown_paths.is_empty()
            || !result.resolved_properties.is_empty())
        .then_some(result)
    }
}

