fn bind_unknown_parameter_from(arguments: &[Argument<'_>]) -> Option<usize> {
    arguments
        .iter()
        .position(|argument| matches!(argument, Argument::SpreadElement(_)))
        .map(|index| index.saturating_sub(1))
}

