const TS_CHECKER_SCRIPT: &str = r#"
const fs = require('fs');

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', chunk => { data += chunk; });
    process.stdin.on('end', () => resolve(data));
    process.stdin.on('error', reject);
  });
}

function findNode(sourceFile, start, end) {
  let best = sourceFile;
  function visit(node) {
    const nodeStart = node.getStart(sourceFile, false);
    const nodeEnd = node.getEnd();
    if (start < nodeStart || end > nodeEnd) return;
    best = node;
    node.forEachChild(visit);
  }
  visit(sourceFile);
  return best;
}

function unique(values) {
  return [...new Set(values)].sort();
}

function finiteFromType(ts, checker, type) {
  if (!type) return null;
  if (type.isUnion && type.isUnion()) {
    let values = [];
    for (const part of type.types) {
      const partValues = finiteFromType(ts, checker, part);
      if (!partValues) return null;
      values.push(...partValues);
      if (values.length > 128) return null;
    }
    return unique(values);
  }
  if (type.isStringLiteral && type.isStringLiteral()) {
    return [type.value];
  }
  if ((type.flags & ts.TypeFlags.StringLiteral) && typeof type.value === 'string') {
    return [type.value];
  }
  if (type.isLiteral && type.isLiteral() && typeof type.value === 'string') {
    return [type.value];
  }
  return null;
}

function appendFinite(left, right) {
  const values = [];
  for (const l of left) {
    for (const r of right) {
      values.push(`${l}${r}`);
      if (values.length > 128) return null;
    }
  }
  return unique(values);
}

function transform(values, method) {
  if (method === 'toLowerCase') return values.map(value => value.toLowerCase());
  if (method === 'toUpperCase') return values.map(value => value.toUpperCase());
  return null;
}

function finiteFromObjectEntriesBinding(ts, checker, node) {
  if (!ts.isIdentifier(node)) return null;
  const symbol = checker.getSymbolAtLocation(node);
  const declaration = symbol?.valueDeclaration;
  if (!declaration || !ts.isBindingElement(declaration)) return null;
  const pattern = declaration.parent;
  if (!ts.isArrayBindingPattern(pattern) || pattern.elements[0] !== declaration) return null;
  const parameter = pattern.parent;
  if (!ts.isParameter(parameter)) return null;
  const callback = parameter.parent;
  if (!ts.isArrowFunction(callback) && !ts.isFunctionExpression(callback)) return null;
  const iterationCall = callback.parent;
  if (!ts.isCallExpression(iterationCall) || !ts.isPropertyAccessExpression(iterationCall.expression)) return null;
  if (iterationCall.expression.name.text !== 'map' && iterationCall.expression.name.text !== 'flatMap' && iterationCall.expression.name.text !== 'forEach') return null;
  const entriesCall = iterationCall.expression.expression;
  if (!ts.isCallExpression(entriesCall) || !ts.isPropertyAccessExpression(entriesCall.expression)) return null;
  if (!ts.isIdentifier(entriesCall.expression.expression) || entriesCall.expression.expression.text !== 'Object' || entriesCall.expression.name.text !== 'entries') return null;
  const object = entriesCall.arguments[0];
  if (!object) return null;
  const objectType = checker.getTypeAtLocation(object);
  if (!(objectType.flags & ts.TypeFlags.Object) || !(objectType.objectFlags & ts.ObjectFlags.Mapped)) return null;
  const keys = checker.getPropertiesOfType(objectType).map(property => property.name);
  if (keys.length === 0 || keys.length > 128) return null;
  return unique(keys);
}

function finiteFromExpression(ts, checker, node) {
  if (!node) return null;

  if (ts.isParenthesizedExpression(node) || ts.isAsExpression(node) || ts.isSatisfiesExpression?.(node) || ts.isNonNullExpression(node) || ts.isTypeAssertionExpression(node)) {
    return finiteFromExpression(ts, checker, node.expression);
  }

  if (ts.isStringLiteralLike(node)) return [node.text];

  if (ts.isTemplateExpression(node)) {
    let values = [node.head.text];
    for (const span of node.templateSpans) {
      const expressionValues = finiteFromExpression(ts, checker, span.expression);
      if (!expressionValues) return null;
      values = appendFinite(values, expressionValues);
      if (!values) return null;
      values = appendFinite(values, [span.literal.text]);
      if (!values) return null;
    }
    return values;
  }

  if (ts.isNoSubstitutionTemplateLiteral(node)) return [node.text];

  if (ts.isCallExpression(node) && node.arguments.length === 0 && ts.isPropertyAccessExpression(node.expression)) {
    const method = node.expression.name.text;
    const objectValues = finiteFromExpression(ts, checker, node.expression.expression);
    if (!objectValues) return null;
    return transform(objectValues, method);
  }

  if (ts.isIdentifier(node)) {
    const entryKeys = finiteFromObjectEntriesBinding(ts, checker, node);
    if (entryKeys) return entryKeys;
  }

  if (ts.isPropertyAccessExpression(node) || ts.isElementAccessExpression(node) || ts.isIdentifier(node)) {
    return finiteFromType(ts, checker, checker.getTypeAtLocation(node));
  }

  return finiteFromType(ts, checker, checker.getTypeAtLocation(node));
}

(async () => {
  const input = JSON.parse(await readStdin());
  const tsPath = require.resolve('typescript', { paths: [input.root] });
  const ts = require(tsPath);
  const configPath =
    ts.findConfigFile(input.root, ts.sys.fileExists, 'tsconfig.json') ||
    ts.findConfigFile(input.root, ts.sys.fileExists, 'jsconfig.json');
  if (!configPath) {
    console.log(JSON.stringify({ results: [], error: 'no tsconfig.json or jsconfig.json found' }));
    return;
  }
  const config = ts.readConfigFile(configPath, ts.sys.readFile);
  if (config.error) {
    console.log(JSON.stringify({ results: [], error: 'failed to read the TypeScript configuration' }));
    return;
  }
  const parsed = ts.parseJsonConfigFileContent(
    config.config,
    ts.sys,
    require('path').dirname(configPath),
    { noEmit: true, skipLibCheck: true },
    configPath,
  );
  const program = ts.createProgram({
    rootNames: parsed.fileNames,
    options: parsed.options,
  });
  const checker = program.getTypeChecker();
  const results = [];
  for (const query of input.queries) {
    const sourceFile = program.getSourceFile(query.file);
    if (!sourceFile) continue;
    const node = findNode(sourceFile, query.start, query.end);
    const keys = finiteFromExpression(ts, checker, node);
    if (keys && keys.length > 0 && keys.length <= 128) {
      results.push({ index: query.index, keys });
    }
  }
  console.log(JSON.stringify({ results, error: null }));
})().catch(error => {
  console.log(JSON.stringify({
    results: [],
    error: error instanceof Error ? error.message : String(error),
  }));
});
"#;

pub fn find_unused(root: impl AsRef<Path>, config: &TransConfig) -> Result<UnusedReport> {
    find_unused_with_options(root, config, true, true)
}

pub fn find_unused_with_ts_checker(
    root: impl AsRef<Path>,
    config: &TransConfig,
    use_ts_checker: bool,
) -> Result<UnusedReport> {
    find_unused_with_options(root, config, true, use_ts_checker)
}

pub fn find_unused_keys(root: impl AsRef<Path>, config: &TransConfig) -> Result<Vec<String>> {
    find_unused_keys_with_ts_checker(root, config, true)
}

pub fn find_unused_keys_with_ts_checker(
    root: impl AsRef<Path>,
    config: &TransConfig,
    use_ts_checker: bool,
) -> Result<Vec<String>> {
    let report = find_unused_with_options(root, config, true, use_ts_checker)?;
    if report.ts_checker_failed {
        return Err(TransError::InvalidInput(
            "the TypeScript checker failed; rerun with --no-ts-checker to list conservative results"
                .to_string(),
        ));
    }
    Ok(report.unused_ids)
}

pub fn remove_unused(
    root: impl AsRef<Path>,
    config: &TransConfig,
    force: bool,
) -> Result<UnusedReport> {
    remove_unused_with_ts_checker(root, config, force, true, None)
}

pub fn remove_unused_with_ts_checker(
    root: impl AsRef<Path>,
    config: &TransConfig,
    force: bool,
    use_ts_checker: bool,
    exclude: Option<&str>,
) -> Result<UnusedReport> {
    let root = root.as_ref();
    let mut report = find_unused_with_options(root, config, !force, use_ts_checker)?;

    if report.ts_checker_failed {
        return Err(TransError::InvalidInput(
            "the TypeScript checker failed; fix the checker or rerun with --no-ts-checker"
                .to_string(),
        ));
    }

    if report.extraction_usage_detected {
        return Err(TransError::InvalidInput(
            "cannot remove unused keys while next-intl extraction usage is detected".to_string(),
        ));
    }
    if report.dynamic_usage_detected && !force {
        return Err(TransError::InvalidInput(
            "dynamic translation key usage detected; rerun with --force to remove anyway"
                .to_string(),
        ));
    }
    let exclude_patterns = parse_unused_exclude_patterns(exclude)?;
    if !exclude_patterns.is_empty() {
        report
            .unused_ids
            .retain(|id| !exclude_patterns.iter().any(|pattern| pattern.matches(id)));
    }
    if report.unused_ids.is_empty() {
        return Ok(report);
    }

    verify_language_files(root, config)?;
    let snapshot = snapshot_translations(root, config)?;
    let mut updated = snapshot.clone();
    let unused: BTreeSet<&str> = report.unused_ids.iter().map(String::as_str).collect();

    for language in &config.available_languages {
        let translations = updated.get_mut(language).ok_or_else(|| {
            TransError::InvalidInput(format!("missing translations for language '{language}'"))
        })?;
        translations.retain(|id, _| !unused.contains(id.as_str()));
    }

    if let Err(err) = write_snapshot(root, config, &updated) {
        let _ = restore_translations(root, config, &snapshot);
        return Err(err);
    }

    if let Err(err) = verify_language_files(root, config) {
        let _ = restore_translations(root, config, &snapshot);
        return Err(err);
    }

    Ok(report)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct UnusedExcludePattern {
    segments: Vec<String>,
}

impl UnusedExcludePattern {
    fn new(pattern: &str) -> Self {
        Self {
            segments: pattern.split('*').map(ToOwned::to_owned).collect(),
        }
    }

    fn matches(&self, id: &str) -> bool {
        if self.segments.len() == 1 {
            return self.segments[0] == id;
        }

        let mut rest = id;
        let starts_with_wildcard = self.segments.first().is_some_and(String::is_empty);
        let ends_with_wildcard = self.segments.last().is_some_and(String::is_empty);

        for (index, segment) in self.segments.iter().enumerate() {
            if segment.is_empty() {
                continue;
            }
            if index == 0 && !starts_with_wildcard {
                let Some(next_rest) = rest.strip_prefix(segment) else {
                    return false;
                };
                rest = next_rest;
                continue;
            }

            let Some(position) = rest.find(segment) else {
                return false;
            };
            rest = &rest[position + segment.len()..];
        }

        ends_with_wildcard
            || self
                .segments
                .last()
                .is_none_or(|segment| rest.is_empty() || segment.is_empty())
    }
}

fn parse_unused_exclude_patterns(exclude: Option<&str>) -> Result<Vec<UnusedExcludePattern>> {
    let Some(exclude) = exclude else {
        return Ok(Vec::new());
    };

    let mut patterns = Vec::new();
    for pattern in exclude.split(',') {
        let pattern = pattern.trim();
        if pattern.is_empty() {
            return Err(TransError::InvalidInput(
                "unused remove exclude patterns cannot be empty".to_string(),
            ));
        }
        patterns.push(UnusedExcludePattern::new(pattern));
    }

    Ok(patterns)
}

fn find_unused_with_options(
    root: impl AsRef<Path>,
    config: &TransConfig,
    apply_dynamic_exclusions: bool,
    use_ts_checker: bool,
) -> Result<UnusedReport> {
    let root = root.as_ref();
    if config.mode != ConfigMode::NextIntl {
        return Err(TransError::InvalidInput(
            "trans unused currently supports next-intl mode only".to_string(),
        ));
    }

    verify_language_files(root, config)?;
    let primary = load_language_translations(root, config, &config.primary_language)?;
    let source_files = discover_source_files(root)?;
    let mut scan = collect_usage_from_files(root, &source_files)?;
    let ts_checker_error = use_ts_checker
        .then(|| apply_ts_checker_fallback(root, &mut scan).err())
        .flatten();

    let mut unused_ids = Vec::new();
    for id in primary.keys() {
        if scan.used_ids.contains(id) {
            continue;
        }
        if scan
            .used_key_suffixes
            .iter()
            .any(|key| translation_id_matches_key(id, key))
        {
            continue;
        }
        if apply_dynamic_exclusions && is_dynamic_protected(id, &scan.dynamic_usages) {
            continue;
        }
        unused_ids.push(id.clone());
    }

    let unbounded_dynamic_usages = scan
        .dynamic_usages
        .iter()
        .filter(|usage| usage.possible_keys.is_none())
        .cloned()
        .collect::<Vec<_>>();
    let dynamic_usage_locations = dynamic_usage_locations(root, &unbounded_dynamic_usages);

    let mut warnings = Vec::new();
    if !unbounded_dynamic_usages.is_empty() {
        warnings.push(format!(
            "dynamic translation key usage detected in {} place(s)",
            dynamic_usage_locations.len()
        ));
    }
    if !scan.extraction_usages.is_empty() {
        warnings.push(format!(
            "next-intl extraction usage detected in {} place(s); remove is disabled for this project in v1",
            scan.extraction_usages.len()
        ));
    }
    if let Some(error) = &ts_checker_error {
        warnings.push(format!("TypeScript checker failed: {error}"));
    }

    Ok(UnusedReport {
        unused_ids,
        total_ids: primary.len(),
        warnings,
        dynamic_usage_locations,
        dynamic_usage_detected: !unbounded_dynamic_usages.is_empty(),
        extraction_usage_detected: !scan.extraction_usages.is_empty(),
        ts_checker_failed: ts_checker_error.is_some(),
    })
}

fn write_snapshot(root: &Path, config: &TransConfig, snapshot: &TranslationSnapshot) -> Result<()> {
    for language in &config.available_languages {
        let translations = snapshot.get(language).ok_or_else(|| {
            TransError::InvalidInput(format!("missing translations for language '{language}'"))
        })?;
        save_language_translations(root, config, language, translations)?;
    }
    Ok(())
}

fn is_dynamic_protected(id: &str, dynamic_usages: &[DynamicUsage]) -> bool {
    dynamic_usages.iter().any(|prefix| {
        if let Some(keys) = &prefix.possible_keys {
            return keys.iter().any(|key| translation_id_matches_key(id, key));
        }
        prefix.namespace.is_empty()
            || id == prefix.namespace
            || id
                .strip_prefix(&prefix.namespace)
                .is_some_and(|remaining| remaining.starts_with('.'))
    })
}

fn translation_id_matches_key(id: &str, key: &str) -> bool {
    id == key
        || id
            .strip_suffix(key)
            .is_some_and(|remaining| remaining.ends_with('.'))
}

fn dynamic_usage_locations(root: &Path, dynamic_usages: &[DynamicUsage]) -> Vec<UsageLocation> {
    let mut locations: Vec<UsageLocation> = dynamic_usages
        .iter()
        .map(|usage| {
            let path = usage.path.strip_prefix(root).unwrap_or(&usage.path);
            UsageLocation {
                display: format!("./{}:{}", path.display(), usage.line),
                url: format!("file://{}#L{}", file_url_path(&usage.path), usage.line),
            }
        })
        .collect();
    locations.sort_by(|left, right| left.display.cmp(&right.display));
    locations.dedup_by(|left, right| left.display == right.display);
    locations
}

fn file_url_path(path: &Path) -> String {
    path.to_string_lossy()
        .bytes()
        .flat_map(|byte| match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'/' | b'-' | b'_' | b'.' | b'~' => {
                vec![byte as char]
            }
            _ => format!("%{byte:02X}").chars().collect(),
        })
        .collect()
}

fn collect_usage_from_files(root: &Path, paths: &[PathBuf]) -> Result<UsageScan> {
    let project = Arc::new(ProjectIndex::build(root, paths)?);
    let mut combined = UsageScan::default();
    for path in project.files.keys() {
        let source = fs::read_to_string(path)?;
        let scan =
            collect_usage_from_source_with_project(&source, path, Some(Arc::clone(&project)))?;
        combined.used_ids.extend(scan.used_ids);
        combined.used_key_suffixes.extend(scan.used_key_suffixes);
        combined.dynamic_usages.extend(scan.dynamic_usages);
        combined.extraction_usages.extend(scan.extraction_usages);
    }
    combined.dynamic_usages.sort();
    combined.dynamic_usages.dedup();
    combined.extraction_usages.sort();
    combined.extraction_usages.dedup();
    Ok(combined)
}

fn apply_ts_checker_fallback(root: &Path, scan: &mut UsageScan) -> std::result::Result<(), String> {
    let queries = ts_checker_queries(&scan.dynamic_usages);
    if queries.is_empty() {
        return Ok(());
    }

    let request = TsCheckerRequest {
        root: root.to_string_lossy().to_string(),
        queries,
    };
    let input = serde_json::to_vec(&request).map_err(|error| error.to_string())?;

    let mut child = match Command::new("node")
        .arg("-e")
        .arg(TS_CHECKER_SCRIPT)
        .current_dir(root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
    {
        Ok(child) => child,
        Err(error) => return Err(format!("could not start Node.js: {error}")),
    };

    if let Some(stdin) = child.stdin.as_mut() {
        if stdin.write_all(&input).is_err() {
            return Err("could not send queries to the TypeScript checker".to_string());
        }
    }

    let output = child
        .wait_with_output()
        .map_err(|error| format!("could not wait for the TypeScript checker: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "TypeScript checker exited with status {}",
            output.status
        ));
    }

    let response = serde_json::from_slice::<TsCheckerResponse>(&output.stdout)
        .map_err(|error| format!("invalid TypeScript checker response: {error}"))?;
    if let Some(error) = response.error {
        return Err(error);
    }

    apply_ts_checker_results(scan, response.results);
    Ok(())
}

fn apply_ts_checker_results(scan: &mut UsageScan, results: Vec<TsCheckerResult>) {
    let mut resolved = BTreeSet::new();
    for result in results {
        let Some(usage) = scan.dynamic_usages.get(result.index) else {
            continue;
        };
        if result.keys.is_empty() || result.keys.len() > 128 {
            continue;
        }
        if usage.namespace_unknown {
            scan.used_key_suffixes.extend(result.keys);
        } else {
            for key in &result.keys {
                let Some(id) = resolved_translation_id(&usage.namespace, key) else {
                    continue;
                };
                scan.used_ids.insert(id);
            }
        }
        resolved.insert(result.index);
    }

    if !resolved.is_empty() {
        let mut index = 0;
        scan.dynamic_usages.retain(|_| {
            let keep = !resolved.contains(&index);
            index += 1;
            keep
        });
    }
}

fn ts_checker_queries(dynamic_usages: &[DynamicUsage]) -> Vec<TsCheckerQuery> {
    dynamic_usages
        .iter()
        .enumerate()
        .filter_map(|(index, usage)| {
            let start = usage.key_start?;
            let end = usage.key_end?;
            Some(TsCheckerQuery {
                index,
                file: usage.path.to_string_lossy().to_string(),
                start,
                end,
                namespace: usage.namespace.clone(),
            })
        })
        .collect()
}

fn resolved_translation_id(namespace: &str, key: &str) -> Option<String> {
    match (namespace.is_empty(), key.is_empty()) {
        (true, true) => None,
        (true, false) => Some(key.to_string()),
        (false, true) => Some(namespace.to_string()),
        (false, false) => Some(format!("{namespace}.{key}")),
    }
}

pub fn collect_usage_from_source(source: &str, path: &Path) -> Result<UsageScan> {
    collect_usage_from_source_with_project(source, path, None)
}

fn collect_usage_from_source_with_project(
    source: &str,
    path: &Path,
    project: Option<Arc<ProjectIndex>>,
) -> Result<UsageScan> {
    let allocator = Allocator::default();
    let source_type = SourceType::from_path(path).unwrap_or_default();
    let ret = Parser::new(&allocator, source, source_type).parse();
    if !ret.errors.is_empty() {
        return Err(TransError::InvalidInput(format!(
            "failed to parse source file '{}' ({} parser error(s))",
            path.display(),
            ret.errors.len()
        )));
    }

    let project = match project {
        Some(project) => Some(project),
        None => {
            let mut index_collector = SourceIndexCollector::new(path, source);
            index_collector.visit_program(&ret.program);
            let mut files = BTreeMap::new();
            files.insert(path.to_path_buf(), index_collector.finish());
            let mut source_files = BTreeSet::new();
            source_files.insert(path.to_path_buf());
            Some(Arc::new(ProjectIndex {
                files,
                source_files,
                aliases: PathAliases::default(),
                packages: WorkspacePackages::default(),
            }))
        }
    };

    let mut collector = SourceUsageCollector::new(path, source, project);
    collector.visit_program(&ret.program);
    Ok(collector.finish())
}

fn discover_source_files(root: &Path) -> Result<Vec<PathBuf>> {
    if let Some(files) = discover_source_files_with_git(root)? {
        return Ok(files);
    }

    let mut files = Vec::new();
    collect_source_files_fallback(root, &mut files)?;
    files.sort();
    Ok(files)
}

fn discover_source_files_with_git(root: &Path) -> Result<Option<Vec<PathBuf>>> {
    let rev_parse = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["rev-parse", "--show-toplevel"])
        .output();
    let Ok(rev_parse) = rev_parse else {
        return Ok(None);
    };
    if !rev_parse.status.success() {
        return Ok(None);
    }

    let git_root = PathBuf::from(String::from_utf8_lossy(&rev_parse.stdout).trim());
    if git_root.as_os_str().is_empty() {
        return Ok(None);
    }

    let mut command = Command::new("git");
    command.arg("-C").arg(&git_root).args([
        "ls-files",
        "--cached",
        "--others",
        "--exclude-standard",
        "--",
    ]);

    let output = command.output()?;
    if !output.status.success() {
        return Ok(None);
    }

    let mut files = Vec::new();
    for line in String::from_utf8_lossy(&output.stdout).lines() {
        let path = git_root.join(line);
        if path.starts_with(root) && is_source_file(&path) {
            files.push(path);
        }
    }
    files.sort();
    files.dedup();
    Ok(Some(files))
}

fn collect_source_files_fallback(dir: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            if path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| FALLBACK_EXCLUDED_DIRS.contains(&name))
            {
                continue;
            }
            collect_source_files_fallback(&path, files)?;
        } else if file_type.is_file() && is_source_file(&path) {
            files.push(path);
        }
    }
    Ok(())
}

fn is_source_file(path: &Path) -> bool {
    if is_declaration_file(path) {
        return false;
    }

    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| SOURCE_EXTENSIONS.contains(&extension))
}

fn is_declaration_file(path: &Path) -> bool {
    let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
        return false;
    };
    file_name.ends_with(".d.ts") || file_name.ends_with(".d.mts") || file_name.ends_with(".d.cts")
}

fn is_allowed_source_file(path: &Path) -> bool {
    path.is_file()
        && is_source_file(path)
        && !path.components().any(|component| {
            let Component::Normal(name) = component else {
                return false;
            };
            name.to_str()
                .is_some_and(|name| FALLBACK_EXCLUDED_DIRS.contains(&name))
        })
}

impl ProjectIndex {
    fn build(root: &Path, paths: &[PathBuf]) -> Result<Self> {
        let aliases = PathAliases::load(root);
        let packages = WorkspacePackages::load(root);
        let mut project = Self {
            files: BTreeMap::new(),
            source_files: paths.iter().map(|path| normalize_path(path)).collect(),
            aliases,
            packages,
        };
        let mut queue: VecDeque<PathBuf> = paths.iter().map(|path| normalize_path(path)).collect();

        while let Some(path) = queue.pop_front() {
            let path = normalize_path(&path);
            if project.files.contains_key(&path) || !is_allowed_source_file(&path) {
                continue;
            }

            let source = fs::read_to_string(&path)?;
            let allocator = Allocator::default();
            let source_type = SourceType::from_path(&path).unwrap_or_default();
            let ret = Parser::new(&allocator, &source, source_type).parse();
            if !ret.errors.is_empty() {
                return Err(TransError::InvalidInput(format!(
                    "failed to parse source file '{}' ({} parser error(s))",
                    path.display(),
                    ret.errors.len()
                )));
            }

            let mut collector = SourceIndexCollector::new(&path, &source);
            collector.visit_program(&ret.program);
            let index = collector.finish();
            let dependency_sources: Vec<_> = index.dependency_sources.iter().cloned().collect();
            project.source_files.insert(path.clone());
            project.files.insert(path.clone(), index);

            for source in dependency_sources {
                let Some(dependency) = project.resolve_module(&path, &source) else {
                    continue;
                };
                if project.files.contains_key(&dependency)
                    || project.source_files.contains(&dependency)
                    || !is_allowed_source_file(&dependency)
                {
                    continue;
                }
                project.source_files.insert(dependency.clone());
                queue.push_back(dependency);
            }
        }

        Ok(project)
    }

    fn helper_for_import(&self, from: &Path, target: &ImportTarget) -> Option<HelperSummary> {
        self.helper_for_import_at_depth(from, target, 0)
    }

    fn translator_return_for_local(&self, path: &Path, name: &str) -> Option<TranslatorBinding> {
        self.translator_return_for_local_at_depth(path, name, 0)
    }

    fn translator_array_return_for_local(
        &self,
        path: &Path,
        name: &str,
    ) -> Option<TranslatorBinding> {
        self.translator_array_return_for_local_at_depth(path, name, 0)
    }

    fn translator_return_for_forward(
        &self,
        path: &Path,
        forward: &TranslatorReturnForward,
        depth: usize,
    ) -> Option<TranslatorBinding> {
        let file = self.files.get(path)?;
        match forward {
            TranslatorReturnForward::Local(name) => file
                .imports
                .get(name)
                .and_then(|target| {
                    self.translator_return_for_import_at_depth(path, target, depth + 1)
                })
                .or_else(|| self.translator_return_for_local_at_depth(path, name, depth + 1)),
            TranslatorReturnForward::NamespaceMember { namespace, name } => {
                let source = file.namespace_imports.get(namespace)?;
                self.translator_return_for_import_at_depth(
                    path,
                    &ImportTarget {
                        source: source.clone(),
                        imported: ImportedName::Named(name.clone()),
                    },
                    depth + 1,
                )
            }
            TranslatorReturnForward::ForwardCall {
                namespace, name, ..
            } => {
                if let Some(namespace) = namespace {
                    let source = file.namespace_imports.get(namespace)?;
                    let target = ImportTarget {
                        source: source.clone(),
                        imported: ImportedName::Named(name.clone()),
                    };
                    self.translator_return_for_import_at_depth(path, &target, depth + 1)
                        .or_else(|| {
                            self.translator_array_return_for_import_at_depth(
                                path,
                                &target,
                                depth + 1,
                            )
                        })
                } else if let Some(target) = file.imports.get(name) {
                    self.translator_return_for_import_at_depth(path, target, depth + 1)
                        .or_else(|| {
                            self.translator_array_return_for_import_at_depth(
                                path,
                                target,
                                depth + 1,
                            )
                        })
                } else {
                    self.translator_return_for_local_at_depth(path, name, depth + 1)
                        .or_else(|| {
                            self.translator_array_return_for_local_at_depth(path, name, depth + 1)
                        })
                }
            }
            TranslatorReturnForward::ParameterCall { .. } => None,
        }
    }

    fn translator_array_return_for_forward(
        &self,
        path: &Path,
        forward: &TranslatorReturnForward,
        depth: usize,
    ) -> Option<TranslatorBinding> {
        let file = self.files.get(path)?;
        match forward {
            TranslatorReturnForward::Local(name) => file
                .imports
                .get(name)
                .and_then(|target| {
                    self.translator_array_return_for_import_at_depth(path, target, depth + 1)
                        .or_else(|| {
                            self.translator_return_for_import_at_depth(path, target, depth + 1)
                        })
                })
                .or_else(|| self.translator_array_return_for_local_at_depth(path, name, depth + 1))
                .or_else(|| self.translator_return_for_local_at_depth(path, name, depth + 1)),
            TranslatorReturnForward::NamespaceMember { namespace, name } => {
                let source = file.namespace_imports.get(namespace)?;
                let target = ImportTarget {
                    source: source.clone(),
                    imported: ImportedName::Named(name.clone()),
                };
                self.translator_array_return_for_import_at_depth(path, &target, depth + 1)
                    .or_else(|| {
                        self.translator_return_for_import_at_depth(path, &target, depth + 1)
                    })
            }
            TranslatorReturnForward::ForwardCall {
                namespace, name, ..
            } => {
                if let Some(namespace) = namespace {
                    let source = file.namespace_imports.get(namespace)?;
                    let target = ImportTarget {
                        source: source.clone(),
                        imported: ImportedName::Named(name.clone()),
                    };
                    self.translator_return_for_import_at_depth(path, &target, depth + 1)
                        .or_else(|| {
                            self.translator_array_return_for_import_at_depth(
                                path,
                                &target,
                                depth + 1,
                            )
                        })
                } else if let Some(target) = file.imports.get(name) {
                    self.translator_return_for_import_at_depth(path, target, depth + 1)
                        .or_else(|| {
                            self.translator_array_return_for_import_at_depth(
                                path,
                                target,
                                depth + 1,
                            )
                        })
                } else {
                    self.translator_return_for_local_at_depth(path, name, depth + 1)
                        .or_else(|| {
                            self.translator_array_return_for_local_at_depth(path, name, depth + 1)
                        })
                }
            }
            TranslatorReturnForward::ParameterCall { .. } => None,
        }
    }

    fn translator_array_return_params_for_forward(
        &self,
        path: &Path,
        forward: &TranslatorReturnForward,
        depth: usize,
    ) -> ParamIndexes {
        let Some(file) = self.files.get(path) else {
            return BTreeSet::new();
        };
        match forward {
            TranslatorReturnForward::Local(name) => file
                .imports
                .get(name)
                .map(|target| {
                    self.translator_array_return_params_for_import_at_depth(path, target, depth + 1)
                })
                .unwrap_or_else(|| {
                    self.translator_array_return_params_for_local_at_depth(path, name, depth + 1)
                }),
            TranslatorReturnForward::NamespaceMember { namespace, name } => file
                .namespace_imports
                .get(namespace)
                .map(|source| {
                    self.translator_array_return_params_for_import_at_depth(
                        path,
                        &ImportTarget {
                            source: source.clone(),
                            imported: ImportedName::Named(name.clone()),
                        },
                        depth + 1,
                    )
                })
                .unwrap_or_default(),
            TranslatorReturnForward::ForwardCall {
                namespace,
                name,
                argument_params,
                ..
            } => {
                let resolved = if let Some(namespace) = namespace {
                    file.namespace_imports
                        .get(namespace)
                        .map(|source| {
                            self.translator_array_return_params_for_import_at_depth(
                                path,
                                &ImportTarget {
                                    source: source.clone(),
                                    imported: ImportedName::Named(name.clone()),
                                },
                                depth + 1,
                            )
                        })
                        .unwrap_or_default()
                } else if let Some(target) = file.imports.get(name) {
                    self.translator_array_return_params_for_import_at_depth(path, target, depth + 1)
                } else {
                    self.translator_array_return_params_for_local_at_depth(path, name, depth + 1)
                };
                resolved
                    .into_iter()
                    .filter_map(|index| argument_params.get(index).copied().flatten())
                    .collect()
            }
            TranslatorReturnForward::ParameterCall { .. } => BTreeSet::new(),
        }
    }

    fn translator_return_parameter_calls_for_local(
        &self,
        path: &Path,
        name: &str,
    ) -> BTreeSet<TranslatorReturnForward> {
        self.translator_return_parameter_calls_for_local_at_depth(path, name, 0)
    }

    fn translator_return_parameter_calls_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> BTreeSet<TranslatorReturnForward> {
        if depth > 16 {
            return BTreeSet::new();
        }
        let Some(file) = self.files.get(path) else {
            return BTreeSet::new();
        };
        let Some(forwards) = file.translator_return_forwards.get(name) else {
            return BTreeSet::new();
        };
        let mut calls = BTreeSet::new();
        for forward in forwards {
            match forward {
                TranslatorReturnForward::ParameterCall { .. } => {
                    calls.insert(forward.clone());
                }
                TranslatorReturnForward::Local(name) => {
                    let resolved = file
                        .imports
                        .get(name)
                        .map(|target| {
                            self.translator_return_parameter_calls_for_import_at_depth(
                                path,
                                target,
                                depth + 1,
                            )
                        })
                        .unwrap_or_else(|| {
                            self.translator_return_parameter_calls_for_local_at_depth(
                                path,
                                name,
                                depth + 1,
                            )
                        });
                    calls.extend(resolved);
                }
                TranslatorReturnForward::NamespaceMember { namespace, name } => {
                    if let Some(source) = file.namespace_imports.get(namespace) {
                        calls.extend(self.translator_return_parameter_calls_for_import_at_depth(
                            path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        ));
                    }
                }
                TranslatorReturnForward::ForwardCall {
                    namespace,
                    name,
                    argument_params,
                    ..
                } => {
                    let resolved = if let Some(namespace) = namespace {
                        file.namespace_imports
                            .get(namespace)
                            .map(|source| {
                                self.translator_return_parameter_calls_for_import_at_depth(
                                    path,
                                    &ImportTarget {
                                        source: source.clone(),
                                        imported: ImportedName::Named(name.clone()),
                                    },
                                    depth + 1,
                                )
                            })
                            .unwrap_or_default()
                    } else if let Some(target) = file.imports.get(name) {
                        self.translator_return_parameter_calls_for_import_at_depth(
                            path,
                            target,
                            depth + 1,
                        )
                    } else {
                        self.translator_return_parameter_calls_for_local_at_depth(
                            path,
                            name,
                            depth + 1,
                        )
                    };
                    calls.extend(resolved.into_iter().filter_map(|call| {
                        let TranslatorReturnForward::ParameterCall {
                            param_index,
                            binding,
                        } = call
                        else {
                            return None;
                        };
                        Some(TranslatorReturnForward::ParameterCall {
                            param_index: *argument_params.get(param_index)?.as_ref()?,
                            binding,
                        })
                    }));
                }
            }
        }
        calls
    }

    fn translator_return_parameter_calls_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> BTreeSet<TranslatorReturnForward> {
        self.translator_return_parameter_calls_for_import_at_depth(from, target, 0)
    }

    fn translator_return_parameter_calls_for_namespace_member(
        &self,
        from: &Path,
        namespace: &str,
        name: &str,
    ) -> BTreeSet<TranslatorReturnForward> {
        let Some(source) = self
            .files
            .get(from)
            .and_then(|file| file.namespace_imports.get(namespace))
        else {
            return BTreeSet::new();
        };
        self.translator_return_parameter_calls_for_import_at_depth(
            from,
            &ImportTarget {
                source: source.clone(),
                imported: ImportedName::Named(name.to_string()),
            },
            0,
        )
    }

    fn translator_return_parameter_calls_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> BTreeSet<TranslatorReturnForward> {
        if depth > 16 {
            return BTreeSet::new();
        }
        let Some(path) = self.resolve_module(from, &target.source) else {
            return BTreeSet::new();
        };
        let Some(file) = self.files.get(&path) else {
            return BTreeSet::new();
        };
        match &target.imported {
            ImportedName::Named(name) => {
                if let Some(local) = file.translator_return_export_locals.get(name) {
                    return self.translator_return_parameter_calls_for_local_at_depth(
                        &path,
                        local,
                        depth + 1,
                    );
                }
                if let Some(target) = file.re_exports.get(name) {
                    return self.translator_return_parameter_calls_for_import_at_depth(
                        &path,
                        target,
                        depth + 1,
                    );
                }
                file.star_re_exports
                    .iter()
                    .find_map(|source| {
                        let calls = self.translator_return_parameter_calls_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        );
                        (!calls.is_empty()).then_some(calls)
                    })
                    .unwrap_or_default()
            }
            ImportedName::Default => {
                if let Some(local) = &file.default_local_export {
                    let calls = self.translator_return_parameter_calls_for_local_at_depth(
                        &path,
                        local,
                        depth + 1,
                    );
                    if !calls.is_empty() {
                        return calls;
                    }
                }
                let calls = file
                    .default_translator_return_forwards
                    .iter()
                    .filter(|forward| {
                        matches!(forward, TranslatorReturnForward::ParameterCall { .. })
                    })
                    .cloned()
                    .collect::<BTreeSet<_>>();
                if !calls.is_empty() {
                    return calls;
                }
                file.re_exports
                    .get("default")
                    .map(|target| {
                        self.translator_return_parameter_calls_for_import_at_depth(
                            &path,
                            target,
                            depth + 1,
                        )
                    })
                    .unwrap_or_default()
            }
        }
    }

    fn translator_return_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> Option<TranslatorBinding> {
        if depth > 16 {
            return None;
        }
        let file = self.files.get(path)?;
        let mut bindings = file
            .translator_return_helpers
            .get(name)
            .cloned()
            .into_iter()
            .collect::<Vec<_>>();
        if let Some(forwards) = file.translator_return_forwards.get(name) {
            let resolved: Vec<_> = forwards
                .iter()
                .map(|forward| self.translator_return_for_forward(path, forward, depth + 1))
                .collect();
            if !bindings.is_empty() || resolved.iter().any(Option::is_some) {
                bindings.extend(resolved.into_iter().map(|binding| {
                    binding.unwrap_or_else(|| {
                        translator_binding_from_namespace_arg(NamespaceArg::Dynamic)
                    })
                }));
            }
        }
        merge_translator_binding_iter(bindings)
    }

    fn translator_return_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<TranslatorBinding> {
        self.translator_return_for_import_at_depth(from, target, 0)
    }

    fn translator_return_for_namespace_member(
        &self,
        from: &Path,
        namespace: &str,
        name: &str,
    ) -> Option<TranslatorBinding> {
        let source = self.files.get(from)?.namespace_imports.get(namespace)?;
        self.translator_return_for_import_at_depth(
            from,
            &ImportTarget {
                source: source.clone(),
                imported: ImportedName::Named(name.to_string()),
            },
            0,
        )
    }

    fn translator_return_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<TranslatorBinding> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .translator_return_export_locals
                .get(name)
                .and_then(|local| {
                    self.translator_return_for_local_at_depth(&path, local, depth + 1)
                })
                .or_else(|| file.named_translator_return_exports.get(name).cloned())
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.translator_return_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.translator_return_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file
                .default_local_export
                .as_ref()
                .and_then(|local| {
                    self.translator_return_for_local_at_depth(&path, local, depth + 1)
                })
                .or_else(|| {
                    let mut bindings: Vec<_> = file
                        .default_translator_return_export
                        .clone()
                        .into_iter()
                        .collect();
                    let resolved: Vec<_> = file
                        .default_translator_return_forwards
                        .iter()
                        .map(|forward| {
                            self.translator_return_for_forward(&path, forward, depth + 1)
                        })
                        .collect();
                    if !bindings.is_empty() || resolved.iter().any(Option::is_some) {
                        bindings.extend(resolved.into_iter().map(|binding| {
                            binding.unwrap_or_else(|| {
                                translator_binding_from_namespace_arg(NamespaceArg::Dynamic)
                            })
                        }));
                    }
                    merge_translator_binding_iter(bindings)
                })
                .or_else(|| {
                    file.re_exports.get("default").and_then(|target| {
                        self.translator_return_for_import_at_depth(&path, target, depth + 1)
                    })
                }),
        }
    }

    fn translator_array_return_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> Option<TranslatorBinding> {
        if depth > 16 {
            return None;
        }
        let file = self.files.get(path)?;
        let mut bindings = file
            .translator_array_return_helpers
            .get(name)
            .cloned()
            .into_iter()
            .collect::<Vec<_>>();
        if let Some(forwards) = file.translator_return_forwards.get(name) {
            bindings.extend(forwards.iter().filter_map(|forward| {
                self.translator_array_return_for_forward(path, forward, depth + 1)
            }));
        }
        merge_translator_binding_iter(bindings)
    }

    fn translator_array_return_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<TranslatorBinding> {
        self.translator_array_return_for_import_at_depth(from, target, 0)
    }

    fn translator_array_return_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<TranslatorBinding> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .translator_return_export_locals
                .get(name)
                .and_then(|local| {
                    self.translator_array_return_for_local_at_depth(&path, local, depth + 1)
                })
                .or_else(|| {
                    file.named_translator_array_return_exports
                        .get(name)
                        .cloned()
                })
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.translator_array_return_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.translator_array_return_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file
                .default_local_export
                .as_ref()
                .and_then(|local| {
                    self.translator_array_return_for_local_at_depth(&path, local, depth + 1)
                })
                .or_else(|| file.default_translator_array_return_export.clone())
                .or_else(|| {
                    file.default_translator_return_forwards
                        .iter()
                        .find_map(|forward| {
                            self.translator_array_return_for_forward(&path, forward, depth + 1)
                        })
                })
                .or_else(|| {
                    file.re_exports.get("default").and_then(|target| {
                        self.translator_array_return_for_import_at_depth(&path, target, depth + 1)
                    })
                }),
        }
    }

    fn translator_array_return_params_for_local(&self, path: &Path, name: &str) -> ParamIndexes {
        self.translator_array_return_params_for_local_at_depth(path, name, 0)
    }

    fn translator_array_return_params_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> ParamIndexes {
        if depth > 16 {
            return BTreeSet::new();
        }
        let Some(file) = self.files.get(path) else {
            return BTreeSet::new();
        };
        let mut indexes = file
            .translator_array_return_params
            .get(name)
            .cloned()
            .unwrap_or_default();
        if let Some(forwards) = file.translator_return_forwards.get(name) {
            for forward in forwards {
                indexes.extend(self.translator_array_return_params_for_forward(
                    path,
                    forward,
                    depth + 1,
                ));
            }
        }
        indexes
    }

    fn translator_array_return_params_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> ParamIndexes {
        self.translator_array_return_params_for_import_at_depth(from, target, 0)
    }

    fn translator_array_return_params_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> ParamIndexes {
        if depth > 16 {
            return BTreeSet::new();
        }
        let Some(path) = self.resolve_module(from, &target.source) else {
            return BTreeSet::new();
        };
        let Some(file) = self.files.get(&path) else {
            return BTreeSet::new();
        };
        match &target.imported {
            ImportedName::Named(name) => file
                .translator_return_export_locals
                .get(name)
                .map(|local| {
                    self.translator_array_return_params_for_local_at_depth(&path, local, depth + 1)
                })
                .or_else(|| file.named_translator_array_return_params.get(name).cloned())
                .or_else(|| {
                    file.re_exports.get(name).map(|target| {
                        self.translator_array_return_params_for_import_at_depth(
                            &path,
                            target,
                            depth + 1,
                        )
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        let indexes = self.translator_array_return_params_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        );
                        (!indexes.is_empty()).then_some(indexes)
                    })
                })
                .unwrap_or_default(),
            ImportedName::Default => file
                .default_local_export
                .as_ref()
                .map(|local| {
                    self.translator_array_return_params_for_local_at_depth(&path, local, depth + 1)
                })
                .filter(|indexes| !indexes.is_empty())
                .unwrap_or_else(|| file.default_translator_array_return_params.clone()),
        }
    }

    fn helper_for_local(&self, path: &Path, name: &str) -> Option<HelperSummary> {
        self.helper_for_local_at_depth(path, name, 0)
    }

    fn helper_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> Option<HelperSummary> {
        if depth > 16 {
            return None;
        }
        let summary = self.files.get(path)?.helpers.get(name)?.clone();
        Some(self.expand_helper_summary(path, summary, depth + 1))
    }

    fn expand_helper_summary(
        &self,
        path: &Path,
        mut summary: HelperSummary,
        depth: usize,
    ) -> HelperSummary {
        let forwards = std::mem::take(&mut summary.forwards);
        for forward in forwards {
            let target = if depth <= 16 {
                self.files.get(path).and_then(|file| {
                    if file.helpers.contains_key(&forward.callee) {
                        self.helper_for_local_at_depth(path, &forward.callee, depth + 1)
                    } else {
                        file.imports.get(&forward.callee).and_then(|target| {
                            self.helper_for_import_at_depth(path, target, depth + 1)
                        })
                    }
                })
            } else {
                None
            };

            if forward.argument_array.safe_layout {
                if let Some(target) = target {
                    for usage in target.param_usages {
                        let Some(indexes) = forward.argument_array.bindings.get(usage.param_index)
                        else {
                            continue;
                        };
                        for param_index in indexes {
                            summary.param_usages.push(HelperParamUsage {
                                param_index: *param_index,
                                param_path: usage.param_path.clone(),
                                keys: usage.keys.clone(),
                                query: usage.query.clone(),
                                translator_like: usage.translator_like,
                                direct_translator: usage.direct_translator,
                            });
                        }
                    }
                    continue;
                }
            }

            for param_index in forward.fallback_params {
                summary.param_usages.push(HelperParamUsage {
                    param_index,
                    param_path: Vec::new(),
                    keys: None,
                    query: None,
                    translator_like: true,
                    direct_translator: false,
                });
            }
        }
        summary
    }

    fn helper_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<HelperSummary> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => {
                if let Some(summary) = file.named_exports.get(name).cloned() {
                    Some(self.expand_helper_summary(&path, summary, depth + 1))
                } else {
                    file.re_exports
                        .get(name)
                        .and_then(|target| {
                            self.helper_for_import_at_depth(&path, target, depth + 1)
                        })
                        .or_else(|| {
                            file.star_re_exports.iter().find_map(|source| {
                                self.helper_for_import_at_depth(
                                    &path,
                                    &ImportTarget {
                                        source: source.clone(),
                                        imported: ImportedName::Named(name.clone()),
                                    },
                                    depth + 1,
                                )
                            })
                        })
                }
            }
            ImportedName::Default => file
                .default_export
                .clone()
                .map(|summary| self.expand_helper_summary(&path, summary, depth + 1))
                .or_else(|| {
                    file.re_exports.get("default").and_then(|target| {
                        self.helper_for_import_at_depth(&path, target, depth + 1)
                    })
                }),
        }
    }

    fn jsx_component_for_name(&self, from: &Path, name: &str) -> Option<JsxComponentSummary> {
        self.jsx_component_for_local_at_depth(from, name, 0)
    }

    fn jsx_component_for_local_at_depth(
        &self,
        from: &Path,
        name: &str,
        depth: usize,
    ) -> Option<JsxComponentSummary> {
        if depth > 16 {
            return None;
        }
        let file = self.files.get(from)?;
        if let Some(summary) = file.jsx_components.get(name) {
            return self.expand_jsx_component_summary(from, summary.clone(), depth + 1);
        }
        if let Some(target) = file.imports.get(name) {
            let (path, summary) = self.jsx_component_target_for_import(from, target, depth + 1)?;
            return self.expand_jsx_component_summary(&path, summary, depth + 1);
        }
        let aliases = file.jsx_aliases.get(name)?;
        let mut merged = JsxComponentSummary::default();
        for alias in aliases {
            let summary = match &alias.namespace {
                Some(namespace) => self.jsx_component_for_namespace_member_at_depth(
                    from,
                    namespace,
                    &alias.name,
                    depth + 1,
                ),
                None => self.jsx_component_for_local_at_depth(from, &alias.name, depth + 1),
            }?;
            merged.usages.extend(summary.usages);
            merged.forwards.extend(summary.forwards);
        }
        Some(merged)
    }

    fn jsx_component_for_namespace_member(
        &self,
        from: &Path,
        namespace: &str,
        name: &str,
    ) -> Option<JsxComponentSummary> {
        self.jsx_component_for_namespace_member_at_depth(from, namespace, name, 0)
    }

    fn jsx_component_for_namespace_member_at_depth(
        &self,
        from: &Path,
        namespace: &str,
        name: &str,
        depth: usize,
    ) -> Option<JsxComponentSummary> {
        if depth > 16 {
            return None;
        }
        let file = self.files.get(from)?;
        let source = file.namespace_imports.get(namespace)?;
        let (path, summary) = self.jsx_component_target_for_import(
            from,
            &ImportTarget {
                source: source.clone(),
                imported: ImportedName::Named(name.to_string()),
            },
            depth + 1,
        )?;
        self.expand_jsx_component_summary(&path, summary, depth + 1)
    }

    fn jsx_component_target_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<(PathBuf, JsxComponentSummary)> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .named_jsx_exports
                .get(name)
                .cloned()
                .map(|summary| (path.clone(), summary))
                .or_else(|| {
                    file.jsx_export_locals.get(name).and_then(|local| {
                        self.jsx_component_for_local_at_depth(&path, local, depth + 1)
                            .map(|summary| (path.clone(), summary))
                    })
                })
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.jsx_component_target_for_import(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.jsx_component_target_for_import(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file
                .default_jsx_export
                .clone()
                .map(|summary| (path.clone(), summary))
                .or_else(|| {
                    file.default_local_export.as_ref().and_then(|local| {
                        self.jsx_component_for_local_at_depth(&path, local, depth + 1)
                            .map(|summary| (path.clone(), summary))
                    })
                })
                .or_else(|| {
                    file.re_exports.get("default").and_then(|target| {
                        self.jsx_component_target_for_import(&path, target, depth + 1)
                    })
                }),
        }
    }

    fn expand_jsx_component_summary(
        &self,
        path: &Path,
        summary: JsxComponentSummary,
        depth: usize,
    ) -> Option<JsxComponentSummary> {
        self.expand_jsx_component_summary_with_active(
            path,
            summary,
            depth,
            &mut BTreeSet::new(),
            &mut BTreeMap::new(),
        )
    }

    fn expand_jsx_component_summary_with_active(
        &self,
        path: &Path,
        mut summary: JsxComponentSummary,
        depth: usize,
        active: &mut BTreeSet<(PathBuf, String)>,
        cache: &mut BTreeMap<(PathBuf, String), Option<JsxComponentSummary>>,
    ) -> Option<JsxComponentSummary> {
        if depth > 16 {
            return None;
        }
        let forwards = std::mem::take(&mut summary.forwards);
        for forward in forwards {
            let edge_name = forward
                .component_namespace
                .as_ref()
                .map(|namespace| format!("{namespace}.{}", forward.component_name))
                .unwrap_or_else(|| forward.component_name.clone());
            let edge = (path.to_path_buf(), edge_name);
            if !active.insert(edge.clone()) {
                continue;
            }
            let Some(file) = self.files.get(path) else {
                active.remove(&edge);
                continue;
            };
            let child = if let Some(namespace) = &forward.component_namespace {
                file.namespace_imports.get(namespace).and_then(|source| {
                    self.jsx_component_target_for_import(
                        path,
                        &ImportTarget {
                            source: source.clone(),
                            imported: ImportedName::Named(forward.component_name.clone()),
                        },
                        depth + 1,
                    )
                })
            } else if let Some(child) = file.jsx_components.get(&forward.component_name) {
                Some((path.to_path_buf(), child.clone()))
            } else if file.jsx_aliases.contains_key(&forward.component_name) {
                self.jsx_component_for_local_at_depth(path, &forward.component_name, depth + 1)
                    .map(|summary| (path.to_path_buf(), summary))
            } else {
                file.imports
                    .get(&forward.component_name)
                    .and_then(|target| {
                        self.jsx_component_target_for_import(path, target, depth + 1)
                    })
            };
            let Some((child_path, child_summary)) = child else {
                active.remove(&edge);
                summary.usages.push(JsxPropUsage {
                    prop_name: forward.prop_name,
                    keys: None,
                    query: None,
                    translator_like: false,
                });
                continue;
            };
            let cache_key = edge.clone();
            let child_summary = if let Some(summary) = cache.get(&cache_key) {
                summary.clone()
            } else {
                let summary = self.expand_jsx_component_summary_with_active(
                    &child_path,
                    child_summary,
                    depth + 1,
                    active,
                    cache,
                );
                cache.insert(cache_key, summary.clone());
                summary
            };
            active.remove(&edge);
            let Some(child_summary) = child_summary else {
                continue;
            };
            summary.usages.extend(
                child_summary
                    .usages
                    .into_iter()
                    .filter(|usage| usage.prop_name == forward.target_prop)
                    .map(|usage| JsxPropUsage {
                        prop_name: forward.prop_name.clone(),
                        keys: usage.keys,
                        query: usage.query,
                        translator_like: usage.translator_like,
                    }),
            );
        }
        Some(summary)
    }

    fn return_helper_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<FiniteStrings> {
        self.return_helper_for_import_at_depth(from, target, 0)
    }

    fn return_helper_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<FiniteStrings> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .named_return_exports
                .get(name)
                .cloned()
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.return_helper_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.return_helper_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file.default_return_export.clone().or_else(|| {
                file.re_exports.get("default").and_then(|target| {
                    self.return_helper_for_import_at_depth(&path, target, depth + 1)
                })
            }),
        }
    }

    fn wrapper_return_for_local(&self, path: &Path, name: &str) -> bool {
        self.wrapper_return_for_local_at_depth(path, name, 0)
    }

    fn wrapper_array_indexes_for_local(&self, path: &Path, name: &str) -> Option<BTreeSet<usize>> {
        self.wrapper_array_indexes_for_local_at_depth(path, name, 0)
    }

    fn wrapper_array_indexes_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> Option<BTreeSet<usize>> {
        if depth > 16 {
            return None;
        }
        let file = self.files.get(path)?;
        let mut indexes = file
            .wrapper_array_return_indexes
            .get(name)
            .cloned()
            .unwrap_or_default();
        if let Some(candidates) = file.wrapper_array_index_forwards.get(name) {
            for (index, forwards) in candidates {
                let resolves = forwards.iter().any(|forward| match forward {
                    TranslatorReturnForward::Local(callee)
                    | TranslatorReturnForward::ForwardCall {
                        namespace: None,
                        name: callee,
                        ..
                    } => {
                        self.wrapper_return_for_local_at_depth(path, callee, depth + 1)
                            || file.imports.get(callee).is_some_and(|target| {
                                self.wrapper_return_for_import_at_depth(path, target, depth + 1)
                            })
                    }
                    TranslatorReturnForward::NamespaceMember { namespace, name }
                    | TranslatorReturnForward::ForwardCall {
                        namespace: Some(namespace),
                        name,
                        ..
                    } => file.namespace_imports.get(namespace).is_some_and(|source| {
                        self.wrapper_return_for_import_at_depth(
                            path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    }),
                    TranslatorReturnForward::ParameterCall { .. } => false,
                });
                if resolves {
                    indexes.insert(*index);
                }
            }
        }
        if let Some(bound_calls) = file.wrapper_bound_calls.get(name) {
            for bound in bound_calls {
                let parameter_indexes = if let Some(namespace) = &bound.namespace {
                    file.namespace_imports
                        .get(namespace)
                        .map(|source| {
                            self.wrapper_array_parameter_indexes_for_import_at_depth(
                                path,
                                &ImportTarget {
                                    source: source.clone(),
                                    imported: ImportedName::Named(bound.name.clone()),
                                },
                                depth + 1,
                            )
                        })
                        .unwrap_or_default()
                } else if let Some(target) = file.imports.get(&bound.name) {
                    self.wrapper_array_parameter_indexes_for_import_at_depth(
                        path,
                        target,
                        depth + 1,
                    )
                } else {
                    self.wrapper_array_parameter_indexes_for_local_at_depth(
                        path,
                        &bound.name,
                        depth + 1,
                    )
                };
                for (index, params) in parameter_indexes {
                    if bound
                        .unknown_from
                        .is_some_and(|from| params.iter().any(|param| *param >= from))
                        || params.into_iter().any(|param| {
                            bound.arguments.get(param).is_some_and(|forwards| {
                                forwards.iter().any(|forward| match forward {
                                    TranslatorReturnForward::Local(name)
                                    | TranslatorReturnForward::ForwardCall {
                                        namespace: None,
                                        name,
                                        ..
                                    } => {
                                        self.wrapper_return_for_local_at_depth(
                                            path,
                                            name,
                                            depth + 1,
                                        ) || file.imports.get(name).is_some_and(|target| {
                                            self.wrapper_return_for_import_at_depth(
                                                path,
                                                target,
                                                depth + 1,
                                            )
                                        })
                                    }
                                    TranslatorReturnForward::NamespaceMember {
                                        namespace,
                                        name,
                                    }
                                    | TranslatorReturnForward::ForwardCall {
                                        namespace: Some(namespace),
                                        name,
                                        ..
                                    } => file.namespace_imports.get(namespace).is_some_and(
                                        |source| {
                                            self.wrapper_return_for_import_at_depth(
                                                path,
                                                &ImportTarget {
                                                    source: source.clone(),
                                                    imported: ImportedName::Named(name.clone()),
                                                },
                                                depth + 1,
                                            )
                                        },
                                    ),
                                    TranslatorReturnForward::ParameterCall { .. } => false,
                                })
                            })
                        })
                    {
                        indexes.insert(index);
                    }
                }
            }
        }
        if let Some(forwards) = file.wrapper_return_forwards.get(name) {
            indexes.extend(self.wrapper_concrete_indexes_from_forwards(path, forwards, depth));
        }
        if !indexes.is_empty() {
            return Some(indexes);
        }
        file.wrapper_return_forwards
            .get(name)?
            .iter()
            .find_map(|forward| match forward {
                TranslatorReturnForward::Local(callee)
                | TranslatorReturnForward::ForwardCall {
                    namespace: None,
                    name: callee,
                    ..
                } => self
                    .wrapper_array_indexes_for_local_at_depth(path, callee, depth + 1)
                    .or_else(|| {
                        file.imports.get(callee).and_then(|target| {
                            self.wrapper_array_indexes_for_import_at_depth(path, target, depth + 1)
                        })
                    }),
                _ => None,
            })
    }

    fn wrapper_concrete_indexes_from_forwards(
        &self,
        path: &Path,
        forwards: &BTreeSet<TranslatorReturnForward>,
        depth: usize,
    ) -> BTreeSet<usize> {
        let Some(file) = self.files.get(path) else {
            return BTreeSet::new();
        };
        let mut indexes = BTreeSet::new();
        for forward in forwards {
            let TranslatorReturnForward::ForwardCall {
                namespace,
                name: target_name,
                argument_targets,
                wrapper_arguments,
                ..
            } = forward
            else {
                continue;
            };
            let parameter_indexes = if let Some(namespace) = namespace {
                file.namespace_imports
                    .get(namespace)
                    .map(|source| {
                        self.wrapper_array_parameter_indexes_for_import_at_depth(
                            path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(target_name.clone()),
                            },
                            depth + 1,
                        )
                    })
                    .unwrap_or_default()
            } else if let Some(target) = file.imports.get(target_name) {
                self.wrapper_array_parameter_indexes_for_import_at_depth(path, target, depth + 1)
            } else {
                self.wrapper_array_parameter_indexes_for_local_at_depth(
                    path,
                    target_name,
                    depth + 1,
                )
            };
            for (index, params) in parameter_indexes {
                let concrete = params.into_iter().any(|param| {
                    wrapper_arguments.contains(&param)
                        || argument_targets.get(&param).is_some_and(|targets| {
                            targets.iter().any(|target| {
                                self.wrapper_callable_target_resolution_at_depth(
                                    path,
                                    target,
                                    depth + 1,
                                )
                                .is_some_and(|target| target.direct || !target.indexes.is_empty())
                            })
                        })
                });
                if concrete {
                    indexes.insert(index);
                }
            }
        }
        indexes
    }

    fn wrapper_array_indexes_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<BTreeSet<usize>> {
        self.wrapper_array_indexes_for_import_at_depth(from, target, 0)
    }

    fn wrapper_array_indexes_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<BTreeSet<usize>> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .translator_return_export_locals
                .get(name)
                .and_then(|local| {
                    self.wrapper_array_indexes_for_local_at_depth(&path, local, depth + 1)
                })
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.wrapper_array_indexes_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.wrapper_array_indexes_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => {
                let mut indexes = file.default_wrapper_array_return_indexes.clone();
                for (index, forwards) in &file.default_wrapper_array_index_forwards {
                    if forwards.iter().any(|forward| match forward {
                        TranslatorReturnForward::Local(callee)
                        | TranslatorReturnForward::ForwardCall {
                            namespace: None,
                            name: callee,
                            ..
                        } => {
                            self.wrapper_return_for_local_at_depth(&path, callee, depth + 1)
                                || file.imports.get(callee).is_some_and(|target| {
                                    self.wrapper_return_for_import_at_depth(
                                        &path,
                                        target,
                                        depth + 1,
                                    )
                                })
                        }
                        TranslatorReturnForward::NamespaceMember { namespace, name }
                        | TranslatorReturnForward::ForwardCall {
                            namespace: Some(namespace),
                            name,
                            ..
                        } => file.namespace_imports.get(namespace).is_some_and(|source| {
                            self.wrapper_return_for_import_at_depth(
                                &path,
                                &ImportTarget {
                                    source: source.clone(),
                                    imported: ImportedName::Named(name.clone()),
                                },
                                depth + 1,
                            )
                        }),
                        TranslatorReturnForward::ParameterCall { .. } => false,
                    }) {
                        indexes.insert(*index);
                    }
                }
                indexes.extend(self.wrapper_concrete_indexes_from_forwards(
                    &path,
                    &file.default_wrapper_return_forwards,
                    depth + 1,
                ));
                if !indexes.is_empty() {
                    Some(indexes)
                } else {
                    file.default_local_export
                        .as_ref()
                        .and_then(|local| {
                            self.wrapper_array_indexes_for_local_at_depth(&path, local, depth + 1)
                        })
                        .or_else(|| {
                            file.re_exports.get("default").and_then(|target| {
                                self.wrapper_array_indexes_for_import_at_depth(
                                    &path,
                                    target,
                                    depth + 1,
                                )
                            })
                        })
                }
            }
        }
    }

    fn wrapper_array_parameter_indexes_for_local(
        &self,
        path: &Path,
        name: &str,
    ) -> BTreeMap<usize, BTreeSet<usize>> {
        self.wrapper_array_parameter_indexes_for_local_at_depth(path, name, 0)
    }

    fn wrapper_array_parameter_indexes_for_local_at_depth(
        &self,
        path: &Path,
        name: &str,
        depth: usize,
    ) -> BTreeMap<usize, BTreeSet<usize>> {
        if depth > 16 {
            return BTreeMap::new();
        }
        let Some(file) = self.files.get(path) else {
            return BTreeMap::new();
        };
        let mut indexes = file
            .wrapper_array_index_forwards
            .get(name)
            .into_iter()
            .flat_map(|forwards| forwards.iter())
            .filter_map(|(index, candidates)| {
                let params = candidates
                    .iter()
                    .filter_map(|candidate| match candidate {
                        TranslatorReturnForward::ParameterCall { param_index, .. } => {
                            Some(*param_index)
                        }
                        _ => None,
                    })
                    .collect::<BTreeSet<_>>();
                (!params.is_empty()).then_some((*index, params))
            })
            .collect::<BTreeMap<_, _>>();
        if let Some(bound_calls) = file.wrapper_bound_calls.get(name) {
            for bound in bound_calls {
                if bound.unknown_from.is_some() {
                    continue;
                }
                let resolved = if let Some(namespace) = &bound.namespace {
                    file.namespace_imports
                        .get(namespace)
                        .map(|source| {
                            self.wrapper_array_parameter_indexes_for_import_at_depth(
                                path,
                                &ImportTarget {
                                    source: source.clone(),
                                    imported: ImportedName::Named(bound.name.clone()),
                                },
                                depth + 1,
                            )
                        })
                        .unwrap_or_default()
                } else if let Some(target) = file.imports.get(&bound.name) {
                    self.wrapper_array_parameter_indexes_for_import_at_depth(
                        path,
                        target,
                        depth + 1,
                    )
                } else {
                    self.wrapper_array_parameter_indexes_for_local_at_depth(
                        path,
                        &bound.name,
                        depth + 1,
                    )
                };
                for (index, params) in resolved {
                    for param in params
                        .into_iter()
                        .filter(|param| *param >= bound.arguments.len())
                    {
                        indexes
                            .entry(index)
                            .or_default()
                            .insert(param - bound.arguments.len());
                    }
                }
            }
            return indexes;
        }
        let Some(forwards) = file.wrapper_return_forwards.get(name) else {
            return indexes;
        };
        self.extend_wrapper_parameter_indexes_from_forwards(path, forwards, depth, &mut indexes);
        indexes
    }

    fn extend_wrapper_parameter_indexes_from_forwards(
        &self,
        path: &Path,
        forwards: &BTreeSet<TranslatorReturnForward>,
        depth: usize,
        indexes: &mut BTreeMap<usize, BTreeSet<usize>>,
    ) {
        let Some(file) = self.files.get(path) else {
            return;
        };
        for forward in forwards {
            let (resolved, argument_params) = match forward {
                TranslatorReturnForward::Local(callee) => {
                    let resolved = file.imports.get(callee).map_or_else(
                        || {
                            self.wrapper_array_parameter_indexes_for_local_at_depth(
                                path,
                                callee,
                                depth + 1,
                            )
                        },
                        |target| {
                            self.wrapper_array_parameter_indexes_for_import_at_depth(
                                path,
                                target,
                                depth + 1,
                            )
                        },
                    );
                    (resolved, None)
                }
                TranslatorReturnForward::NamespaceMember { namespace, name } => {
                    let resolved = file
                        .namespace_imports
                        .get(namespace)
                        .map(|source| {
                            self.wrapper_array_parameter_indexes_for_import_at_depth(
                                path,
                                &ImportTarget {
                                    source: source.clone(),
                                    imported: ImportedName::Named(name.clone()),
                                },
                                depth + 1,
                            )
                        })
                        .unwrap_or_default();
                    (resolved, None)
                }
                TranslatorReturnForward::ForwardCall {
                    namespace,
                    name,
                    argument_params,
                    argument_targets,
                    wrapper_arguments: _,
                } => {
                    let resolved = if let Some(namespace) = namespace {
                        file.namespace_imports
                            .get(namespace)
                            .map(|source| {
                                self.wrapper_array_parameter_indexes_for_import_at_depth(
                                    path,
                                    &ImportTarget {
                                        source: source.clone(),
                                        imported: ImportedName::Named(name.clone()),
                                    },
                                    depth + 1,
                                )
                            })
                            .unwrap_or_default()
                    } else if let Some(target) = file.imports.get(name) {
                        self.wrapper_array_parameter_indexes_for_import_at_depth(
                            path,
                            target,
                            depth + 1,
                        )
                    } else {
                        self.wrapper_array_parameter_indexes_for_local_at_depth(
                            path,
                            name,
                            depth + 1,
                        )
                    };
                    (resolved, Some((argument_params, argument_targets)))
                }
                TranslatorReturnForward::ParameterCall { .. } => continue,
            };
            for (index, params) in resolved {
                let params = if let Some((argument_params, argument_targets)) = argument_params {
                    let mut mapped = BTreeSet::new();
                    for param in params {
                        if let Some(Some(mapped_param)) = argument_params.get(param) {
                            mapped.insert(*mapped_param);
                        } else if let Some(targets) = argument_targets.get(&param) {
                            for target in targets {
                                if let Some(target) = self
                                    .wrapper_callable_target_resolution_at_depth(
                                        path,
                                        target,
                                        depth + 1,
                                    )
                                {
                                    mapped.extend(
                                        target.captured_parameters.values().flatten().copied(),
                                    );
                                }
                            }
                        }
                    }
                    mapped
                } else {
                    params
                };
                if !params.is_empty() {
                    indexes.entry(index).or_default().extend(params);
                }
            }
        }
    }

    fn wrapper_callable_target_resolution_at_depth(
        &self,
        path: &Path,
        target: &WrapperCallableTarget,
        depth: usize,
    ) -> Option<LocalWrapperResolution> {
        if depth > 16 {
            return None;
        }
        let file = self.files.get(path)?;
        let (direct, indexes, parameters) = if let Some(namespace) = &target.namespace {
            let source = file.namespace_imports.get(namespace)?;
            let import = ImportTarget {
                source: source.clone(),
                imported: ImportedName::Named(target.name.clone()),
            };
            (
                self.wrapper_return_for_import_at_depth(path, &import, depth + 1),
                self.wrapper_array_indexes_for_import_at_depth(path, &import, depth + 1)
                    .unwrap_or_default(),
                self.wrapper_array_parameter_indexes_for_import_at_depth(path, &import, depth + 1),
            )
        } else if let Some(import) = file.imports.get(&target.name) {
            (
                self.wrapper_return_for_import_at_depth(path, import, depth + 1),
                self.wrapper_array_indexes_for_import_at_depth(path, import, depth + 1)
                    .unwrap_or_default(),
                self.wrapper_array_parameter_indexes_for_import_at_depth(path, import, depth + 1),
            )
        } else {
            (
                self.wrapper_return_for_local_at_depth(path, &target.name, depth + 1),
                self.wrapper_array_indexes_for_local_at_depth(path, &target.name, depth + 1)
                    .unwrap_or_default(),
                self.wrapper_array_parameter_indexes_for_local_at_depth(
                    path,
                    &target.name,
                    depth + 1,
                ),
            )
        };
        let mut resolution = LocalWrapperResolution {
            direct,
            indexes,
            parameters,
            captured_parameters: BTreeMap::new(),
            forwards: BTreeSet::new(),
            definition_shadowed_bindings: BTreeSet::new(),
        };
        if target.bound_argument_count == 0 && target.bound_unknown_from.is_none() {
            return Some(resolution);
        }
        let mut remaining = BTreeMap::<usize, BTreeSet<usize>>::new();
        let mut captured = BTreeMap::<usize, BTreeSet<usize>>::new();
        for (index, params) in std::mem::take(&mut resolution.parameters) {
            let mut wrapper_argument = false;
            for param in params {
                if param < target.bound_argument_count {
                    wrapper_argument |= target.bound_wrapper_arguments.contains(&param);
                    if let Some(params) = target.bound_argument_params.get(&param) {
                        captured
                            .entry(index)
                            .or_default()
                            .extend(params.iter().copied());
                    }
                    if let Some(targets) = target.bound_argument_targets.get(&param) {
                        for nested in targets {
                            if let Some(nested) = self.wrapper_callable_target_resolution_at_depth(
                                path,
                                nested,
                                depth + 1,
                            ) {
                                wrapper_argument |= nested.direct || !nested.indexes.is_empty();
                                captured
                                    .entry(index)
                                    .or_default()
                                    .extend(nested.captured_parameters.values().flatten().copied());
                            }
                        }
                    }
                    if target.bound_unknown_from.is_some_and(|from| param >= from) {
                        wrapper_argument |= target.bound_unknown_may_wrap;
                        captured
                            .entry(index)
                            .or_default()
                            .extend(target.bound_unknown_params.iter().copied());
                        for nested in &target.bound_unknown_targets {
                            if let Some(nested) = self.wrapper_callable_target_resolution_at_depth(
                                path,
                                nested,
                                depth + 1,
                            ) {
                                wrapper_argument |= nested.direct || !nested.indexes.is_empty();
                                captured
                                    .entry(index)
                                    .or_default()
                                    .extend(nested.captured_parameters.values().flatten().copied());
                            }
                        }
                    }
                } else if target.bound_unknown_from.is_some_and(|from| param >= from) {
                    wrapper_argument |= target.bound_unknown_may_wrap;
                    captured
                        .entry(index)
                        .or_default()
                        .extend(target.bound_unknown_params.iter().copied());
                    for nested in &target.bound_unknown_targets {
                        if let Some(nested) = self.wrapper_callable_target_resolution_at_depth(
                            path,
                            nested,
                            depth + 1,
                        ) {
                            wrapper_argument |= nested.direct || !nested.indexes.is_empty();
                            captured
                                .entry(index)
                                .or_default()
                                .extend(nested.captured_parameters.values().flatten().copied());
                        }
                    }
                } else {
                    remaining
                        .entry(index)
                        .or_default()
                        .insert(param - target.bound_argument_count);
                }
            }
            if wrapper_argument {
                resolution.indexes.insert(index);
            }
        }
        resolution.parameters = remaining;
        resolution.captured_parameters = captured;
        Some(resolution)
    }

    fn wrapper_array_parameter_indexes_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> BTreeMap<usize, BTreeSet<usize>> {
        self.wrapper_array_parameter_indexes_for_import_at_depth(from, target, 0)
    }

    fn wrapper_array_parameter_indexes_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> BTreeMap<usize, BTreeSet<usize>> {
        if depth > 16 {
            return BTreeMap::new();
        }
        let Some(path) = self.resolve_module(from, &target.source) else {
            return BTreeMap::new();
        };
        let Some(file) = self.files.get(&path) else {
            return BTreeMap::new();
        };
        match &target.imported {
            ImportedName::Named(name) => {
                if let Some(local) = file.translator_return_export_locals.get(name) {
                    return self.wrapper_array_parameter_indexes_for_local_at_depth(
                        &path,
                        local,
                        depth + 1,
                    );
                }
                if let Some(target) = file.re_exports.get(name) {
                    return self.wrapper_array_parameter_indexes_for_import_at_depth(
                        &path,
                        target,
                        depth + 1,
                    );
                }
                file.star_re_exports
                    .iter()
                    .find_map(|source| {
                        let indexes = self.wrapper_array_parameter_indexes_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        );
                        (!indexes.is_empty()).then_some(indexes)
                    })
                    .unwrap_or_default()
            }
            ImportedName::Default => {
                if let Some(local) = &file.default_local_export {
                    return self.wrapper_array_parameter_indexes_for_local_at_depth(
                        &path,
                        local,
                        depth + 1,
                    );
                }
                let mut indexes = file
                    .default_wrapper_array_index_forwards
                    .iter()
                    .filter_map(|(index, candidates)| {
                        let params = candidates
                            .iter()
                            .filter_map(|candidate| match candidate {
                                TranslatorReturnForward::ParameterCall { param_index, .. } => {
                                    Some(*param_index)
                                }
                                _ => None,
                            })
                            .collect::<BTreeSet<_>>();
                        (!params.is_empty()).then_some((*index, params))
                    })
                    .collect::<BTreeMap<_, _>>();
                self.extend_wrapper_parameter_indexes_from_forwards(
                    &path,
                    &file.default_wrapper_return_forwards,
                    depth + 1,
                    &mut indexes,
                );
                if !indexes.is_empty() {
                    return indexes;
                }
                file.re_exports
                    .get("default")
                    .map(|target| {
                        self.wrapper_array_parameter_indexes_for_import_at_depth(
                            &path,
                            target,
                            depth + 1,
                        )
                    })
                    .unwrap_or_default()
            }
        }
    }

    fn wrapper_return_for_local_at_depth(&self, path: &Path, name: &str, depth: usize) -> bool {
        if depth > 16 {
            return false;
        }
        let Some(file) = self.files.get(path) else {
            return false;
        };
        if file.wrapper_return_helpers.contains(name) {
            return true;
        }
        file.wrapper_return_forwards
            .get(name)
            .is_some_and(|forwards| {
                forwards.iter().any(|forward| match forward {
                    TranslatorReturnForward::Local(callee) => {
                        self.wrapper_return_for_local_at_depth(path, callee, depth + 1)
                            || file.imports.get(callee).is_some_and(|target| {
                                self.wrapper_return_for_import_at_depth(path, target, depth + 1)
                            })
                    }
                    TranslatorReturnForward::NamespaceMember { namespace, name } => {
                        file.namespace_imports.get(namespace).is_some_and(|source| {
                            self.wrapper_return_for_import_at_depth(
                                path,
                                &ImportTarget {
                                    source: source.clone(),
                                    imported: ImportedName::Named(name.clone()),
                                },
                                depth + 1,
                            )
                        })
                    }
                    TranslatorReturnForward::ParameterCall { .. } => false,
                    TranslatorReturnForward::ForwardCall {
                        namespace: None,
                        name,
                        ..
                    } => {
                        self.wrapper_return_for_local_at_depth(path, name, depth + 1)
                            || file.imports.get(name).is_some_and(|target| {
                                self.wrapper_return_for_import_at_depth(path, target, depth + 1)
                            })
                    }
                    TranslatorReturnForward::ForwardCall {
                        namespace: Some(namespace),
                        name,
                        ..
                    } => file.namespace_imports.get(namespace).is_some_and(|source| {
                        self.wrapper_return_for_import_at_depth(
                            path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    }),
                })
            })
    }

    fn wrapper_return_for_import(&self, from: &Path, target: &ImportTarget) -> bool {
        self.wrapper_return_for_import_at_depth(from, target, 0)
    }

    fn wrapper_return_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> bool {
        if depth > 16 {
            return false;
        }
        let Some(path) = self.resolve_module(from, &target.source) else {
            return false;
        };
        let Some(file) = self.files.get(&path) else {
            return false;
        };
        match &target.imported {
            ImportedName::Named(name) => {
                file.named_wrapper_return_exports.contains(name)
                    || file
                        .translator_return_export_locals
                        .get(name)
                        .is_some_and(|local| {
                            self.wrapper_return_for_local_at_depth(&path, local, depth + 1)
                        })
                    || file.re_exports.get(name).is_some_and(|target| {
                        self.wrapper_return_for_import_at_depth(&path, target, depth + 1)
                    })
                    || file.star_re_exports.iter().any(|source| {
                        self.wrapper_return_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
            }
            ImportedName::Default => {
                file.default_wrapper_return_export
                    || file.default_local_export.as_ref().is_some_and(|local| {
                        self.wrapper_return_for_local_at_depth(&path, local, depth + 1)
                    })
                    || file
                        .default_wrapper_return_forwards
                        .iter()
                        .any(|forward| match forward {
                            TranslatorReturnForward::Local(callee) => {
                                self.wrapper_return_for_local_at_depth(&path, callee, depth + 1)
                                    || file.imports.get(callee).is_some_and(|target| {
                                        self.wrapper_return_for_import_at_depth(
                                            &path,
                                            target,
                                            depth + 1,
                                        )
                                    })
                            }
                            TranslatorReturnForward::NamespaceMember { namespace, name } => {
                                file.namespace_imports.get(namespace).is_some_and(|source| {
                                    self.wrapper_return_for_import_at_depth(
                                        &path,
                                        &ImportTarget {
                                            source: source.clone(),
                                            imported: ImportedName::Named(name.clone()),
                                        },
                                        depth + 1,
                                    )
                                })
                            }
                            TranslatorReturnForward::ParameterCall { .. } => false,
                            TranslatorReturnForward::ForwardCall {
                                namespace: None,
                                name,
                                ..
                            } => {
                                self.wrapper_return_for_local_at_depth(&path, name, depth + 1)
                                    || file.imports.get(name).is_some_and(|target| {
                                        self.wrapper_return_for_import_at_depth(
                                            &path,
                                            target,
                                            depth + 1,
                                        )
                                    })
                            }
                            TranslatorReturnForward::ForwardCall {
                                namespace: Some(namespace),
                                name,
                                ..
                            } => file.namespace_imports.get(namespace).is_some_and(|source| {
                                self.wrapper_return_for_import_at_depth(
                                    &path,
                                    &ImportTarget {
                                        source: source.clone(),
                                        imported: ImportedName::Named(name.clone()),
                                    },
                                    depth + 1,
                                )
                            }),
                        })
                    || file.re_exports.get("default").is_some_and(|target| {
                        self.wrapper_return_for_import_at_depth(&path, target, depth + 1)
                    })
            }
        }
    }

    fn finite_iterable_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<FiniteStrings> {
        self.finite_iterable_for_import_at_depth(from, target, 0)
    }

    fn finite_iterable_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<FiniteStrings> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .named_iterable_exports
                .get(name)
                .cloned()
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.finite_iterable_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.finite_iterable_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file.default_iterable_export.clone().or_else(|| {
                file.re_exports.get("default").and_then(|target| {
                    self.finite_iterable_for_import_at_depth(&path, target, depth + 1)
                })
            }),
        }
    }

    fn finite_record_iterable_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<FiniteRecords> {
        self.finite_record_iterable_for_import_at_depth(from, target, 0)
    }

    fn finite_record_iterable_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<FiniteRecords> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .named_record_iterable_exports
                .get(name)
                .cloned()
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.finite_record_iterable_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.finite_record_iterable_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file.default_record_iterable_export.clone().or_else(|| {
                file.re_exports.get("default").and_then(|target| {
                    self.finite_record_iterable_for_import_at_depth(&path, target, depth + 1)
                })
            }),
        }
    }

    fn return_record_helper_for_import(
        &self,
        from: &Path,
        target: &ImportTarget,
    ) -> Option<FiniteRecords> {
        self.return_record_helper_for_import_at_depth(from, target, 0)
    }

    fn return_record_helper_for_import_at_depth(
        &self,
        from: &Path,
        target: &ImportTarget,
        depth: usize,
    ) -> Option<FiniteRecords> {
        if depth > 16 {
            return None;
        }
        let path = self.resolve_module(from, &target.source)?;
        let file = self.files.get(&path)?;
        match &target.imported {
            ImportedName::Named(name) => file
                .named_record_return_exports
                .get(name)
                .cloned()
                .or_else(|| {
                    file.re_exports.get(name).and_then(|target| {
                        self.return_record_helper_for_import_at_depth(&path, target, depth + 1)
                    })
                })
                .or_else(|| {
                    file.star_re_exports.iter().find_map(|source| {
                        self.return_record_helper_for_import_at_depth(
                            &path,
                            &ImportTarget {
                                source: source.clone(),
                                imported: ImportedName::Named(name.clone()),
                            },
                            depth + 1,
                        )
                    })
                }),
            ImportedName::Default => file.default_record_return_export.clone().or_else(|| {
                file.re_exports.get("default").and_then(|target| {
                    self.return_record_helper_for_import_at_depth(&path, target, depth + 1)
                })
            }),
        }
    }

    fn resolve_module(&self, from: &Path, source: &str) -> Option<PathBuf> {
        if source.starts_with('.') {
            let base = from.parent()?.join(source);
            return self.resolve_candidate(&base);
        }

        for candidate in self.aliases.expand(source) {
            if let Some(path) = self.resolve_candidate(&candidate) {
                return Some(path);
            }
        }

        if let Some(candidate) = self.packages.expand(source) {
            if let Some(path) = self.resolve_candidate(&candidate) {
                return Some(path);
            }
        }

        None
    }

    fn resolve_candidate(&self, base: &Path) -> Option<PathBuf> {
        let candidates = module_candidates(base);
        candidates
            .into_iter()
            .map(|candidate| normalize_path(&candidate))
            .find(|candidate| is_allowed_source_file(candidate))
    }
}

impl SourceFileIndex {
    fn helper_for_local(&self, name: &str) -> Option<HelperSummary> {
        self.helpers.get(name).cloned()
    }

    fn return_helper_for_local(&self, name: &str) -> Option<FiniteStrings> {
        self.return_helpers.get(name).cloned()
    }

    fn return_record_helper_for_local(&self, name: &str) -> Option<FiniteRecords> {
        self.return_record_helpers.get(name).cloned()
    }
}

impl PathAliases {
    fn load(root: &Path) -> Self {
        for file_name in ["tsconfig.json", "jsconfig.json"] {
            let path = root.join(file_name);
            let Ok(contents) = fs::read_to_string(&path) else {
                continue;
            };
            let stripped = strip_json_comments(&contents);
            let Ok(config) = serde_json::from_str::<TsConfig>(&stripped) else {
                continue;
            };
            let Some(options) = config.compiler_options else {
                return Self::default();
            };

            let base_url = options.base_url.map(|value| root.join(value));
            let base = base_url.clone().unwrap_or_else(|| root.to_path_buf());
            let mut paths = Vec::new();
            if let Some(config_paths) = options.paths {
                for (alias, targets) in config_paths {
                    let (prefix, suffix) = split_alias_pattern(&alias);
                    paths.push(PathAlias {
                        prefix,
                        suffix,
                        targets: targets
                            .into_iter()
                            .map(|target| base.join(target).to_string_lossy().to_string())
                            .collect(),
                    });
                }
            }

            return Self { base_url, paths };
        }

        Self::default()
    }

    fn expand(&self, source: &str) -> Vec<PathBuf> {
        let mut candidates = Vec::new();
        for alias in &self.paths {
            if let Some(capture) = match_alias(source, &alias.prefix, &alias.suffix) {
                for target in &alias.targets {
                    let path = if target.contains('*') {
                        target.replace('*', capture)
                    } else {
                        target.clone()
                    };
                    candidates.push(PathBuf::from(path));
                }
            }
        }

        if candidates.is_empty() {
            if let Some(base_url) = &self.base_url {
                candidates.push(base_url.join(source));
            }
        }

        candidates
    }
}

impl WorkspacePackages {
    fn load(root: &Path) -> Self {
        let workspace_root = workspace_root(root).unwrap_or_else(|| root.to_path_buf());
        let mut packages = BTreeMap::new();
        collect_workspace_packages(&workspace_root, &mut packages);
        Self { packages }
    }

    fn expand(&self, source: &str) -> Option<PathBuf> {
        let (package_name, subpath) = split_package_source(source)?;
        let package = self.packages.get(package_name)?;
        let export_key = if subpath.is_empty() {
            ".".to_string()
        } else {
            format!("./{subpath}")
        };

        package
            .exports
            .get(&export_key)
            .map(|target| package.root.join(target))
            .or_else(|| {
                if subpath.is_empty() {
                    package.main.as_ref().map(|main| package.root.join(main))
                } else {
                    Some(package.root.join(subpath))
                }
            })
    }
}

fn workspace_root(root: &Path) -> Option<PathBuf> {
    if let Ok(output) = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["rev-parse", "--show-toplevel"])
        .output()
    {
        if output.status.success() {
            let path = PathBuf::from(String::from_utf8_lossy(&output.stdout).trim());
            if !path.as_os_str().is_empty() {
                return Some(path);
            }
        }
    }

    root.ancestors()
        .find(|ancestor| ancestor.join("pnpm-workspace.yaml").is_file())
        .map(Path::to_path_buf)
}

fn collect_workspace_packages(root: &Path, packages: &mut BTreeMap<String, WorkspacePackage>) {
    let Ok(entries) = fs::read_dir(root) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if file_type.is_dir() {
            if path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| FALLBACK_EXCLUDED_DIRS.contains(&name))
            {
                continue;
            }
            collect_workspace_packages(&path, packages);
        } else if file_type.is_file() && path.file_name().is_some_and(|name| name == "package.json")
        {
            if let Some(package) = workspace_package_from_package_json(&path) {
                packages.insert(package.0, package.1);
            }
        }
    }
}

fn workspace_package_from_package_json(path: &Path) -> Option<(String, WorkspacePackage)> {
    let contents = fs::read_to_string(path).ok()?;
    let value = serde_json::from_str::<Value>(&contents).ok()?;
    let name = value.get("name")?.as_str()?.to_string();
    let root = path.parent()?.to_path_buf();
    let exports = value
        .get("exports")
        .map(package_exports)
        .unwrap_or_default();
    let main = value
        .get("source")
        .or_else(|| value.get("module"))
        .or_else(|| value.get("main"))
        .and_then(Value::as_str)
        .map(str::to_string);
    Some((
        name,
        WorkspacePackage {
            root,
            exports,
            main,
        },
    ))
}

fn package_exports(value: &Value) -> BTreeMap<String, String> {
    let mut exports = BTreeMap::new();
    match value {
        Value::String(target) => {
            exports.insert(".".to_string(), target.to_string());
        }
        Value::Object(object) => {
            for (key, value) in object {
                if !key.starts_with('.') {
                    continue;
                }
                if let Some(target) = package_export_target(value) {
                    exports.insert(key.to_string(), target);
                }
            }
        }
        _ => {}
    }
    exports
}

fn package_export_target(value: &Value) -> Option<String> {
    match value {
        Value::String(target) => Some(target.to_string()),
        Value::Object(object) => ["source", "import", "default", "module", "require", "types"]
            .into_iter()
            .find_map(|key| object.get(key).and_then(package_export_target))
            .or_else(|| object.values().find_map(package_export_target)),
        _ => None,
    }
}

fn split_package_source(source: &str) -> Option<(&str, &str)> {
    if source.starts_with('.') || source.starts_with('/') {
        return None;
    }
    if source.starts_with('@') {
        let mut parts = source.splitn(3, '/');
        let scope = parts.next()?;
        let package = parts.next()?;
        let rest = parts.next().unwrap_or_default();
        let package_name_len = scope.len() + 1 + package.len();
        return Some((&source[..package_name_len], rest));
    }
    let mut parts = source.splitn(2, '/');
    let package = parts.next()?;
    Some((package, parts.next().unwrap_or_default()))
}

fn module_candidates(base: &Path) -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    if is_source_file(base) {
        candidates.push(base.to_path_buf());
    } else {
        for extension in SOURCE_EXTENSIONS {
            candidates.push(path_with_appended_extension(base, extension));
        }
    }

    for extension in SOURCE_EXTENSIONS {
        candidates.push(base.join(format!("index.{extension}")));
    }

    candidates
}

fn path_with_appended_extension(base: &Path, extension: &str) -> PathBuf {
    let mut path = base.as_os_str().to_os_string();
    path.push(".");
    path.push(extension);
    PathBuf::from(path)
}

fn normalize_path(path: &Path) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                normalized.pop();
            }
            _ => normalized.push(component.as_os_str()),
        }
    }
    normalized
}

fn split_alias_pattern(pattern: &str) -> (String, String) {
    match pattern.split_once('*') {
        Some((prefix, suffix)) => (prefix.to_string(), suffix.to_string()),
        None => (pattern.to_string(), String::new()),
    }
}

fn match_alias<'a>(source: &'a str, prefix: &str, suffix: &str) -> Option<&'a str> {
    if suffix.is_empty() && source == prefix {
        return Some("");
    }
    source.strip_prefix(prefix)?.strip_suffix(suffix)
}

fn strip_json_comments(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut chars = input.chars().peekable();
    let mut in_string = false;
    let mut escaped = false;

    while let Some(ch) = chars.next() {
        if in_string {
            escaped = ch == '\\' && !escaped;
            if ch == '"' && !escaped {
                in_string = false;
            }
            output.push(ch);
            if ch != '\\' {
                escaped = false;
            }
            continue;
        }

        if ch == '"' {
            in_string = true;
            output.push(ch);
            continue;
        }

        if ch == '/' {
            match chars.peek().copied() {
                Some('/') => {
                    chars.next();
                    for next in chars.by_ref() {
                        if next == '\n' {
                            output.push('\n');
                            break;
                        }
                    }
                    continue;
                }
                Some('*') => {
                    chars.next();
                    let mut previous = '\0';
                    for next in chars.by_ref() {
                        if previous == '*' && next == '/' {
                            break;
                        }
                        previous = next;
                    }
                    continue;
                }
                _ => {}
            }
        }

        output.push(ch);
    }

    output
}

#[derive(Debug, Clone, Default)]
struct PotentialWrapperPaths {
    included: BTreeSet<String>,
    excluded: BTreeSet<String>,
}

impl PotentialWrapperPaths {
    fn pattern_matches(pattern: &str, target: &str) -> bool {
        let pattern = pattern.split('.').collect::<Vec<_>>();
        let target = target.split('.').collect::<Vec<_>>();
        pattern.len() == target.len()
            && pattern.iter().zip(target).all(|(pattern, target)| {
                (*pattern == "*" && !target.is_empty()) || *pattern == target
            })
    }

    fn specificity(pattern: &str) -> usize {
        if pattern.is_empty() {
            return 0;
        }
        pattern.split('.').filter(|segment| *segment != "*").count()
    }

    fn contains(&self, target: &str) -> bool {
        let positive = self
            .included
            .iter()
            .filter(|pattern| Self::pattern_matches(pattern, target))
            .map(|pattern| Self::specificity(pattern))
            .max();
        let negative = self
            .excluded
            .iter()
            .filter(|path| {
                path.is_empty()
                    || target == path.as_str()
                    || target
                        .strip_prefix(path.as_str())
                        .is_some_and(|suffix| suffix.starts_with('.'))
            })
            .map(|path| Self::specificity(path))
            .max();
        positive.is_some_and(|positive| negative.is_none_or(|negative| positive > negative))
    }

    fn merge_alternative(mut self, alternate: Self) -> Self {
        self.included.extend(alternate.included);
        self.excluded = self
            .excluded
            .intersection(&alternate.excluded)
            .cloned()
            .collect();
        self
    }

    fn remove_property(&mut self, property: &str) {
        let prefix = format!("{property}.");
        self.included
            .retain(|path| path != property && !path.starts_with(&prefix));
        self.excluded
            .retain(|path| path != property && !path.starts_with(&prefix));
    }

    fn assign_property(&mut self, property: &str, direct: bool, nested: &Self) {
        self.remove_property(property);
        if direct {
            self.included.insert(property.to_string());
        } else {
            self.excluded.insert(property.to_string());
        }
        self.included.extend(
            nested
                .included
                .iter()
                .map(|path| format!("{property}.{path}")),
        );
        self.excluded.extend(
            nested
                .excluded
                .iter()
                .map(|path| format!("{property}.{path}")),
        );
    }

    fn is_empty(&self) -> bool {
        self.included.is_empty() && self.excluded.is_empty()
    }
}

