fn helper_summary_from_body_with_context(
    params: &oxc_ast::ast::FormalParameters<'_>,
    body: &FunctionBody<'_>,
    helpers: &BTreeMap<String, HelperSummary>,
    finite_constants: &BTreeMap<String, FiniteStrings>,
    finite_iterables: &BTreeMap<String, FiniteStrings>,
    finite_object_maps: &FiniteObjectMaps,
    finite_record_constants: &FiniteRecordBindings,
    finite_record_iterables: &FiniteRecordBindings,
    finite_record_maps: &FiniteRecordMaps,
    enum_member_domains: &TypeDomains,
    source_context: Option<&SourceQueryContext>,
) -> HelperSummary {
    let mut param_names = BTreeMap::new();
    let mut param_paths = BTreeMap::new();
    for (index, parameter) in params.items.iter().enumerate() {
        collect_parameter_bindings(
            &parameter.pattern,
            index,
            &[],
            &mut param_names,
            &mut param_paths,
        );
    }

    let mut helpers = helpers.clone();
    let mut finite_constants = finite_constants.clone();
    let mut finite_iterables = finite_iterables.clone();
    let mut finite_object_maps = finite_object_maps.clone();
    let mut finite_record_constants = finite_record_constants.clone();
    let mut finite_record_iterables = finite_record_iterables.clone();
    let mut finite_record_maps = finite_record_maps.clone();
    let mut enum_member_domains = enum_member_domains.clone();
    for name in param_names.keys() {
        helpers.remove(name);
        finite_constants.remove(name);
        finite_iterables.remove(name);
        finite_object_maps.remove(name);
        finite_record_constants.remove(name);
        finite_record_iterables.remove(name);
        finite_record_maps.remove(name);
        enum_member_domains.remove(name);
    }

    let mut collector = HelperBodyCollector {
        param_names,
        param_paths,
        helpers,
        finite_constants,
        finite_iterables,
        finite_object_maps,
        finite_record_constants,
        finite_record_iterables,
        finite_record_maps,
        enum_member_domains,
        param_argument_arrays: BTreeMap::new(),
        source_context: source_context.cloned(),
        usages: Vec::new(),
        forwards: Vec::new(),
        jsx_forwards: Vec::new(),
        jsx_dynamic_params: BTreeSet::new(),
        binding_scopes: Vec::new(),
        injected_bindings: BTreeSet::new(),
        pending_var_bindings: None,
    };
    for name in function_var_bindings(body) {
        if !collector.param_names.contains_key(&name) {
            collector.mask_binding_name(&name);
        }
    }
    for statement in &body.statements {
        collector.visit_statement(statement);
    }

    HelperSummary {
        param_usages: collector.usages,
        forwards: collector.forwards,
    }
}

fn collect_parameter_bindings(
    pattern: &BindingPattern<'_>,
    param_index: usize,
    path: &[String],
    names: &mut BTreeMap<String, usize>,
    paths: &mut BTreeMap<String, Vec<String>>,
) {
    match pattern {
        BindingPattern::BindingIdentifier(identifier) => {
            let name = identifier.name.to_string();
            names.insert(name.clone(), param_index);
            paths.insert(name, path.to_vec());
        }
        BindingPattern::AssignmentPattern(assignment) => {
            collect_parameter_bindings(&assignment.left, param_index, path, names, paths)
        }
        BindingPattern::ObjectPattern(object) => {
            for property in &object.properties {
                if property.computed {
                    continue;
                }
                let Some(name) = property.key.static_name() else {
                    continue;
                };
                let mut property_path = path.to_vec();
                property_path.push(name.to_string());
                collect_parameter_bindings(
                    &property.value,
                    param_index,
                    &property_path,
                    names,
                    paths,
                );
            }
            if let Some(rest) = &object.rest {
                collect_parameter_bindings(&rest.argument, param_index, path, names, paths);
            }
        }
        BindingPattern::ArrayPattern(array) => {
            for (index, element) in array.elements.iter().enumerate() {
                let Some(element) = element else {
                    continue;
                };
                let mut element_path = path.to_vec();
                element_path.push(index.to_string());
                collect_parameter_bindings(element, param_index, &element_path, names, paths);
            }
            if let Some(rest) = &array.rest {
                collect_parameter_bindings(&rest.argument, param_index, path, names, paths);
            }
        }
    }
}

fn jsx_component_summary_from_body(
    pattern: &BindingPattern<'_>,
    body: &FunctionBody<'_>,
    helpers: &BTreeMap<String, HelperSummary>,
    finite_constants: &BTreeMap<String, FiniteStrings>,
    finite_iterables: &BTreeMap<String, FiniteStrings>,
    finite_object_maps: &FiniteObjectMaps,
    finite_record_constants: &FiniteRecordBindings,
    finite_record_iterables: &FiniteRecordBindings,
    finite_record_maps: &FiniteRecordMaps,
    enum_member_domains: &TypeDomains,
    source_context: &SourceQueryContext,
) -> Option<JsxComponentSummary> {
    let BindingPattern::ObjectPattern(object) = pattern else {
        return None;
    };
    let mut param_names = BTreeMap::new();
    let mut prop_names = Vec::new();
    for property in &object.properties {
        if property.computed {
            continue;
        }
        let Some(prop_name) = property.key.static_name() else {
            continue;
        };
        let Some(binding_name) = binding_identifier_name(&property.value) else {
            continue;
        };
        let index = prop_names.len();
        prop_names.push(prop_name.to_string());
        param_names.insert(binding_name.to_string(), index);
    }
    if param_names.is_empty() {
        return None;
    }

    let mut collector = HelperBodyCollector {
        param_names,
        param_paths: BTreeMap::new(),
        helpers: helpers.clone(),
        finite_constants: finite_constants.clone(),
        finite_iterables: finite_iterables.clone(),
        finite_object_maps: finite_object_maps.clone(),
        finite_record_constants: finite_record_constants.clone(),
        finite_record_iterables: finite_record_iterables.clone(),
        finite_record_maps: finite_record_maps.clone(),
        enum_member_domains: enum_member_domains.clone(),
        param_argument_arrays: BTreeMap::new(),
        source_context: Some(source_context.clone()),
        usages: Vec::new(),
        forwards: Vec::new(),
        jsx_forwards: Vec::new(),
        jsx_dynamic_params: BTreeSet::new(),
        binding_scopes: Vec::new(),
        injected_bindings: BTreeSet::new(),
        pending_var_bindings: None,
    };
    let parameter_names = collector.param_names.keys().cloned().collect::<Vec<_>>();
    for name in parameter_names {
        collector.mask_outer_binding_name(&name);
    }
    for name in function_var_bindings(body) {
        if !collector.param_names.contains_key(&name) {
            collector.mask_binding_name(&name);
        }
    }
    for statement in &body.statements {
        collector.visit_statement(statement);
    }
    let mut usages = collector
        .usages
        .into_iter()
        .filter_map(|usage| {
            if usage.keys.is_none() && usage.query.is_none() {
                return None;
            }
            Some(JsxPropUsage {
                prop_name: prop_names.get(usage.param_index)?.clone(),
                keys: usage.keys,
                query: usage.query,
                translator_like: usage.translator_like,
            })
        })
        .collect::<Vec<_>>();
    usages.extend(
        collector
            .jsx_dynamic_params
            .into_iter()
            .filter_map(|param_index| {
                Some(JsxPropUsage {
                    prop_name: prop_names.get(param_index)?.clone(),
                    keys: None,
                    query: None,
                    translator_like: false,
                })
            }),
    );
    let forwards = collector
        .jsx_forwards
        .into_iter()
        .filter_map(|forward| {
            Some(JsxPropForward {
                prop_name: prop_names.get(forward.param_index)?.clone(),
                component_namespace: forward.component_namespace,
                component_name: forward.component_name,
                target_prop: forward.target_prop,
            })
        })
        .collect::<Vec<_>>();
    (!usages.is_empty() || !forwards.is_empty()).then_some(JsxComponentSummary { usages, forwards })
}

fn message_key_helper_from_expression(expression: &Expression<'_>) -> Option<usize> {
    match expression.get_inner_expression() {
        Expression::ArrowFunctionExpression(arrow) => {
            Some(message_key_helper_from_body(&arrow.params, &arrow.body)?)
        }
        Expression::FunctionExpression(function) => message_key_helper_from_function(function),
        _ => None,
    }
}

fn message_key_helper_from_function(function: &Function<'_>) -> Option<usize> {
    let body = function.body.as_ref()?;
    Some(message_key_helper_from_body(&function.params, body)?)
}

fn message_key_helper_from_body(
    params: &oxc_ast::ast::FormalParameters<'_>,
    body: &FunctionBody<'_>,
) -> Option<usize> {
    let mut param_names = BTreeMap::new();
    for (index, parameter) in params.items.iter().enumerate() {
        if let Some(name) = binding_identifier_name(&parameter.pattern) {
            param_names.insert(name.to_string(), index);
        }
    }

    let mut collector = MessageKeyHelperCollector {
        param_names,
        param_indexes: BTreeSet::new(),
    };
    for statement in &body.statements {
        collector.visit_statement(statement);
    }
    single_usize(&collector.param_indexes)
}

fn finite_return_summary_from_expression(expression: &Expression<'_>) -> Option<FiniteStrings> {
    match expression.get_inner_expression() {
        Expression::ArrowFunctionExpression(arrow) => finite_return_summary_from_arrow(arrow),
        Expression::FunctionExpression(function) => finite_return_summary_from_function(function),
        _ => None,
    }
}

fn finite_record_return_summary_from_expression(
    expression: &Expression<'_>,
) -> Option<FiniteRecords> {
    match expression.get_inner_expression() {
        Expression::ArrowFunctionExpression(arrow) => {
            finite_record_return_summary_from_arrow(arrow)
        }
        Expression::FunctionExpression(function) => {
            finite_record_return_summary_from_function(function)
        }
        _ => None,
    }
}

fn finite_record_return_summary_from_arrow(
    arrow: &ArrowFunctionExpression<'_>,
) -> Option<FiniteRecords> {
    if arrow.expression {
        if let Some(Statement::ExpressionStatement(statement)) = arrow.body.statements.first() {
            return finite_record_from_expression(
                &statement.expression,
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
            )
            .or_else(|| {
                finite_record_iterable_from_expression(
                    &statement.expression,
                    &BTreeMap::new(),
                    &BTreeMap::new(),
                    &BTreeMap::new(),
                    &BTreeMap::new(),
                    &BTreeMap::new(),
                )
            });
        }
    }
    finite_record_return_summary_from_body(
        &arrow.body,
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeSet::new(),
        BTreeSet::new(),
    )
}

fn finite_record_return_summary_from_function(function: &Function<'_>) -> Option<FiniteRecords> {
    let body = function.body.as_ref()?;
    finite_record_return_summary_from_body(
        body,
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeMap::new(),
        BTreeSet::new(),
        BTreeSet::new(),
    )
}

fn finite_record_return_summary_from_function_with_context(
    function: &Function<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    iterables: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    record_constants: &FiniteRecordBindings,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
    enum_member_domains: &TypeDomains,
    mut react_use_memo_identifiers: BTreeSet<String>,
    mut react_namespaces: BTreeSet<String>,
) -> Option<FiniteRecords> {
    let body = function.body.as_ref()?;
    for parameter in &function.params.items {
        for identifier in parameter.pattern.get_binding_identifiers() {
            react_use_memo_identifiers.remove(identifier.name.as_str());
            react_namespaces.remove(identifier.name.as_str());
        }
    }
    if let Some(rest) = &function.params.rest {
        for identifier in rest.rest.argument.get_binding_identifiers() {
            react_use_memo_identifiers.remove(identifier.name.as_str());
            react_namespaces.remove(identifier.name.as_str());
        }
    }
    finite_record_return_summary_from_body(
        body,
        constants.clone(),
        iterables.clone(),
        object_maps.clone(),
        record_constants.clone(),
        record_iterables.clone(),
        record_maps.clone(),
        enum_member_domains.clone(),
        react_use_memo_identifiers,
        react_namespaces,
    )
}

fn finite_record_return_summary_from_body(
    body: &FunctionBody<'_>,
    finite_constants: BTreeMap<String, FiniteStrings>,
    finite_iterables: BTreeMap<String, FiniteStrings>,
    finite_object_maps: FiniteObjectMaps,
    finite_record_constants: FiniteRecordBindings,
    finite_record_iterables: FiniteRecordBindings,
    finite_record_maps: FiniteRecordMaps,
    enum_member_domains: TypeDomains,
    react_use_memo_identifiers: BTreeSet<String>,
    react_namespaces: BTreeSet<String>,
) -> Option<FiniteRecords> {
    let mut collector = ReturnRecordCollector {
        finite_constants,
        finite_iterables,
        finite_object_maps,
        finite_record_constants,
        finite_record_iterables,
        finite_record_maps,
        enum_member_domains,
        react_use_memo_identifiers,
        react_namespaces,
        return_records: Vec::new(),
        unknown_return: false,
    };
    for statement in &body.statements {
        collector.visit_statement(statement);
    }
    if collector.unknown_return || collector.return_records.is_empty() {
        None
    } else {
        Some(collector.return_records)
    }
}

fn finite_return_summary_from_arrow(arrow: &ArrowFunctionExpression<'_>) -> Option<FiniteStrings> {
    if arrow.expression {
        if let Some(Statement::ExpressionStatement(statement)) = arrow.body.statements.first() {
            return finite_strings_from_expression(
                &statement.expression,
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
            );
        }
    }
    finite_return_summary_from_body(&arrow.body)
}

fn finite_return_summary_from_function(function: &Function<'_>) -> Option<FiniteStrings> {
    let body = function.body.as_ref()?;
    finite_return_summary_from_body(body)
}

fn finite_return_summary_from_body(body: &FunctionBody<'_>) -> Option<FiniteStrings> {
    let mut collector = ReturnValueCollector {
        finite_constants: BTreeMap::new(),
        finite_iterables: BTreeMap::new(),
        finite_object_maps: BTreeMap::new(),
        enum_member_domains: BTreeMap::new(),
        return_values: BTreeSet::new(),
        unknown_return: false,
    };
    for statement in &body.statements {
        collector.visit_statement(statement);
    }
    if collector.unknown_return || collector.return_values.is_empty() {
        None
    } else {
        Some(collector.return_values)
    }
}

fn binding_identifier_name<'a>(pattern: &'a BindingPattern<'a>) -> Option<&'a str> {
    match pattern {
        BindingPattern::BindingIdentifier(identifier) => Some(identifier.name.as_str()),
        BindingPattern::AssignmentPattern(assignment) => binding_identifier_name(&assignment.left),
        _ => None,
    }
}

fn namespace_arg_from_finite_strings(values: FiniteStrings) -> NamespaceArg {
    let mut values = values.into_iter();
    let Some(first) = values.next() else {
        return NamespaceArg::Dynamic;
    };
    let Some(second) = values.next() else {
        return NamespaceArg::Scoped(first);
    };
    let mut namespaces = finite_string(first);
    namespaces.insert(second);
    namespaces.extend(values);
    NamespaceArg::Finite(namespaces)
}

fn translator_binding_from_namespace_arg(namespace: NamespaceArg) -> TranslatorBinding {
    match namespace {
        NamespaceArg::Scoped(namespace) => TranslatorBinding {
            namespace: Some(namespace),
            namespaces: None,
            dynamic_namespace: false,
        },
        NamespaceArg::Finite(namespaces) => TranslatorBinding {
            namespace: None,
            namespaces: Some(namespaces),
            dynamic_namespace: false,
        },
        NamespaceArg::Unscoped => TranslatorBinding {
            namespace: None,
            namespaces: None,
            dynamic_namespace: false,
        },
        NamespaceArg::Dynamic => TranslatorBinding {
            namespace: None,
            namespaces: None,
            dynamic_namespace: true,
        },
    }
}

fn translator_binding_namespaces(binding: &TranslatorBinding) -> Option<FiniteStrings> {
    if binding.dynamic_namespace {
        return None;
    }
    Some(match &binding.namespaces {
        Some(namespaces) => namespaces.clone(),
        None => finite_string(binding.namespace.clone().unwrap_or_default()),
    })
}

fn merge_translator_bindings(
    left: &TranslatorBinding,
    right: &TranslatorBinding,
) -> TranslatorBinding {
    let (Some(mut namespaces), Some(right_namespaces)) = (
        translator_binding_namespaces(left),
        translator_binding_namespaces(right),
    ) else {
        return translator_binding_from_namespace_arg(NamespaceArg::Dynamic);
    };
    namespaces.extend(right_namespaces);
    if namespaces.len() == 1 {
        let namespace = namespaces.into_iter().next().unwrap_or_default();
        if namespace.is_empty() {
            translator_binding_from_namespace_arg(NamespaceArg::Unscoped)
        } else {
            translator_binding_from_namespace_arg(NamespaceArg::Scoped(namespace))
        }
    } else {
        translator_binding_from_namespace_arg(NamespaceArg::Finite(namespaces))
    }
}

fn merge_translator_binding_iter(
    bindings: impl IntoIterator<Item = TranslatorBinding>,
) -> Option<TranslatorBinding> {
    bindings
        .into_iter()
        .reduce(|left, right| merge_translator_bindings(&left, &right))
}

fn merge_optional_translator_bindings(
    left: Option<TranslatorBinding>,
    right: Option<TranslatorBinding>,
) -> Option<TranslatorBinding> {
    match (left, right) {
        (Some(left), Some(right)) => Some(merge_translator_bindings(&left, &right)),
        (Some(binding), None) | (None, Some(binding)) => Some(merge_translator_bindings(
            &binding,
            &translator_binding_from_namespace_arg(NamespaceArg::Dynamic),
        )),
        (None, None) => None,
    }
}

fn dynamic_translator_binding() -> TranslatorBinding {
    translator_binding_from_namespace_arg(NamespaceArg::Dynamic)
}

fn merge_translator_argument_arrays(
    left: TranslatorArgumentArray,
    right: TranslatorArgumentArray,
) -> TranslatorArgumentArray {
    let same_length = left.bindings.len() == right.bindings.len();
    let length = left.bindings.len().max(right.bindings.len());
    let mut bindings = Vec::with_capacity(length);
    for index in 0..length {
        let left = left.bindings.get(index).cloned().flatten();
        let right = right.bindings.get(index).cloned().flatten();
        bindings.push(match (left, right) {
            (Some(left), Some(right)) => Some(merge_translator_bindings(&left, &right)),
            (Some(binding), None) | (None, Some(binding)) => Some(merge_translator_bindings(
                &binding,
                &translator_binding_from_namespace_arg(NamespaceArg::Dynamic),
            )),
            (None, None) => None,
        });
    }
    TranslatorArgumentArray {
        bindings,
        safe_layout: same_length && left.safe_layout && right.safe_layout,
        set_like: left.set_like && right.set_like,
        optional: left.optional || right.optional,
        unknown_contents: left.unknown_contents || right.unknown_contents,
    }
}

fn merge_param_argument_arrays(
    left: ParamArgumentArray,
    right: ParamArgumentArray,
) -> ParamArgumentArray {
    let same_length = left.bindings.len() == right.bindings.len();
    let length = left.bindings.len().max(right.bindings.len());
    let mut bindings = Vec::with_capacity(length);
    for index in 0..length {
        let mut indexes = left.bindings.get(index).cloned().unwrap_or_default();
        if let Some(right) = right.bindings.get(index) {
            indexes.extend(right);
        }
        bindings.push(indexes);
    }
    ParamArgumentArray {
        bindings,
        safe_layout: same_length && left.safe_layout && right.safe_layout,
    }
}

fn module_export_name<'a>(name: &'a ModuleExportName<'a>) -> Option<&'a str> {
    match name {
        ModuleExportName::IdentifierName(identifier) => Some(identifier.name.as_str()),
        ModuleExportName::IdentifierReference(identifier) => Some(identifier.name.as_str()),
        ModuleExportName::StringLiteral(literal) => Some(literal.value.as_str()),
    }
}

fn commonjs_require_source(expression: &Expression<'_>) -> Option<String> {
    let Expression::CallExpression(call) = expression.get_inner_expression() else {
        return None;
    };
    let callee = call
        .callee
        .get_inner_expression()
        .get_identifier_reference()?;
    if callee.name.as_str() != "require" {
        return None;
    }
    let source = call
        .arguments
        .first()?
        .as_expression()?
        .get_inner_expression();
    let Expression::StringLiteral(source) = source else {
        return None;
    };
    Some(source.value.to_string())
}

fn commonjs_member_import(expression: &Expression<'_>) -> Option<(String, String)> {
    let member = expression.get_member_expr()?;
    let imported = member.static_property_name()?.to_string();
    let source = commonjs_require_source(member.object())?;
    Some((source, imported))
}

fn commonjs_declarator_imports(
    declarator: &VariableDeclarator<'_>,
) -> Vec<(String, Option<String>, String)> {
    let Some(init) = &declarator.init else {
        return Vec::new();
    };
    if let Some(source) = commonjs_require_source(init) {
        return match &declarator.id {
            BindingPattern::BindingIdentifier(identifier) => {
                vec![(source, None, identifier.name.to_string())]
            }
            BindingPattern::ObjectPattern(object) => object
                .properties
                .iter()
                .filter_map(|property| {
                    if property.computed {
                        return None;
                    }
                    let imported = property.key.static_name()?.to_string();
                    let local = binding_identifier_name(&property.value)?.to_string();
                    Some((source.clone(), Some(imported), local))
                })
                .collect(),
            _ => Vec::new(),
        };
    }
    let Some((source, imported)) = commonjs_member_import(init) else {
        return Vec::new();
    };
    binding_identifier_name(&declarator.id)
        .map(|local| vec![(source, Some(imported), local.to_string())])
        .unwrap_or_default()
}

fn ts_type_name_identifier<'a>(name: &'a TSTypeName<'a>) -> Option<&'a str> {
    match name {
        TSTypeName::IdentifierReference(identifier) => Some(identifier.name.as_str()),
        _ => None,
    }
}

fn ts_type_name_parts(name: &TSTypeName<'_>) -> Option<Vec<String>> {
    match name {
        TSTypeName::IdentifierReference(identifier) => Some(vec![identifier.name.to_string()]),
        TSTypeName::QualifiedName(qualified) => {
            let mut parts = ts_type_name_parts(&qualified.left)?;
            parts.push(qualified.right.name.to_string());
            Some(parts)
        }
        _ => None,
    }
}

fn ts_type_query_expr_identifier<'a>(name: &'a TSTypeQueryExprName<'a>) -> Option<&'a str> {
    match name {
        TSTypeQueryExprName::IdentifierReference(identifier) => Some(identifier.name.as_str()),
        _ => None,
    }
}

fn is_identifier_expression(expression: &Expression<'_>, expected: &str) -> bool {
    expression
        .get_identifier_reference()
        .is_some_and(|identifier| identifier.name == expected)
}

fn assignment_target_member_object_name<'a>(target: &'a AssignmentTarget<'a>) -> Option<&'a str> {
    let object = match target {
        AssignmentTarget::StaticMemberExpression(member) => &member.object,
        AssignmentTarget::ComputedMemberExpression(member) => &member.object,
        _ => return None,
    };
    expression_member_root_name(object)
}

fn expression_member_root_name<'a>(expression: &'a Expression<'a>) -> Option<&'a str> {
    match expression.get_inner_expression() {
        Expression::Identifier(identifier) => Some(identifier.name.as_str()),
        Expression::StaticMemberExpression(member) => expression_member_root_name(&member.object),
        Expression::ComputedMemberExpression(member) => expression_member_root_name(&member.object),
        _ => None,
    }
}

fn expression_static_member_path<'a>(
    expression: &'a Expression<'a>,
    path: &mut Vec<String>,
) -> Option<&'a str> {
    match expression.get_inner_expression() {
        Expression::Identifier(identifier) => Some(identifier.name.as_str()),
        Expression::StaticMemberExpression(member) => {
            let root = expression_static_member_path(&member.object, path)?;
            path.push(member.property.name.to_string());
            Some(root)
        }
        _ => None,
    }
}

fn assignment_target_static_member_path<'a>(
    target: &'a AssignmentTarget<'a>,
) -> Option<(&'a str, Vec<String>)> {
    let AssignmentTarget::StaticMemberExpression(member) = target else {
        return None;
    };
    let mut path = Vec::new();
    let root = expression_static_member_path(&member.object, &mut path)?;
    path.push(member.property.name.to_string());
    Some((root, path))
}

fn assignment_target_unknown_container_path<'a>(
    target: &'a AssignmentTarget<'a>,
) -> Option<(&'a str, Vec<String>)> {
    let AssignmentTarget::ComputedMemberExpression(member) = target else {
        return None;
    };
    let mut path = Vec::new();
    let root = expression_static_member_path(&member.object, &mut path)?;
    Some((root, path))
}

fn assignment_target_identifier_names(target: &AssignmentTarget<'_>, names: &mut Vec<String>) {
    match target {
        AssignmentTarget::AssignmentTargetIdentifier(identifier) => {
            names.push(identifier.name.to_string());
        }
        AssignmentTarget::ArrayAssignmentTarget(array) => {
            for element in array.elements.iter().flatten() {
                assignment_target_maybe_default_identifier_names(element, names);
            }
            if let Some(rest) = &array.rest {
                assignment_target_identifier_names(&rest.target, names);
            }
        }
        AssignmentTarget::ObjectAssignmentTarget(object) => {
            for property in &object.properties {
                match property {
                    AssignmentTargetProperty::AssignmentTargetPropertyIdentifier(property) => {
                        names.push(property.binding.name.to_string());
                    }
                    AssignmentTargetProperty::AssignmentTargetPropertyProperty(property) => {
                        assignment_target_maybe_default_identifier_names(&property.binding, names);
                    }
                }
            }
            if let Some(rest) = &object.rest {
                assignment_target_identifier_names(&rest.target, names);
            }
        }
        _ => {}
    }
}

fn assignment_target_maybe_default_identifier_names(
    target: &AssignmentTargetMaybeDefault<'_>,
    names: &mut Vec<String>,
) {
    match target {
        AssignmentTargetMaybeDefault::AssignmentTargetWithDefault(default) => {
            assignment_target_identifier_names(&default.binding, names);
        }
        AssignmentTargetMaybeDefault::AssignmentTargetIdentifier(identifier) => {
            names.push(identifier.name.to_string());
        }
        AssignmentTargetMaybeDefault::ArrayAssignmentTarget(array) => {
            for element in array.elements.iter().flatten() {
                assignment_target_maybe_default_identifier_names(element, names);
            }
            if let Some(rest) = &array.rest {
                assignment_target_identifier_names(&rest.target, names);
            }
        }
        AssignmentTargetMaybeDefault::ObjectAssignmentTarget(object) => {
            for property in &object.properties {
                match property {
                    AssignmentTargetProperty::AssignmentTargetPropertyIdentifier(property) => {
                        names.push(property.binding.name.to_string());
                    }
                    AssignmentTargetProperty::AssignmentTargetPropertyProperty(property) => {
                        assignment_target_maybe_default_identifier_names(&property.binding, names);
                    }
                }
            }
            if let Some(rest) = &object.rest {
                assignment_target_identifier_names(&rest.target, names);
            }
        }
        _ => {}
    }
}

fn singularize_constant_word(word: &str) -> String {
    if word.ends_with("ies") && word.len() > 3 {
        format!("{}y", &word[..word.len() - 3])
    } else if word.ends_with("ses") && word.len() > 3 {
        word[..word.len() - 2].to_string()
    } else if word.ends_with('s') && word.len() > 1 {
        word[..word.len() - 1].to_string()
    } else {
        word.to_string()
    }
}

fn lower_camel(words: &[String]) -> String {
    let Some((first, rest)) = words.split_first() else {
        return String::new();
    };
    let mut value = first.clone();
    for word in rest {
        let mut chars = word.chars();
        if let Some(first) = chars.next() {
            value.push(first.to_ascii_uppercase());
            value.extend(chars);
        }
    }
    value
}

fn property_names_from_value_constant_name(name: &str) -> BTreeSet<String> {
    let mut words: Vec<String> = name
        .split('_')
        .filter(|part| !part.is_empty())
        .map(|part| part.to_ascii_lowercase())
        .collect();
    if words.is_empty() {
        return BTreeSet::new();
    }

    if matches!(
        words.last().map(String::as_str),
        Some("values" | "options" | "items")
    ) {
        words.pop();
    }

    let words: Vec<String> = words
        .into_iter()
        .map(|word| singularize_constant_word(&word))
        .collect();
    let mut properties = BTreeSet::new();
    for start in 0..words.len() {
        properties.insert(lower_camel(&words[start..]));
    }
    properties
}

fn finite_strings_from_ts_type(
    ty: &TSType<'_>,
    type_domains: &TypeDomains,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    match ty {
        TSType::TSLiteralType(literal_type) => match &literal_type.literal {
            TSLiteral::StringLiteral(literal) => Some(finite_string(literal.value.to_string())),
            TSLiteral::TemplateLiteral(literal) if literal.quasis.len() == 1 => literal.quasis[0]
                .value
                .cooked
                .map(|value| finite_string(value.to_string())),
            _ => None,
        },
        TSType::TSUnionType(union) => {
            let mut values = BTreeSet::new();
            for ty in &union.types {
                values.extend(finite_strings_from_ts_type(
                    ty,
                    type_domains,
                    enum_member_domains,
                )?);
                if values.len() > MAX_FINITE_STRINGS {
                    return None;
                }
            }
            Some(values)
        }
        TSType::TSParenthesizedType(parenthesized) => finite_strings_from_ts_type(
            &parenthesized.type_annotation,
            type_domains,
            enum_member_domains,
        ),
        TSType::TSTypeReference(reference) => {
            let name = ts_type_name_identifier(&reference.type_name)?;
            type_domains
                .get(name)
                .cloned()
                .or_else(|| enum_member_domains.get(name).cloned())
        }
        TSType::TSTypeOperatorType(operator)
            if operator.operator == TSTypeOperatorOperator::Readonly =>
        {
            finite_strings_from_ts_type(
                &operator.type_annotation,
                type_domains,
                enum_member_domains,
            )
        }
        _ => None,
    }
}

fn finite_iterable_from_ts_type(
    ty: &TSType<'_>,
    type_domains: &TypeDomains,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    match ty {
        TSType::TSArrayType(array) => {
            finite_strings_from_ts_type(&array.element_type, type_domains, enum_member_domains)
        }
        TSType::TSTypeOperatorType(operator)
            if operator.operator == TSTypeOperatorOperator::Readonly =>
        {
            finite_iterable_from_ts_type(
                &operator.type_annotation,
                type_domains,
                enum_member_domains,
            )
            .or_else(|| {
                finite_strings_from_ts_type(
                    &operator.type_annotation,
                    type_domains,
                    enum_member_domains,
                )
            })
        }
        TSType::TSTypeReference(reference) => {
            let name = ts_type_name_identifier(&reference.type_name)?;
            if matches!(name, "Array" | "ReadonlyArray" | "Readonly") {
                let first = reference.type_arguments.as_ref()?.params.first()?;
                finite_strings_from_ts_type(first, type_domains, enum_member_domains).or_else(
                    || finite_iterable_from_ts_type(first, type_domains, enum_member_domains),
                )
            } else {
                None
            }
        }
        _ => None,
    }
}

fn property_domains_from_type_literal(
    members: &[TSSignature<'_>],
    _type_property_domains: &TypePropertyDomains,
    type_domains: &TypeDomains,
    enum_member_domains: &TypeDomains,
) -> PropertyDomains {
    let mut properties = BTreeMap::new();
    for member in members {
        let TSSignature::TSPropertySignature(property) = member else {
            continue;
        };
        if property.computed {
            continue;
        }
        let Some(name) = property.key.static_name() else {
            continue;
        };
        let Some(annotation) = &property.type_annotation else {
            continue;
        };
        if let Some(values) = finite_iterable_from_ts_type(
            &annotation.type_annotation,
            type_domains,
            enum_member_domains,
        )
        .or_else(|| {
            finite_strings_from_ts_type(
                &annotation.type_annotation,
                type_domains,
                enum_member_domains,
            )
        }) {
            properties.insert(name.to_string(), values);
        }
    }
    properties
}

fn type_literal_property_annotation<'a>(
    members: &'a [TSSignature<'a>],
    property_name: &str,
) -> Option<&'a TSType<'a>> {
    for member in members {
        let TSSignature::TSPropertySignature(property) = member else {
            continue;
        };
        if property.computed {
            continue;
        }
        if property
            .key
            .static_name()
            .is_some_and(|name| name == property_name)
        {
            return property
                .type_annotation
                .as_ref()
                .map(|annotation| &annotation.type_annotation);
        }
    }
    None
}

fn merge_property_domains(
    left: PropertyDomains,
    right: PropertyDomains,
) -> Option<PropertyDomains> {
    let mut merged = left;
    for (property, values) in right {
        let entry = merged.entry(property).or_default();
        entry.extend(values);
        if entry.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    Some(merged)
}

fn property_domains_from_ts_type(
    ty: &TSType<'_>,
    type_property_domains: &TypePropertyDomains,
    type_domains: &TypeDomains,
    enum_member_domains: &TypeDomains,
    zod_schema_property_domains: &TypePropertyDomains,
) -> Option<PropertyDomains> {
    match ty {
        TSType::TSTypeLiteral(literal) => Some(property_domains_from_type_literal(
            &literal.members,
            type_property_domains,
            type_domains,
            enum_member_domains,
        ))
        .filter(|properties| !properties.is_empty()),
        TSType::TSUnionType(union) => {
            let mut merged = BTreeMap::new();
            for ty in &union.types {
                if let Some(properties) = property_domains_from_ts_type(
                    ty,
                    type_property_domains,
                    type_domains,
                    enum_member_domains,
                    zod_schema_property_domains,
                ) {
                    merged = merge_property_domains(merged, properties)?;
                }
            }
            Some(merged).filter(|properties| !properties.is_empty())
        }
        TSType::TSParenthesizedType(parenthesized) => property_domains_from_ts_type(
            &parenthesized.type_annotation,
            type_property_domains,
            type_domains,
            enum_member_domains,
            zod_schema_property_domains,
        ),
        TSType::TSTypeReference(reference) => {
            if ts_type_name_parts(&reference.type_name)
                .is_some_and(|parts| parts.len() == 2 && parts[0] == "z" && parts[1] == "infer")
            {
                let first = reference.type_arguments.as_ref()?.params.first()?;
                let TSType::TSTypeQuery(query) = first else {
                    return None;
                };
                let schema_name = ts_type_query_expr_identifier(&query.expr_name)?;
                return zod_schema_property_domains.get(schema_name).cloned();
            }

            let name = ts_type_name_identifier(&reference.type_name)?;
            if matches!(name, "UseFormReturn" | "Partial" | "Required" | "Readonly") {
                let first = reference.type_arguments.as_ref()?.params.first()?;
                return property_domains_from_ts_type(
                    first,
                    type_property_domains,
                    type_domains,
                    enum_member_domains,
                    zod_schema_property_domains,
                );
            }
            type_property_domains.get(name).cloned()
        }
        TSType::TSTypeOperatorType(operator)
            if operator.operator == TSTypeOperatorOperator::Readonly =>
        {
            property_domains_from_ts_type(
                &operator.type_annotation,
                type_property_domains,
                type_domains,
                enum_member_domains,
                zod_schema_property_domains,
            )
        }
        _ => None,
    }
}

fn record_enum_member_domain(
    enum_member_domains: &mut TypeDomains,
    object: &Expression<'_>,
    property: &str,
) {
    let Some(object) = object.get_inner_expression().get_identifier_reference() else {
        return;
    };
    if !object
        .name
        .chars()
        .next()
        .is_some_and(|first| first.is_ascii_uppercase())
    {
        return;
    }
    enum_member_domains
        .entry(object.name.to_string())
        .or_default()
        .insert(property.to_string());
}

struct EnumMemberDomainCollector<'m> {
    domains: &'m mut TypeDomains,
}

impl<'a> Visit<'a> for EnumMemberDomainCollector<'_> {
    fn visit_static_member_expression(&mut self, member: &StaticMemberExpression<'a>) {
        record_enum_member_domain(self.domains, &member.object, member.property.name.as_str());
        walk::walk_static_member_expression(self, member);
    }
}

fn record_enum_member_domains_from_expression(
    expression: &Expression<'_>,
    enum_member_domains: &mut TypeDomains,
) {
    let mut collector = EnumMemberDomainCollector {
        domains: enum_member_domains,
    };
    collector.visit_expression(expression);
}

fn finite_string(value: impl Into<String>) -> FiniteStrings {
    BTreeSet::from([value.into()])
}

fn single_finite_string(values: &FiniteStrings) -> Option<String> {
    if values.len() == 1 {
        values.first().cloned()
    } else {
        None
    }
}

fn single_usize(values: &BTreeSet<usize>) -> Option<usize> {
    if values.len() == 1 {
        values.first().copied()
    } else {
        None
    }
}

fn union_finite_strings(left: FiniteStrings, right: FiniteStrings) -> Option<FiniteStrings> {
    let mut values = left;
    values.extend(right);
    if values.len() > MAX_FINITE_STRINGS {
        None
    } else {
        Some(values)
    }
}

fn append_finite_strings(
    prefixes: FiniteStrings,
    suffixes: &FiniteStrings,
) -> Option<FiniteStrings> {
    let mut values = BTreeSet::new();
    for prefix in prefixes {
        for suffix in suffixes {
            values.insert(format!("{prefix}{suffix}"));
            if values.len() > MAX_FINITE_STRINGS {
                return None;
            }
        }
    }
    Some(values)
}

fn finite_strings_from_argument(
    argument: &Argument<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    match argument {
        Argument::StringLiteral(literal) => Some(finite_string(literal.value.to_string())),
        Argument::TemplateLiteral(literal) => {
            finite_strings_from_template(literal, constants, object_maps, enum_member_domains)
        }
        Argument::Identifier(identifier) => constants.get(identifier.name.as_str()).cloned(),
        Argument::CallExpression(call) => {
            finite_strings_from_call(call, constants, object_maps, enum_member_domains)
        }
        Argument::ComputedMemberExpression(member) => {
            finite_strings_from_computed_member(member, constants, object_maps, enum_member_domains)
        }
        Argument::StaticMemberExpression(member) => {
            finite_strings_from_static_member(member, object_maps, enum_member_domains)
        }
        Argument::ConditionalExpression(conditional) => finite_strings_from_conditional(
            conditional,
            constants,
            object_maps,
            enum_member_domains,
        ),
        Argument::ParenthesizedExpression(parenthesized) => finite_strings_from_expression(
            &parenthesized.expression,
            constants,
            object_maps,
            enum_member_domains,
        ),
        Argument::TSAsExpression(expression) => finite_strings_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
        ),
        Argument::TSSatisfiesExpression(expression) => finite_strings_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
        ),
        Argument::TSNonNullExpression(expression) => finite_strings_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
        ),
        Argument::TSInstantiationExpression(expression) => finite_strings_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
        ),
        Argument::TSTypeAssertion(expression) => finite_strings_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
        ),
        _ => None,
    }
}

fn finite_strings_from_expression(
    expression: &Expression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    match expression.get_inner_expression() {
        Expression::StringLiteral(literal) => Some(finite_string(literal.value.to_string())),
        Expression::TemplateLiteral(literal) => {
            finite_strings_from_template(literal, constants, object_maps, enum_member_domains)
        }
        Expression::Identifier(identifier) => constants.get(identifier.name.as_str()).cloned(),
        Expression::CallExpression(call) => {
            finite_strings_from_call(call, constants, object_maps, enum_member_domains)
        }
        Expression::ComputedMemberExpression(member) => {
            finite_strings_from_computed_member(member, constants, object_maps, enum_member_domains)
        }
        Expression::StaticMemberExpression(member) => {
            finite_strings_from_static_member(member, object_maps, enum_member_domains)
        }
        Expression::ConditionalExpression(conditional) => finite_strings_from_conditional(
            conditional,
            constants,
            object_maps,
            enum_member_domains,
        ),
        _ => None,
    }
}

fn finite_iterable_from_expression(
    expression: &Expression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    iterables: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    match expression.get_inner_expression() {
        Expression::ArrayExpression(array) => finite_iterable_from_array_elements(
            array.elements.iter(),
            constants,
            iterables,
            object_maps,
            enum_member_domains,
        ),
        Expression::Identifier(identifier) => iterables.get(identifier.name.as_str()).cloned(),
        _ => None,
    }
}

fn finite_iterable_from_array_elements<'a>(
    elements: impl Iterator<Item = &'a ArrayExpressionElement<'a>>,
    constants: &BTreeMap<String, FiniteStrings>,
    iterables: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    let mut values = BTreeSet::new();
    for element in elements {
        let element_values = finite_strings_from_array_element(
            element,
            constants,
            iterables,
            object_maps,
            enum_member_domains,
        )?;
        values.extend(element_values);
        if values.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    Some(values)
}

fn finite_object_map_from_expression(
    expression: &Expression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteObjectMap> {
    match expression.get_inner_expression() {
        Expression::ObjectExpression(object) => {
            finite_object_map_from_object(object, constants, object_maps, enum_member_domains)
        }
        _ => None,
    }
}

fn finite_object_map_from_object(
    object: &ObjectExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteObjectMap> {
    let mut map = BTreeMap::new();
    for property in &object.properties {
        let ObjectPropertyKind::ObjectProperty(property) = property else {
            return None;
        };
        if property.kind != PropertyKind::Init || property.method || property.shorthand {
            return None;
        }
        let key = property.key.static_name()?.to_string();
        let values = finite_strings_from_expression(
            &property.value,
            constants,
            object_maps,
            enum_member_domains,
        )?;
        map.insert(key, values);
        if map.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    if map.is_empty() {
        return None;
    }
    Some(map)
}

fn finite_strings_from_computed_member(
    member: &ComputedMemberExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    let object_name = member
        .object
        .get_inner_expression()
        .get_identifier_reference()?
        .name
        .as_str();
    let map = object_maps.get(object_name)?;
    if let Some(keys) = finite_strings_from_expression(
        &member.expression,
        constants,
        object_maps,
        enum_member_domains,
    ) {
        return finite_object_map_values_for_keys(map, keys);
    }
    finite_object_map_all_values(map)
}

fn finite_strings_from_static_member(
    member: &StaticMemberExpression<'_>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    let object_name = member
        .object
        .get_inner_expression()
        .get_identifier_reference()?
        .name
        .as_str();
    object_maps
        .get(object_name)
        .and_then(|map| map.get(member.property.name.as_str()).cloned())
        .or_else(|| {
            enum_member_domains
                .get(object_name)
                .filter(|values| values.contains(member.property.name.as_str()))
                .map(|_| finite_string(member.property.name.to_string()))
        })
}

fn finite_object_map_values_for_keys(
    map: &FiniteObjectMap,
    keys: FiniteStrings,
) -> Option<FiniteStrings> {
    let mut values = BTreeSet::new();
    for key in keys {
        values.extend(map.get(&key)?.iter().cloned());
        if values.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    Some(values)
}

fn finite_object_map_all_values(map: &FiniteObjectMap) -> Option<FiniteStrings> {
    let mut values = BTreeSet::new();
    for entry_values in map.values() {
        values.extend(entry_values.iter().cloned());
        if values.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    Some(values)
}

fn finite_record_property_strings(
    records: &FiniteRecords,
    property: &str,
) -> Option<FiniteStrings> {
    let mut values = BTreeSet::new();
    for record in records {
        if let Some(record_values) = record.strings.get(property) {
            values.extend(record_values.iter().cloned());
            if values.len() > MAX_FINITE_STRINGS {
                return None;
            }
        }
    }
    if values.is_empty() {
        None
    } else {
        Some(values)
    }
}

fn finite_record_property_iterable(
    records: &FiniteRecords,
    property: &str,
) -> Option<FiniteRecords> {
    let mut values = Vec::new();
    for record in records {
        if let Some(record_values) = record.record_iterables.get(property) {
            values.extend(record_values.iter().cloned());
            if values.len() > MAX_FINITE_STRINGS {
                return None;
            }
        }
    }
    if values.is_empty() {
        None
    } else {
        Some(values)
    }
}

#[derive(Clone, Default)]
struct CallbackLocalValue {
    binding: Option<TranslatorBinding>,
    object: Option<TranslatorObjectBinding>,
    map: Option<TranslatorObjectBinding>,
    entries: Option<TranslatorObjectBinding>,
    entry: Option<TranslatorObjectBinding>,
    array: Option<TranslatorArgumentArray>,
}

struct CallbackReturnExpressionCollector<'source, 'callback, F> {
    source: &'source SourceUsageCollector,
    callback: &'callback mut F,
    locals: BTreeMap<String, CallbackLocalValue>,
    scopes: Vec<BTreeMap<String, CallbackLocalValue>>,
}

impl<F> CallbackReturnExpressionCollector<'_, '_, F> {
    fn local_value_from_expression(&self, expression: &Expression<'_>) -> CallbackLocalValue {
        if let Some(identifier) = expression.get_identifier_reference()
            && let Some(local) = self.locals.get(identifier.name.as_str())
        {
            return local.clone();
        }
        let object = self
            .source
            .translator_object_bindings_from_expression(expression)
            .or_else(|| {
                matches!(
                    expression.get_inner_expression(),
                    Expression::ObjectExpression(_)
                )
                .then(TranslatorObjectBinding::default)
            });
        let array = self
            .source
            .translator_argument_array_from_expression(expression);
        let map = self.source.translator_map_from_expression(expression);
        let entries = self
            .source
            .translator_map_entries_from_expression(expression);
        let binding = self
            .source
            .translator_binding_from_expression(expression)
            .or_else(|| {
                object
                    .clone()
                    .and_then(TranslatorObjectBinding::aggregate_binding)
            })
            .or_else(|| {
                array
                    .clone()
                    .and_then(SourceUsageCollector::aggregate_translator_argument_array)
            })
            .or_else(|| {
                map.clone()
                    .and_then(TranslatorObjectBinding::aggregate_binding)
            })
            .or_else(|| {
                entries
                    .clone()
                    .and_then(TranslatorObjectBinding::aggregate_binding)
            });
        CallbackLocalValue {
            binding,
            object,
            map,
            entries,
            entry: self.source.translator_map_entry_from_expression(expression),
            array,
        }
    }

    fn refresh_local_binding(&mut self, name: &str) {
        let Some(local) = self.locals.get_mut(name) else {
            return;
        };
        let bindings = local
            .binding
            .clone()
            .into_iter()
            .chain(
                local
                    .object
                    .clone()
                    .and_then(TranslatorObjectBinding::aggregate_binding),
            )
            .chain(
                local
                    .map
                    .clone()
                    .and_then(TranslatorObjectBinding::aggregate_binding),
            )
            .chain(
                local
                    .entries
                    .clone()
                    .and_then(TranslatorObjectBinding::aggregate_binding),
            )
            .chain(
                local
                    .array
                    .clone()
                    .and_then(SourceUsageCollector::aggregate_translator_argument_array),
            );
        local.binding = merge_translator_binding_iter(bindings);
    }
}

impl<'a, F> Visit<'a> for CallbackReturnExpressionCollector<'_, '_, F>
where
    F: FnMut(&Expression<'a>, Option<&CallbackLocalValue>),
{
    fn enter_scope(&mut self, _flags: ScopeFlags, _scope_id: &Cell<Option<ScopeId>>) {
        self.scopes.push(self.locals.clone());
    }

    fn leave_scope(&mut self) {
        if let Some(locals) = self.scopes.pop() {
            self.locals = locals;
        }
    }

    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        let Some(name) = binding_identifier_name(&declarator.id) else {
            return;
        };
        let value = declarator
            .init
            .as_ref()
            .map(|init| self.local_value_from_expression(init))
            .unwrap_or_default();
        self.locals.insert(name.to_string(), value);
    }

    fn visit_call_expression(&mut self, call: &CallExpression<'a>) {
        let Some(member) = call.callee.get_member_expr() else {
            walk::walk_call_expression(self, call);
            return;
        };
        let Some(object) = member.object().get_identifier_reference() else {
            walk::walk_call_expression(self, call);
            return;
        };
        let name = object.name.as_str();
        let Some(method) = member.static_property_name() else {
            walk::walk_call_expression(self, call);
            return;
        };

        if method == "set"
            && self
                .locals
                .get(name)
                .is_some_and(|local| local.map.is_some())
        {
            let keys = call
                .arguments
                .first()
                .and_then(|argument| self.source.finite_strings_from_argument(argument));
            let binding = call
                .arguments
                .get(1)
                .and_then(Argument::as_expression)
                .and_then(|expression| self.local_value_from_expression(expression).binding);
            let map = self
                .locals
                .get_mut(name)
                .and_then(|local| local.map.as_mut())
                .expect("checked callback-local Map");
            if let Some(keys) = keys {
                let exact = keys.len() == 1;
                for key in keys {
                    if let Some(binding) = &binding {
                        map.assign_path(
                            &key,
                            AssignmentOperator::Assign,
                            exact,
                            Some(binding),
                            None,
                        );
                    } else if map.bindings.is_empty() {
                        map.mark_unknown(&key);
                    } else {
                        let dynamic = dynamic_translator_binding();
                        map.assign_path(
                            &key,
                            AssignmentOperator::Assign,
                            exact,
                            Some(&dynamic),
                            None,
                        );
                    }
                }
            } else {
                if let Some(binding) = binding {
                    map.bindings
                        .insert(format!("@entry{}", map.bindings.len()), binding);
                } else if !map.bindings.is_empty() {
                    map.bindings.insert(
                        format!("@entry{}", map.bindings.len()),
                        dynamic_translator_binding(),
                    );
                }
                map.mark_unknown("");
            }
            self.refresh_local_binding(name);
            return;
        }

        if method == "add"
            && self
                .locals
                .get(name)
                .and_then(|local| local.array.as_ref())
                .is_some_and(|array| array.set_like)
        {
            let binding = call
                .arguments
                .first()
                .and_then(Argument::as_expression)
                .and_then(|expression| self.local_value_from_expression(expression).binding);
            let array = self
                .locals
                .get_mut(name)
                .and_then(|local| local.array.as_mut())
                .expect("checked callback-local Set");
            if let Some(binding) = binding {
                array.bindings.push(Some(binding));
            } else if array.bindings.iter().any(Option::is_some) {
                array.bindings.push(Some(dynamic_translator_binding()));
            }
            array.safe_layout = false;
            array.unknown_contents = true;
            self.refresh_local_binding(name);
            return;
        }

        if matches!(method, "push" | "unshift" | "splice") {
            let offset = if method == "splice" { 2 } else { 0 };
            if self
                .locals
                .get(name)
                .is_some_and(|local| local.entries.is_some())
            {
                let mut additions = Vec::new();
                let mut unresolved = false;
                for argument in call.arguments.iter().skip(offset) {
                    let entry = match argument {
                        Argument::SpreadElement(spread) => {
                            let local = self.local_value_from_expression(&spread.argument);
                            local.entries.or_else(|| {
                                self.source
                                    .translator_map_entries_from_expression(&spread.argument)
                            })
                        }
                        _ => argument.as_expression().and_then(|expression| {
                            let local = self.local_value_from_expression(expression);
                            local.entry.or_else(|| {
                                self.source.translator_map_entry_from_expression(expression)
                            })
                        }),
                    };
                    if let Some(entry) = entry {
                        additions.push(entry);
                    } else {
                        unresolved = true;
                    }
                }
                let entries = self
                    .locals
                    .get_mut(name)
                    .and_then(|local| local.entries.as_mut())
                    .expect("checked callback-local entries");
                for addition in additions {
                    if method == "push" {
                        SourceUsageCollector::extend_translator_map_entries(entries, addition);
                    } else {
                        SourceUsageCollector::extend_unordered_translator_map_entries(
                            entries, addition,
                        );
                    }
                }
                if unresolved {
                    if !entries.bindings.is_empty() {
                        entries.bindings.insert(
                            format!("@entry{}", entries.bindings.len()),
                            dynamic_translator_binding(),
                        );
                    }
                }
                if unresolved {
                    entries.mark_unknown("");
                }
            }
            if self
                .locals
                .get(name)
                .is_some_and(|local| local.array.is_some())
            {
                let mut bindings = Vec::new();
                for argument in call.arguments.iter().skip(offset) {
                    let binding = match argument {
                        Argument::SpreadElement(spread) => self
                            .local_value_from_expression(&spread.argument)
                            .array
                            .and_then(SourceUsageCollector::aggregate_translator_argument_array),
                        _ => argument.as_expression().and_then(|expression| {
                            self.local_value_from_expression(expression).binding
                        }),
                    };
                    bindings.push(binding);
                }
                let array = self
                    .locals
                    .get_mut(name)
                    .and_then(|local| local.array.as_mut())
                    .expect("checked callback-local array");
                let has_known = array.bindings.iter().any(Option::is_some)
                    || bindings.iter().any(Option::is_some);
                array
                    .bindings
                    .extend(bindings.into_iter().filter_map(|binding| {
                        binding
                            .map(Some)
                            .or_else(|| has_known.then(|| Some(dynamic_translator_binding())))
                    }));
                array.safe_layout = false;
                array.unknown_contents = true;
            }
            self.refresh_local_binding(name);
            return;
        }

        walk::walk_call_expression(self, call);
    }

    fn visit_assignment_expression(&mut self, expression: &AssignmentExpression<'a>) {
        if expression.operator == AssignmentOperator::Assign
            && let AssignmentTarget::AssignmentTargetIdentifier(identifier) = &expression.left
            && self.locals.contains_key(identifier.name.as_str())
        {
            let value = self.local_value_from_expression(&expression.right);
            self.locals.insert(identifier.name.to_string(), value);
            return;
        }

        let binding = self.local_value_from_expression(&expression.right).binding;
        if let Some((name, path)) = assignment_target_static_member_path(&expression.left)
            && let Some(local) = self.locals.get_mut(name)
        {
            if let Some(object) = local.object.as_mut() {
                if let Some(binding) = &binding {
                    object.assign_path(
                        &path.join("."),
                        expression.operator,
                        true,
                        Some(binding),
                        None,
                    );
                } else {
                    object.mark_unknown(&path.join("."));
                }
            }
            if let Some(array) = local.array.as_mut() {
                if let Some(binding) = &binding {
                    array.bindings.push(Some(binding.clone()));
                } else if array.bindings.iter().any(Option::is_some) {
                    array.bindings.push(Some(dynamic_translator_binding()));
                }
                array.safe_layout = false;
                array.unknown_contents = true;
            }
            if let Some(entries) = local.entries.as_mut() {
                if let Some(binding) = binding {
                    entries
                        .bindings
                        .insert(format!("@entry{}", entries.bindings.len()), binding);
                } else if !entries.bindings.is_empty() {
                    entries.bindings.insert(
                        format!("@entry{}", entries.bindings.len()),
                        dynamic_translator_binding(),
                    );
                }
                entries.mark_unknown("");
            }
            self.refresh_local_binding(name);
            return;
        }

        walk::walk_assignment_expression(self, expression);
    }

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        if let Some(argument) = &statement.argument {
            let local = argument
                .get_identifier_reference()
                .and_then(|identifier| self.locals.get(identifier.name.as_str()));
            (self.callback)(argument, local);
        }
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

fn for_each_callback_return_expression<'a>(
    source: &SourceUsageCollector,
    callback: &Argument<'a>,
    mut visit: impl FnMut(&Expression<'a>, Option<&CallbackLocalValue>),
) {
    let (body, expression) = match callback {
        Argument::ArrowFunctionExpression(arrow) => (&arrow.body, arrow.expression),
        Argument::FunctionExpression(function) => {
            let Some(body) = function.body.as_ref() else {
                return;
            };
            (body, false)
        }
        _ => return,
    };
    if expression && let Some(Statement::ExpressionStatement(statement)) = body.statements.first() {
        visit(&statement.expression, None);
        return;
    }
    let mut collector = CallbackReturnExpressionCollector {
        source,
        callback: &mut visit,
        locals: BTreeMap::new(),
        scopes: Vec::new(),
    };
    for statement in &body.statements {
        collector.visit_statement(statement);
    }
}

fn finite_records_from_callback_argument(
    callback: &Argument<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    iterables: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    match callback {
        Argument::ArrowFunctionExpression(arrow) => {
            if arrow.expression {
                if let Some(Statement::ExpressionStatement(statement)) =
                    arrow.body.statements.first()
                {
                    return finite_record_iterable_from_expression(
                        &statement.expression,
                        constants,
                        object_maps,
                        enum_member_domains,
                        record_iterables,
                        record_maps,
                    )
                    .or_else(|| {
                        finite_record_from_expression(
                            &statement.expression,
                            constants,
                            object_maps,
                            enum_member_domains,
                            record_iterables,
                            record_maps,
                        )
                    });
                }
            }
            finite_record_return_summary_from_body(
                &arrow.body,
                constants.clone(),
                iterables.clone(),
                object_maps.clone(),
                BTreeMap::new(),
                record_iterables.clone(),
                record_maps.clone(),
                enum_member_domains.clone(),
                BTreeSet::new(),
                BTreeSet::new(),
            )
        }
        Argument::FunctionExpression(function) => finite_record_return_summary_from_body(
            function.body.as_ref()?,
            constants.clone(),
            iterables.clone(),
            object_maps.clone(),
            BTreeMap::new(),
            record_iterables.clone(),
            record_maps.clone(),
            enum_member_domains.clone(),
            BTreeSet::new(),
            BTreeSet::new(),
        ),
        _ => None,
    }
}

fn finite_records_from_array_from_call(
    call: &CallExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    let member = call.callee.get_member_expr()?;
    if member.static_property_name()? != "from"
        || !is_identifier_expression(member.object(), "Array")
    {
        return None;
    }
    let Argument::ObjectExpression(options) = call.arguments.first()? else {
        return None;
    };
    let length = options.properties.iter().find_map(|property| {
        let ObjectPropertyKind::ObjectProperty(property) = property else {
            return None;
        };
        if property.key.static_name().as_deref() != Some("length") {
            return None;
        }
        let Expression::NumericLiteral(length) = &property.value else {
            return None;
        };
        if length.value.is_finite() && length.value >= 0.0 && length.value.fract() == 0.0 {
            Some(length.value as usize)
        } else {
            None
        }
    })?;
    if length == 0 || length > MAX_FINITE_STRINGS {
        return None;
    }
    let callback = call.arguments.get(1)?;
    let Argument::ArrowFunctionExpression(arrow) = callback else {
        return None;
    };
    let index_name = arrow
        .params
        .items
        .get(1)
        .and_then(|parameter| binding_identifier_name(&parameter.pattern))?;
    let mut callback_constants = constants.clone();
    callback_constants.insert(
        index_name.to_string(),
        (0..length).map(|index| index.to_string()).collect(),
    );
    finite_records_from_callback_argument(
        callback,
        &callback_constants,
        &BTreeMap::new(),
        object_maps,
        enum_member_domains,
        record_iterables,
        record_maps,
    )
}

fn finite_records_from_object_values(
    object: &ObjectExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    let mut records = Vec::new();
    for property in &object.properties {
        let ObjectPropertyKind::ObjectProperty(property) = property else {
            return None;
        };
        if property.kind != PropertyKind::Init || property.method || property.shorthand {
            return None;
        }
        records.extend(finite_record_from_expression(
            &property.value,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        )?);
        if records.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    Some(records).filter(|records| !records.is_empty())
}

fn merge_finite_records(mut left: FiniteRecords, right: FiniteRecords) -> Option<FiniteRecords> {
    left.extend(right);
    if left.len() > MAX_FINITE_STRINGS {
        None
    } else {
        Some(left)
    }
}

fn argument_usize(argument: &Argument<'_>) -> Option<usize> {
    let value = match argument {
        Argument::NumericLiteral(literal) => literal.value,
        _ => return None,
    };
    if value.is_finite() && value >= 0.0 && value.fract() == 0.0 {
        Some(value as usize)
    } else {
        None
    }
}

fn finite_record_from_object(
    object: &ObjectExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecord> {
    let mut record = FiniteRecord::default();
    for property in &object.properties {
        let ObjectPropertyKind::ObjectProperty(property) = property else {
            return None;
        };
        if property.kind != PropertyKind::Init || property.method || property.computed {
            return None;
        }
        let Some(key) = property.key.static_name() else {
            return None;
        };
        if let Some(values) = finite_strings_from_expression(
            &property.value,
            constants,
            object_maps,
            enum_member_domains,
        ) {
            record.strings.insert(key.to_string(), values);
        }
        if let Some(values) = finite_record_iterable_from_expression(
            &property.value,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ) {
            record.record_iterables.insert(key.to_string(), values);
        }
    }
    if record.strings.is_empty() && record.record_iterables.is_empty() {
        None
    } else {
        Some(record)
    }
}

fn finite_records_from_array_elements<'a>(
    elements: impl Iterator<Item = &'a ArrayExpressionElement<'a>>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    let mut records = Vec::new();
    for element in elements {
        match element {
            ArrayExpressionElement::ObjectExpression(object) => {
                records.push(finite_record_from_object(
                    object,
                    constants,
                    object_maps,
                    enum_member_domains,
                    record_iterables,
                    record_maps,
                )?)
            }
            ArrayExpressionElement::SpreadElement(spread) => {
                records.extend(finite_record_iterable_from_expression(
                    &spread.argument,
                    constants,
                    object_maps,
                    enum_member_domains,
                    record_iterables,
                    record_maps,
                )?);
            }
            ArrayExpressionElement::Identifier(identifier) => {
                records.extend(record_iterables.get(identifier.name.as_str()).cloned()?);
            }
            _ => return None,
        }
        if records.len() > MAX_FINITE_STRINGS {
            return None;
        }
    }
    Some(records).filter(|records| !records.is_empty())
}

fn finite_record_iterable_from_expression(
    expression: &Expression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    match expression.get_inner_expression() {
        Expression::ArrayExpression(array) => finite_records_from_array_elements(
            array.elements.iter(),
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        Expression::ObjectExpression(object) => finite_records_from_object_values(
            object,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        Expression::Identifier(identifier) => {
            record_iterables.get(identifier.name.as_str()).cloned()
        }
        Expression::StaticMemberExpression(member) => {
            let object = member.object.get_identifier_reference()?;
            let records = record_iterables.get(object.name.as_str())?;
            finite_record_property_iterable(records, member.property.name.as_str())
        }
        Expression::CallExpression(call) => {
            if let Some(records) = finite_records_from_array_from_call(
                call,
                constants,
                object_maps,
                enum_member_domains,
                record_iterables,
                record_maps,
            ) {
                return Some(records);
            }
            let member = call.callee.get_member_expr()?;
            let method = member.static_property_name()?;
            let records = finite_record_iterable_from_expression(
                member.object(),
                constants,
                object_maps,
                enum_member_domains,
                record_iterables,
                record_maps,
            )?;
            match method.as_ref() {
                "filter" => Some(records),
                "slice" => {
                    let start = call.arguments.first().and_then(argument_usize).unwrap_or(0);
                    let end = call
                        .arguments
                        .get(1)
                        .and_then(argument_usize)
                        .unwrap_or(records.len());
                    Some(
                        records
                            .into_iter()
                            .skip(start)
                            .take(end.saturating_sub(start))
                            .collect(),
                    )
                }
                _ => None,
            }
        }
        Expression::TSAsExpression(expression) => finite_record_iterable_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        Expression::TSSatisfiesExpression(expression) => finite_record_iterable_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        Expression::TSNonNullExpression(expression) => finite_record_iterable_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        Expression::TSInstantiationExpression(expression) => {
            finite_record_iterable_from_expression(
                &expression.expression,
                constants,
                object_maps,
                enum_member_domains,
                record_iterables,
                record_maps,
            )
        }
        Expression::TSTypeAssertion(expression) => finite_record_iterable_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        _ => None,
    }
}

fn finite_record_map_from_expression(
    expression: &Expression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    let Expression::NewExpression(new_expression) = expression.get_inner_expression() else {
        return None;
    };
    if new_expression
        .callee
        .get_identifier_reference()?
        .name
        .as_str()
        != "Map"
    {
        return None;
    }
    let first = new_expression.arguments.first()?;
    let Argument::CallExpression(call) = first else {
        return None;
    };
    let member = call.callee.get_member_expr()?;
    if member.static_property_name()? != "map" {
        return None;
    }
    finite_record_iterable_from_expression(
        member.object(),
        constants,
        object_maps,
        enum_member_domains,
        record_iterables,
        record_maps,
    )
}

fn finite_record_from_expression(
    expression: &Expression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
    record_iterables: &FiniteRecordBindings,
    record_maps: &FiniteRecordMaps,
) -> Option<FiniteRecords> {
    match expression.get_inner_expression() {
        Expression::ObjectExpression(object) => Some(vec![finite_record_from_object(
            object,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        )?]),
        Expression::Identifier(identifier) => {
            record_iterables.get(identifier.name.as_str()).cloned()
        }
        Expression::ComputedMemberExpression(member) => {
            let object = member.object.get_identifier_reference()?;
            record_iterables.get(object.name.as_str()).cloned()
        }
        Expression::CallExpression(call) => {
            let member = call.callee.get_member_expr()?;
            if member.static_property_name()? != "get" {
                return None;
            }
            let object = member.object().get_identifier_reference()?;
            record_maps.get(object.name.as_str()).cloned()
        }
        Expression::LogicalExpression(logical) => {
            if logical.operator == LogicalOperator::Coalesce {
                let left = finite_record_from_expression(
                    &logical.left,
                    constants,
                    object_maps,
                    enum_member_domains,
                    record_iterables,
                    record_maps,
                );
                let right = finite_record_from_expression(
                    &logical.right,
                    constants,
                    object_maps,
                    enum_member_domains,
                    record_iterables,
                    record_maps,
                );
                match (left, right) {
                    (Some(left), Some(right)) => merge_finite_records(left, right),
                    (Some(values), None) | (None, Some(values)) => Some(values),
                    (None, None) => None,
                }
            } else {
                None
            }
        }
        Expression::ConditionalExpression(conditional) => {
            let consequent = finite_record_from_expression(
                &conditional.consequent,
                constants,
                object_maps,
                enum_member_domains,
                record_iterables,
                record_maps,
            );
            let alternate = finite_record_from_expression(
                &conditional.alternate,
                constants,
                object_maps,
                enum_member_domains,
                record_iterables,
                record_maps,
            );
            match (consequent, alternate) {
                (Some(consequent), Some(alternate)) => merge_finite_records(consequent, alternate),
                (Some(values), None) | (None, Some(values)) => Some(values),
                (None, None) => None,
            }
        }
        Expression::TSNonNullExpression(expression) => finite_record_from_expression(
            &expression.expression,
            constants,
            object_maps,
            enum_member_domains,
            record_iterables,
            record_maps,
        ),
        _ => None,
    }
}

fn finite_strings_from_array_element(
    element: &ArrayExpressionElement<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    iterables: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    match element {
        ArrayExpressionElement::StringLiteral(literal) => {
            Some(finite_string(literal.value.to_string()))
        }
        ArrayExpressionElement::TemplateLiteral(literal) => {
            finite_strings_from_template(literal, constants, object_maps, enum_member_domains)
        }
        ArrayExpressionElement::Identifier(identifier) => {
            constants.get(identifier.name.as_str()).cloned()
        }
        ArrayExpressionElement::CallExpression(call) => {
            finite_strings_from_call(call, constants, object_maps, enum_member_domains)
        }
        ArrayExpressionElement::ComputedMemberExpression(member) => {
            finite_strings_from_computed_member(member, constants, object_maps, enum_member_domains)
        }
        ArrayExpressionElement::StaticMemberExpression(member) => {
            finite_strings_from_static_member(member, object_maps, enum_member_domains)
        }
        ArrayExpressionElement::ConditionalExpression(conditional) => {
            finite_strings_from_conditional(
                conditional,
                constants,
                object_maps,
                enum_member_domains,
            )
        }
        ArrayExpressionElement::ParenthesizedExpression(parenthesized) => {
            finite_strings_from_expression(
                &parenthesized.expression,
                constants,
                object_maps,
                enum_member_domains,
            )
        }
        ArrayExpressionElement::TSAsExpression(expression) => finite_iterable_from_expression(
            &expression.expression,
            constants,
            iterables,
            object_maps,
            enum_member_domains,
        )
        .or_else(|| {
            finite_strings_from_expression(
                &expression.expression,
                constants,
                object_maps,
                enum_member_domains,
            )
        }),
        ArrayExpressionElement::TSSatisfiesExpression(expression) => {
            finite_iterable_from_expression(
                &expression.expression,
                constants,
                iterables,
                object_maps,
                enum_member_domains,
            )
            .or_else(|| {
                finite_strings_from_expression(
                    &expression.expression,
                    constants,
                    object_maps,
                    enum_member_domains,
                )
            })
        }
        ArrayExpressionElement::TSNonNullExpression(expression) => finite_iterable_from_expression(
            &expression.expression,
            constants,
            iterables,
            object_maps,
            enum_member_domains,
        )
        .or_else(|| {
            finite_strings_from_expression(
                &expression.expression,
                constants,
                object_maps,
                enum_member_domains,
            )
        }),
        ArrayExpressionElement::TSInstantiationExpression(expression) => {
            finite_iterable_from_expression(
                &expression.expression,
                constants,
                iterables,
                object_maps,
                enum_member_domains,
            )
            .or_else(|| {
                finite_strings_from_expression(
                    &expression.expression,
                    constants,
                    object_maps,
                    enum_member_domains,
                )
            })
        }
        ArrayExpressionElement::TSTypeAssertion(expression) => finite_iterable_from_expression(
            &expression.expression,
            constants,
            iterables,
            object_maps,
            enum_member_domains,
        )
        .or_else(|| {
            finite_strings_from_expression(
                &expression.expression,
                constants,
                object_maps,
                enum_member_domains,
            )
        }),
        _ => None,
    }
}

fn finite_strings_from_call(
    call: &CallExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    if !call.arguments.is_empty() {
        return None;
    }

    let member = call.callee.get_member_expr()?;
    let method = member.static_property_name()?;
    let values = finite_strings_from_expression(
        member.object(),
        constants,
        object_maps,
        enum_member_domains,
    )?;

    transform_finite_strings(values, &method)
}

fn transform_finite_strings(values: FiniteStrings, method: &str) -> Option<FiniteStrings> {
    let transformed = match method {
        "toLowerCase" => values
            .into_iter()
            .map(|value| value.to_lowercase())
            .collect(),
        "toUpperCase" => values
            .into_iter()
            .map(|value| value.to_uppercase())
            .collect(),
        _ => return None,
    };
    Some(transformed)
}

fn finite_strings_from_conditional(
    conditional: &ConditionalExpression<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    let consequent = finite_strings_from_expression(
        &conditional.consequent,
        constants,
        object_maps,
        enum_member_domains,
    )?;
    let alternate = finite_strings_from_expression(
        &conditional.alternate,
        constants,
        object_maps,
        enum_member_domains,
    )?;
    union_finite_strings(consequent, alternate)
}

fn finite_strings_from_template(
    literal: &TemplateLiteral<'_>,
    constants: &BTreeMap<String, FiniteStrings>,
    object_maps: &FiniteObjectMaps,
    enum_member_domains: &TypeDomains,
) -> Option<FiniteStrings> {
    let mut values = finite_string("");
    for (index, quasi) in literal.quasis.iter().enumerate() {
        let cooked = quasi.value.cooked.as_ref()?;
        values = append_finite_strings(values, &finite_string(cooked.to_string()))?;

        if let Some(expression) = literal.expressions.get(index) {
            let expression_values = finite_strings_from_expression(
                expression,
                constants,
                object_maps,
                enum_member_domains,
            )?;
            values = append_finite_strings(values, &expression_values)?;
        }
    }
    Some(values)
}

