#[derive(Default)]
struct IdentifierReferenceCollector {
    names: BTreeSet<String>,
}

impl<'a> Visit<'a> for IdentifierReferenceCollector {
    fn visit_identifier_reference(&mut self, identifier: &IdentifierReference<'a>) {
        self.names.insert(identifier.name.to_string());
    }
}

fn referenced_identifier_names(expression: &Expression<'_>) -> BTreeSet<String> {
    let mut collector = IdentifierReferenceCollector::default();
    collector.visit_expression(expression);
    collector.names
}

#[derive(Default)]
struct ForwardedIdentifierCollector {
    names: BTreeSet<String>,
}

impl<'a> Visit<'a> for ForwardedIdentifierCollector {
    fn visit_identifier_reference(&mut self, identifier: &IdentifierReference<'a>) {
        self.names.insert(identifier.name.to_string());
    }

    fn visit_call_expression(&mut self, _call: &CallExpression<'a>) {}

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}

    fn visit_jsx_element(&mut self, _element: &JSXElement<'a>) {}

    fn visit_jsx_fragment(&mut self, _fragment: &oxc_ast::ast::JSXFragment<'a>) {}
}

fn forwarded_identifier_names(expression: &Expression<'_>) -> BTreeSet<String> {
    let mut collector = ForwardedIdentifierCollector::default();
    collector.visit_expression(expression);
    collector.names
}

#[derive(Default)]
struct FunctionVarBindingCollector {
    names: BTreeSet<String>,
}

impl<'a> Visit<'a> for FunctionVarBindingCollector {
    fn visit_variable_declaration(&mut self, declaration: &VariableDeclaration<'a>) {
        if declaration.kind == VariableDeclarationKind::Var {
            for declarator in &declaration.declarations {
                self.names.extend(
                    declarator
                        .id
                        .get_binding_identifiers()
                        .into_iter()
                        .map(|identifier| identifier.name.to_string()),
                );
            }
        }
        walk::walk_variable_declaration(self, declaration);
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

fn function_var_bindings(body: &FunctionBody<'_>) -> BTreeSet<String> {
    let mut collector = FunctionVarBindingCollector::default();
    collector.visit_function_body(body);
    collector.names
}

#[derive(Default)]
struct FunctionLocalBindingCollector {
    names: BTreeSet<String>,
}

impl<'a> Visit<'a> for FunctionLocalBindingCollector {
    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        self.names.extend(
            declarator
                .id
                .get_binding_identifiers()
                .into_iter()
                .map(|identifier| identifier.name.to_string()),
        );
        walk::walk_variable_declarator(self, declarator);
    }

    fn visit_function(&mut self, function: &Function<'a>, _flags: ScopeFlags) {
        if let Some(id) = &function.id {
            self.names.insert(id.name.to_string());
        }
    }

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}

    fn visit_catch_parameter(&mut self, parameter: &CatchParameter<'a>) {
        self.names.extend(
            parameter
                .pattern
                .get_binding_identifiers()
                .into_iter()
                .map(|identifier| identifier.name.to_string()),
        );
    }
}

fn function_local_bindings(body: &FunctionBody<'_>) -> BTreeSet<String> {
    let mut collector = FunctionLocalBindingCollector::default();
    collector.visit_function_body(body);
    collector.names
}

fn function_scope_bindings(body: &FunctionBody<'_>) -> BTreeSet<String> {
    let mut names = function_var_bindings(body);
    for statement in &body.statements {
        match statement {
            Statement::VariableDeclaration(declaration) => {
                names.extend(declaration.declarations.iter().flat_map(|declarator| {
                    declarator
                        .id
                        .get_binding_identifiers()
                        .into_iter()
                        .map(|identifier| identifier.name.to_string())
                }));
            }
            Statement::FunctionDeclaration(function) => {
                if let Some(id) = &function.id {
                    names.insert(id.name.to_string());
                }
            }
            Statement::ClassDeclaration(class) => {
                if let Some(id) = &class.id {
                    names.insert(id.name.to_string());
                }
            }
            _ => {}
        }
    }
    names
}

fn block_scope_bindings(statements: &[Statement<'_>]) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for statement in statements {
        match statement {
            Statement::VariableDeclaration(declaration)
                if declaration.kind != VariableDeclarationKind::Var =>
            {
                names.extend(declaration.declarations.iter().flat_map(|declarator| {
                    declarator
                        .id
                        .get_binding_identifiers()
                        .into_iter()
                        .map(|identifier| identifier.name.to_string())
                }));
            }
            Statement::FunctionDeclaration(function) => {
                if let Some(id) = &function.id {
                    names.insert(id.name.to_string());
                }
            }
            Statement::ClassDeclaration(class) => {
                if let Some(id) = &class.id {
                    names.insert(id.name.to_string());
                }
            }
            _ => {}
        }
    }
    names
}

