struct InlineWrapperReturnVisitor<'collector> {
    collector: &'collector ReactWrapperReturnCollector,
    returns_wrapper: bool,
}

#[derive(Default)]
struct FiniteBoundCaptureNameCollector {
    names: BTreeSet<String>,
}

impl<'a> Visit<'a> for FiniteBoundCaptureNameCollector {
    fn visit_identifier_reference(&mut self, identifier: &IdentifierReference<'a>) {
        self.names.insert(identifier.name.to_string());
    }
}

#[derive(Default)]
struct FiniteBoundFunctionDeclarationCollector {
    captures: BTreeMap<String, BTreeSet<String>>,
}

impl<'a> Visit<'a> for FiniteBoundFunctionDeclarationCollector {
    fn visit_function(&mut self, function: &Function<'a>, _flags: ScopeFlags) {
        if function.r#type == FunctionType::FunctionDeclaration
            && let Some(identifier) = &function.id
        {
            let mut collector = FiniteBoundCaptureNameCollector::default();
            collector.visit_function(function, ScopeFlags::empty());
            self.captures
                .entry(identifier.name.to_string())
                .or_default()
                .extend(collector.names);
        }
    }

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

impl<'a> Visit<'a> for InlineWrapperReturnVisitor<'_> {
    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        self.returns_wrapper |= statement
            .argument
            .as_ref()
            .is_some_and(|argument| self.collector.expression_returns_wrapper(argument));
        walk::walk_return_statement(self, statement);
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

impl ReactWrapperReturnCollector {
    fn finite_bound_function_declaration_captures(
        body: &FunctionBody<'_>,
    ) -> BTreeMap<String, BTreeSet<String>> {
        let mut collector = FiniteBoundFunctionDeclarationCollector::default();
        collector.visit_function_body(body);
        collector.captures
    }

    fn finite_bound_parameter_default_captures(
        params: &oxc_ast::ast::FormalParameters<'_>,
    ) -> BTreeMap<String, BTreeSet<String>> {
        let mut captures = BTreeMap::<String, BTreeSet<String>>::new();
        for param in &params.items {
            let mut collector = FiniteBoundCaptureNameCollector::default();
            collector.visit_binding_pattern(&param.pattern);
            if let Some(initializer) = &param.initializer {
                collector.visit_expression(initializer);
            }
            if collector.names.is_empty() {
                continue;
            }
            for identifier in param.pattern.get_binding_identifiers() {
                captures
                    .entry(identifier.name.to_string())
                    .or_default()
                    .extend(collector.names.iter().cloned());
            }
        }
        captures
    }

    fn seed_finite_bound_parameter_defaults(
        &mut self,
        params: &oxc_ast::ast::FormalParameters<'_>,
    ) {
        for (param_index, param) in params.items.iter().enumerate() {
            let Some(name) = binding_identifier_name(&param.pattern) else {
                continue;
            };
            let initializer = param.initializer.as_deref().or_else(|| {
                let BindingPattern::AssignmentPattern(assignment) = &param.pattern else {
                    return None;
                };
                Some(&assignment.right)
            });
            let Some(initializer) = initializer else {
                continue;
            };
            let Some(mut entry) = self.finite_bound_argument_entry(initializer) else {
                continue;
            };
            let Some(_values) = entry.values.as_mut() else {
                continue;
            };
            entry.unknown_parameter = Some(param_index);
            self.finite_bound_argument_arrays
                .insert(name.to_string(), entry);
        }
    }

    fn set_finite_bound_capture_declaration(
        &mut self,
        name: &str,
        captures: Option<BTreeSet<String>>,
    ) {
        let replaces_existing_callable = self.finite_bound_capture_callables.contains_key(name);
        let defines_callable = captures.is_some();
        if let Some(scope) = self.finite_bound_argument_scopes.last_mut() {
            scope
                .previous_capture_callables
                .entry(name.to_string())
                .or_insert_with(|| self.finite_bound_capture_callables.get(name).cloned());
            scope
                .previous_capture_provenance
                .entry(name.to_string())
                .or_insert_with(|| self.finite_bound_capture_provenance.get(name).cloned());
            scope
                .previous_resolved_capture_names
                .entry(name.to_string())
                .or_insert_with(|| self.finite_bound_resolved_capture_names.get(name).cloned());
        }
        self.replace_finite_bound_capture_value(name, captures);
        if defines_callable && !replaces_existing_callable {
            self.refresh_finite_bound_capture_dependents(name, true);
        }
    }

    fn finite_bound_capture_value_state(
        &self,
        captures: &BTreeSet<String>,
    ) -> (BTreeSet<usize>, BTreeSet<String>) {
        let provenance = self.finite_bound_capture_provenance(captures);
        let resolved_names = captures
            .iter()
            .filter(|capture| {
                !self
                    .finite_bound_capture_provenance(&BTreeSet::from([(*capture).clone()]))
                    .is_empty()
            })
            .cloned()
            .collect();
        (provenance, resolved_names)
    }

    fn replace_finite_bound_capture_value(
        &mut self,
        name: &str,
        captures: Option<BTreeSet<String>>,
    ) {
        if let Some(captures) = captures {
            let (provenance, resolved_names) = self.finite_bound_capture_value_state(&captures);
            self.finite_bound_capture_callables
                .insert(name.to_string(), captures);
            self.finite_bound_capture_provenance
                .insert(name.to_string(), provenance);
            self.finite_bound_resolved_capture_names
                .insert(name.to_string(), resolved_names);
        } else {
            self.finite_bound_capture_callables.remove(name);
            self.finite_bound_capture_provenance.remove(name);
            self.finite_bound_resolved_capture_names.remove(name);
        }
    }

    fn merge_finite_bound_capture_value(&mut self, name: &str, captures: BTreeSet<String>) {
        let (provenance, resolved_names) = self.finite_bound_capture_value_state(&captures);
        self.finite_bound_capture_callables
            .entry(name.to_string())
            .or_default()
            .extend(captures);
        self.finite_bound_capture_provenance
            .entry(name.to_string())
            .or_default()
            .extend(provenance);
        self.finite_bound_resolved_capture_names
            .entry(name.to_string())
            .or_default()
            .extend(resolved_names);
        self.refresh_finite_bound_capture_dependents(name, false);
    }

    fn replace_finite_bound_capture_value_and_refresh(
        &mut self,
        name: &str,
        captures: Option<BTreeSet<String>>,
    ) {
        self.replace_finite_bound_capture_value(name, captures);
        self.refresh_finite_bound_capture_dependents(name, false);
    }

    fn refresh_finite_bound_capture_dependents(
        &mut self,
        changed_name: &str,
        unresolved_only: bool,
    ) {
        let mut pending = vec![(changed_name.to_string(), unresolved_only)];
        let mut visited = BTreeSet::from([changed_name.to_string()]);
        while let Some((changed, unresolved_only)) = pending.pop() {
            let dependents = self
                .finite_bound_capture_callables
                .iter()
                .filter_map(|(name, captures)| {
                    (captures.contains(&changed)
                        && (!unresolved_only
                            || self
                                .finite_bound_resolved_capture_names
                                .get(name)
                                .is_none_or(|resolved| !resolved.contains(&changed))))
                    .then_some(name.clone())
                })
                .collect::<Vec<_>>();
            for dependent in dependents {
                let Some(captures) = self.finite_bound_capture_callables.get(&dependent).cloned()
                else {
                    continue;
                };
                let (provenance, resolved_names) = self.finite_bound_capture_value_state(&captures);
                self.finite_bound_capture_provenance
                    .insert(dependent.clone(), provenance);
                self.finite_bound_resolved_capture_names
                    .insert(dependent.clone(), resolved_names);
                if visited.insert(dependent.clone()) {
                    pending.push((dependent, false));
                }
            }
        }
    }

    fn finite_bound_capture_names(expression: &Expression<'_>) -> Option<BTreeSet<String>> {
        let mut collector = FiniteBoundCaptureNameCollector::default();
        match expression.get_inner_expression() {
            Expression::ArrowFunctionExpression(arrow) => {
                collector.visit_arrow_function_expression(arrow);
            }
            Expression::FunctionExpression(function) => {
                collector.visit_function(function, ScopeFlags::empty());
            }
            _ => return None,
        }
        Some(collector.names)
    }

    fn finite_bound_capture_names_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<BTreeSet<String>> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => {
                let captures =
                    self.finite_bound_capture_names_for_identifier(identifier.name.as_str());
                (!captures.is_empty()).then_some(captures)
            }
            Expression::ConditionalExpression(conditional) => {
                let mut captures = self
                    .finite_bound_capture_names_from_expression(&conditional.consequent)
                    .unwrap_or_default();
                captures.extend(
                    self.finite_bound_capture_names_from_expression(&conditional.alternate)
                        .unwrap_or_default(),
                );
                (!captures.is_empty()).then_some(captures)
            }
            Expression::LogicalExpression(logical) => {
                let mut captures = self
                    .finite_bound_capture_names_from_expression(&logical.left)
                    .unwrap_or_default();
                captures.extend(
                    self.finite_bound_capture_names_from_expression(&logical.right)
                        .unwrap_or_default(),
                );
                (!captures.is_empty()).then_some(captures)
            }
            Expression::AwaitExpression(await_expression) => {
                self.finite_bound_capture_names_from_expression(&await_expression.argument)
            }
            Expression::StaticMemberExpression(member) => {
                self.finite_bound_capture_names_from_expression(&member.object)
            }
            Expression::ComputedMemberExpression(member) => {
                self.finite_bound_capture_names_from_expression(&member.object)
            }
            Expression::ArrayExpression(array) => {
                let captures = array
                    .elements
                    .iter()
                    .flat_map(|element| match element {
                        ArrayExpressionElement::SpreadElement(spread) => self
                            .finite_bound_capture_names_from_expression(&spread.argument)
                            .unwrap_or_default(),
                        _ => element
                            .as_expression()
                            .and_then(|element| {
                                self.finite_bound_capture_names_from_expression(element)
                            })
                            .unwrap_or_default(),
                    })
                    .collect::<BTreeSet<_>>();
                (!captures.is_empty()).then_some(captures)
            }
            Expression::ObjectExpression(object) => {
                let captures = object
                    .properties
                    .iter()
                    .flat_map(|property| match property {
                        ObjectPropertyKind::ObjectProperty(property) => self
                            .finite_bound_capture_names_from_expression(&property.value)
                            .unwrap_or_default(),
                        ObjectPropertyKind::SpreadProperty(spread) => self
                            .finite_bound_capture_names_from_expression(&spread.argument)
                            .unwrap_or_default(),
                    })
                    .collect::<BTreeSet<_>>();
                (!captures.is_empty()).then_some(captures)
            }
            Expression::CallExpression(call) => {
                let mut captures = self
                    .finite_bound_capture_names_from_expression(&call.callee)
                    .unwrap_or_default();
                for argument in &call.arguments {
                    let argument = match argument {
                        Argument::SpreadElement(spread) => Some(&spread.argument),
                        _ => argument.as_expression(),
                    };
                    if let Some(argument) = argument {
                        captures.extend(
                            self.finite_bound_capture_names_from_expression(argument)
                                .unwrap_or_default(),
                        );
                    }
                }
                (!captures.is_empty()).then_some(captures)
            }
            Expression::NewExpression(new_expression) => {
                let mut captures = self
                    .finite_bound_capture_names_from_expression(&new_expression.callee)
                    .unwrap_or_default();
                for argument in &new_expression.arguments {
                    let argument = match argument {
                        Argument::SpreadElement(spread) => Some(&spread.argument),
                        _ => argument.as_expression(),
                    };
                    if let Some(argument) = argument {
                        captures.extend(
                            self.finite_bound_capture_names_from_expression(argument)
                                .unwrap_or_default(),
                        );
                    }
                }
                (!captures.is_empty()).then_some(captures)
            }
            Expression::AssignmentExpression(assignment) => {
                self.finite_bound_capture_names_from_expression(&assignment.right)
            }
            Expression::SequenceExpression(sequence) => sequence
                .expressions
                .last()
                .and_then(|expression| self.finite_bound_capture_names_from_expression(expression)),
            Expression::ClassExpression(class) => {
                let captures = Self::finite_bound_class_capture_names(class);
                (!captures.is_empty()).then_some(captures)
            }
            _ => Self::finite_bound_capture_names(expression),
        }
    }

    fn finite_bound_function_capture_names(function: &Function<'_>) -> BTreeSet<String> {
        let mut collector = FiniteBoundCaptureNameCollector::default();
        collector.visit_function(function, ScopeFlags::empty());
        collector.names
    }

    fn finite_bound_class_capture_names(class: &Class<'_>) -> BTreeSet<String> {
        let mut collector = FiniteBoundCaptureNameCollector::default();
        collector.visit_class(class);
        collector.names
    }

    fn finite_bound_binding_capture_names(pattern: &BindingPattern<'_>) -> BTreeSet<String> {
        let mut collector = FiniteBoundCaptureNameCollector::default();
        collector.visit_binding_pattern(pattern);
        collector.names
    }

    fn finite_bound_assignment_capture_names(target: &AssignmentTarget<'_>) -> BTreeSet<String> {
        let mut collector = FiniteBoundCaptureNameCollector::default();
        collector.visit_assignment_target(target);
        collector.names
    }

    fn finite_bound_capture_names_for_identifier(&self, name: &str) -> BTreeSet<String> {
        let mut captures = self
            .finite_bound_capture_callables
            .get(name)
            .cloned()
            .unwrap_or_default();
        if let Some(aliases) = self.finite_bound_capture_aliases.get(name) {
            for alias in aliases {
                if let Some(alias_captures) = self.finite_bound_capture_callables.get(alias) {
                    captures.extend(alias_captures.iter().cloned());
                }
            }
        }
        captures
    }

    fn link_finite_bound_capture_aliases(&mut self, left: &str, right: &str) {
        let mut aliases = self
            .finite_bound_capture_aliases
            .get(left)
            .cloned()
            .unwrap_or_default();
        aliases.extend(
            self.finite_bound_capture_aliases
                .get(right)
                .cloned()
                .unwrap_or_default(),
        );
        aliases.insert(left.to_string());
        aliases.insert(right.to_string());
        for alias in &aliases {
            self.finite_bound_capture_aliases
                .insert(alias.clone(), aliases.clone());
        }
    }

    fn finite_bound_capture_alias_sources(expression: &Expression<'_>) -> BTreeSet<String> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => BTreeSet::from([identifier.name.to_string()]),
            Expression::ConditionalExpression(conditional) => {
                let mut sources = Self::finite_bound_capture_alias_sources(&conditional.consequent);
                sources.extend(Self::finite_bound_capture_alias_sources(
                    &conditional.alternate,
                ));
                sources
            }
            Expression::LogicalExpression(logical) => {
                let mut sources = Self::finite_bound_capture_alias_sources(&logical.left);
                sources.extend(Self::finite_bound_capture_alias_sources(&logical.right));
                sources
            }
            Expression::AwaitExpression(await_expression) => {
                Self::finite_bound_capture_alias_sources(&await_expression.argument)
            }
            Expression::SequenceExpression(sequence) => sequence
                .expressions
                .last()
                .map(Self::finite_bound_capture_alias_sources)
                .unwrap_or_default(),
            Expression::AssignmentExpression(assignment) => {
                Self::finite_bound_capture_alias_sources(&assignment.right)
            }
            Expression::StaticMemberExpression(member) => {
                expression_member_root_name(&member.object)
                    .map(|name| BTreeSet::from([name.to_string()]))
                    .unwrap_or_default()
            }
            Expression::ComputedMemberExpression(member) => {
                expression_member_root_name(&member.object)
                    .map(|name| BTreeSet::from([name.to_string()]))
                    .unwrap_or_default()
            }
            Expression::ArrayExpression(array) => array
                .elements
                .iter()
                .flat_map(|element| match element {
                    ArrayExpressionElement::SpreadElement(spread) => {
                        Self::finite_bound_capture_alias_sources(&spread.argument)
                    }
                    _ => element
                        .as_expression()
                        .map(Self::finite_bound_capture_alias_sources)
                        .unwrap_or_default(),
                })
                .collect(),
            Expression::ObjectExpression(object) => object
                .properties
                .iter()
                .flat_map(|property| match property {
                    ObjectPropertyKind::ObjectProperty(property) => {
                        Self::finite_bound_capture_alias_sources(&property.value)
                    }
                    ObjectPropertyKind::SpreadProperty(spread) => {
                        Self::finite_bound_capture_alias_sources(&spread.argument)
                    }
                })
                .collect(),
            _ => BTreeSet::new(),
        }
    }

    fn finite_bound_capture_provenance(&self, names: &BTreeSet<String>) -> BTreeSet<usize> {
        fn collect(
            collector: &ReactWrapperReturnCollector,
            name: &str,
            visited: &mut BTreeSet<String>,
            provenance: &mut BTreeSet<usize>,
        ) {
            if !visited.insert(name.to_string()) {
                return;
            }
            let aliases = collector
                .finite_bound_capture_aliases
                .get(name)
                .cloned()
                .unwrap_or_else(|| BTreeSet::from([name.to_string()]));
            for alias in aliases {
                if let Some(entry) = collector.finite_bound_argument_arrays.get(&alias) {
                    provenance.extend(entry.provenance.iter().copied());
                }
                if let Some(captures) = collector.finite_bound_capture_callables.get(&alias) {
                    for capture in captures {
                        collect(collector, capture, visited, provenance);
                    }
                }
            }
        }

        let mut visited = BTreeSet::new();
        let mut provenance = BTreeSet::new();
        for name in names {
            collect(self, name, &mut visited, &mut provenance);
        }
        provenance
    }

    fn expanded_finite_bound_capture_names(&self, names: &BTreeSet<String>) -> BTreeSet<String> {
        fn collect(
            collector: &ReactWrapperReturnCollector,
            name: &str,
            visited: &mut BTreeSet<String>,
        ) {
            if !visited.insert(name.to_string()) {
                return;
            }
            for capture in collector.finite_bound_capture_names_for_identifier(name) {
                collect(collector, &capture, visited);
            }
        }

        let mut expanded = BTreeSet::new();
        for name in names {
            collect(self, name, &mut expanded);
        }
        expanded
    }

    fn record_escaped_finite_bound_captures(&mut self, names: BTreeSet<String>) {
        let expanded = self.expanded_finite_bound_capture_names(&names);
        let provenance = self.finite_bound_capture_provenance(&expanded);
        self.invalidate_finite_bound_argument_provenance(provenance);
        self.escaped_finite_bound_capture_names.extend(expanded);
    }

    fn set_finite_bound_argument_declaration(
        &mut self,
        name: &str,
        value: Option<FiniteBoundArgumentEntry>,
    ) {
        if let Some(scope) = self.finite_bound_argument_scopes.last_mut() {
            scope
                .previous
                .entry(name.to_string())
                .or_insert_with(|| self.finite_bound_argument_arrays.get(name).cloned());
        }
        if let Some(value) = value {
            let provenance = value.provenance.clone();
            self.finite_bound_argument_arrays
                .insert(name.to_string(), value);
            let pending = self
                .finite_bound_capture_callables
                .iter()
                .filter_map(|(callable, captures)| {
                    (captures.contains(name)
                        && self
                            .finite_bound_resolved_capture_names
                            .get(callable)
                            .is_none_or(|resolved| !resolved.contains(name)))
                    .then_some(callable.clone())
                })
                .collect::<Vec<_>>();
            for callable in pending {
                self.finite_bound_capture_provenance
                    .entry(callable.clone())
                    .or_default()
                    .extend(provenance.iter().copied());
                self.finite_bound_resolved_capture_names
                    .entry(callable.clone())
                    .or_default()
                    .insert(name.to_string());
                self.refresh_finite_bound_capture_dependents(&callable, false);
            }
        } else {
            self.finite_bound_argument_arrays.remove(name);
        }
    }

    fn finite_bound_argument_entry(
        &mut self,
        expression: &Expression<'_>,
    ) -> Option<FiniteBoundArgumentEntry> {
        let values = self.finite_bound_arguments(expression);
        let mut provenance = self.finite_bound_argument_provenance(expression);
        if values.is_none() && provenance.is_empty() {
            return None;
        }
        if provenance.is_empty() {
            let id = self.next_finite_bound_argument_provenance;
            self.next_finite_bound_argument_provenance += 1;
            provenance.insert(id);
        }
        let spread_provenance = self.finite_bound_spread_provenance(expression);
        Some(FiniteBoundArgumentEntry {
            values,
            provenance,
            spread_provenance,
            unknown_parameter: None,
        })
    }

    fn invalidate_finite_bound_argument_provenance(&mut self, provenance: BTreeSet<usize>) {
        self.invalidated_finite_bound_argument_provenance
            .extend(provenance.iter().copied());
        self.finite_bound_argument_arrays
            .retain(|_, entry| entry.provenance.is_disjoint(&provenance));
    }

    fn finite_bound_carrier_entry(
        provenance: &BTreeSet<usize>,
    ) -> Option<FiniteBoundArgumentEntry> {
        (!provenance.is_empty()).then(|| FiniteBoundArgumentEntry {
            values: None,
            provenance: provenance.clone(),
            spread_provenance: provenance.clone(),
            unknown_parameter: None,
        })
    }

    fn finite_bound_binding_default_provenance(
        &self,
        pattern: &BindingPattern<'_>,
    ) -> BTreeSet<usize> {
        match pattern {
            BindingPattern::BindingIdentifier(_) => BTreeSet::new(),
            BindingPattern::AssignmentPattern(assignment) => {
                let mut provenance = self.finite_bound_argument_provenance(&assignment.right);
                provenance.extend(self.finite_bound_binding_default_provenance(&assignment.left));
                provenance
            }
            BindingPattern::ObjectPattern(object) => object
                .properties
                .iter()
                .flat_map(|property| self.finite_bound_binding_default_provenance(&property.value))
                .chain(
                    object.rest.iter().flat_map(|rest| {
                        self.finite_bound_binding_default_provenance(&rest.argument)
                    }),
                )
                .collect(),
            BindingPattern::ArrayPattern(array) => {
                array
                    .elements
                    .iter()
                    .flatten()
                    .flat_map(|element| self.finite_bound_binding_default_provenance(element))
                    .chain(array.rest.iter().flat_map(|rest| {
                        self.finite_bound_binding_default_provenance(&rest.argument)
                    }))
                    .collect()
            }
        }
    }

    fn finite_bound_assignment_default_provenance(
        &self,
        target: &AssignmentTarget<'_>,
    ) -> BTreeSet<usize> {
        match target {
            AssignmentTarget::ArrayAssignmentTarget(array) => {
                self.finite_bound_array_assignment_default_provenance(array)
            }
            AssignmentTarget::ObjectAssignmentTarget(object) => {
                self.finite_bound_object_assignment_default_provenance(object)
            }
            _ => BTreeSet::new(),
        }
    }

    fn finite_bound_array_assignment_default_provenance(
        &self,
        array: &ArrayAssignmentTarget<'_>,
    ) -> BTreeSet<usize> {
        array
            .elements
            .iter()
            .flatten()
            .flat_map(|element| self.finite_bound_maybe_default_provenance(element))
            .chain(
                array
                    .rest
                    .iter()
                    .flat_map(|rest| self.finite_bound_assignment_default_provenance(&rest.target)),
            )
            .collect()
    }

    fn finite_bound_object_assignment_default_provenance(
        &self,
        object: &ObjectAssignmentTarget<'_>,
    ) -> BTreeSet<usize> {
        object
            .properties
            .iter()
            .flat_map(|property| match property {
                AssignmentTargetProperty::AssignmentTargetPropertyIdentifier(property) => property
                    .init
                    .as_ref()
                    .map(|init| self.finite_bound_argument_provenance(init))
                    .unwrap_or_default(),
                AssignmentTargetProperty::AssignmentTargetPropertyProperty(property) => {
                    self.finite_bound_maybe_default_provenance(&property.binding)
                }
            })
            .chain(
                object
                    .rest
                    .iter()
                    .flat_map(|rest| self.finite_bound_assignment_default_provenance(&rest.target)),
            )
            .collect()
    }

    fn finite_bound_maybe_default_provenance(
        &self,
        target: &AssignmentTargetMaybeDefault<'_>,
    ) -> BTreeSet<usize> {
        match target {
            AssignmentTargetMaybeDefault::AssignmentTargetWithDefault(default) => {
                let mut provenance = self.finite_bound_argument_provenance(&default.init);
                provenance
                    .extend(self.finite_bound_assignment_default_provenance(&default.binding));
                provenance
            }
            AssignmentTargetMaybeDefault::ArrayAssignmentTarget(array) => {
                self.finite_bound_array_assignment_default_provenance(array)
            }
            AssignmentTargetMaybeDefault::ObjectAssignmentTarget(object) => {
                self.finite_bound_object_assignment_default_provenance(object)
            }
            _ => BTreeSet::new(),
        }
    }

    fn argument_param_combinations(
        &self,
        call: &CallExpression<'_>,
    ) -> Vec<(
        Vec<Option<usize>>,
        BTreeMap<usize, BTreeSet<WrapperCallableTarget>>,
        BTreeSet<usize>,
    )> {
        let mut combinations = Vec::new();
        let argument_count = call.arguments.len();
        let argument_targets = call
            .arguments
            .iter()
            .enumerate()
            .filter_map(|(index, argument)| {
                let expression = argument.as_expression()?.get_inner_expression();
                let targets = self.wrapper_callable_targets(expression);
                (!targets.is_empty()).then_some((index, targets))
            })
            .collect::<BTreeMap<_, _>>();
        let wrapper_arguments = call
            .arguments
            .iter()
            .enumerate()
            .filter_map(|(index, argument)| {
                argument
                    .as_expression()
                    .is_some_and(|argument| self.inline_expression_returns_wrapper(argument))
                    .then_some(index)
            })
            .collect::<BTreeSet<_>>();
        for (argument_index, argument) in call.arguments.iter().enumerate() {
            let params = argument
                .as_expression()
                .map(|expression| {
                    self.forwards_from_expression(expression)
                        .into_iter()
                        .filter_map(|forward| match forward {
                            TranslatorReturnForward::ParameterCall { param_index, .. } => {
                                Some(param_index)
                            }
                            _ => None,
                        })
                        .collect::<BTreeSet<_>>()
                })
                .unwrap_or_default();
            for param in params {
                let mut combination = vec![None; argument_count];
                combination[argument_index] = Some(param);
                combinations.push((
                    combination,
                    argument_targets.clone(),
                    wrapper_arguments.clone(),
                ));
            }
        }
        if combinations.is_empty() {
            combinations.push((
                vec![None; argument_count],
                argument_targets,
                wrapper_arguments,
            ));
        }
        combinations
    }

    fn wrapper_callable_targets(
        &self,
        expression: &Expression<'_>,
    ) -> BTreeSet<WrapperCallableTarget> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => BTreeSet::from([WrapperCallableTarget::new(
                None,
                identifier.name.to_string(),
            )]),
            Expression::ConditionalExpression(conditional) => {
                let mut targets = self.wrapper_callable_targets(&conditional.consequent);
                targets.extend(self.wrapper_callable_targets(&conditional.alternate));
                targets
            }
            Expression::LogicalExpression(logical) => {
                let mut targets = self.wrapper_callable_targets(&logical.left);
                targets.extend(self.wrapper_callable_targets(&logical.right));
                targets
            }
            Expression::AwaitExpression(await_expression) => {
                self.wrapper_callable_targets(&await_expression.argument)
            }
            Expression::CallExpression(call)
                if call
                    .callee
                    .get_member_expr()
                    .is_some_and(|member| member.static_property_name() == Some("bind")) =>
            {
                let mut targets = self.wrapper_callable_targets(
                    call.callee
                        .get_member_expr()
                        .expect("bind member checked")
                        .object(),
                );
                let mut fixed_arguments = Vec::<BoundArgumentEvidence>::new();
                let mut unknown_arguments = Vec::<BoundArgumentEvidence>::new();
                let mut unknown_position = None;
                let mut unconditional_unknown = false;
                for argument in call.arguments.iter().skip(1) {
                    match argument {
                        Argument::SpreadElement(spread) => {
                            if let Some(arguments) = self.finite_bound_arguments(&spread.argument) {
                                let default_parameter =
                                    self.finite_bound_unknown_parameter(&spread.argument);
                                let default_start = fixed_arguments.len();
                                if unknown_position.is_some() {
                                    unknown_arguments.extend(arguments);
                                } else {
                                    fixed_arguments.extend(arguments);
                                }
                                if let Some(param_index) = default_parameter {
                                    if unknown_position.is_none() {
                                        unknown_position = Some(default_start);
                                    }
                                    let mut evidence = BoundArgumentEvidence::default();
                                    evidence.params.insert(param_index);
                                    unknown_arguments.push(evidence);
                                }
                            } else {
                                if unknown_position.is_none() {
                                    unknown_position = Some(fixed_arguments.len());
                                }
                                unconditional_unknown = true;
                                unknown_arguments
                                    .push(self.bound_argument_evidence(&spread.argument));
                            }
                        }
                        _ => {
                            let evidence = argument
                                .as_expression()
                                .map(|argument| self.bound_argument_evidence(argument))
                                .unwrap_or_default();
                            if unknown_position.is_some() {
                                unknown_arguments.push(evidence);
                            } else {
                                fixed_arguments.push(evidence);
                            }
                        }
                    }
                }
                let fixed_count = fixed_arguments.len();
                let fixed_argument_targets = fixed_arguments
                    .iter()
                    .enumerate()
                    .filter_map(|(index, argument)| {
                        (!argument.targets.is_empty()).then_some((index, argument.targets.clone()))
                    })
                    .collect::<BTreeMap<_, _>>();
                let fixed_wrapper_arguments = fixed_arguments
                    .iter()
                    .enumerate()
                    .filter_map(|(index, argument)| argument.wrapper.then_some(index))
                    .collect::<BTreeSet<_>>();
                let fixed_argument_params = fixed_arguments
                    .iter()
                    .enumerate()
                    .filter_map(|(index, argument)| {
                        (!argument.params.is_empty()).then_some((index, argument.params.clone()))
                    })
                    .collect::<BTreeMap<_, _>>();
                let unknown_targets = unknown_arguments
                    .iter()
                    .flat_map(|argument| argument.targets.iter().cloned())
                    .collect::<BTreeSet<_>>();
                let unknown_params = unknown_arguments
                    .iter()
                    .flat_map(|argument| argument.params.iter().copied())
                    .collect::<BTreeSet<_>>();
                let unknown_may_wrap = unconditional_unknown
                    || unknown_arguments.iter().any(|argument| argument.wrapper);
                targets = targets
                    .into_iter()
                    .map(|mut target| {
                        if target.bound_unknown_from.is_some() {
                            target.bound_unknown_may_wrap |= unknown_may_wrap;
                            target
                                .bound_unknown_targets
                                .extend(unknown_targets.iter().cloned());
                            target.bound_unknown_targets.extend(
                                fixed_argument_targets
                                    .values()
                                    .flat_map(|targets| targets.iter().cloned()),
                            );
                            target.bound_unknown_params.extend(
                                fixed_argument_params
                                    .values()
                                    .flat_map(|params| params.iter().copied()),
                            );
                            target
                                .bound_unknown_params
                                .extend(unknown_params.iter().copied());
                            target.bound_unknown_may_wrap |= !fixed_wrapper_arguments.is_empty();
                            return target;
                        }
                        let offset = target.bound_argument_count;
                        for (index, targets) in &fixed_argument_targets {
                            target
                                .bound_argument_targets
                                .entry(offset + index)
                                .or_default()
                                .extend(targets.iter().cloned());
                        }
                        for (index, params) in &fixed_argument_params {
                            target
                                .bound_argument_params
                                .entry(offset + index)
                                .or_default()
                                .extend(params.iter().copied());
                        }
                        target
                            .bound_wrapper_arguments
                            .extend(fixed_wrapper_arguments.iter().map(|index| offset + index));
                        target.bound_argument_count += fixed_count;
                        if let Some(unknown_position) = unknown_position {
                            target.bound_unknown_from = Some(offset + unknown_position);
                            target.bound_unknown_may_wrap = unknown_may_wrap;
                            target.bound_unknown_targets = unknown_targets.clone();
                            target.bound_unknown_params = unknown_params.clone();
                        }
                        target
                    })
                    .collect();
                targets
            }
            expression => expression
                .get_member_expr()
                .and_then(|member| {
                    Some(WrapperCallableTarget::new(
                        Some(member.object().get_identifier_reference()?.name.to_string()),
                        member.static_property_name()?.to_string(),
                    ))
                })
                .into_iter()
                .collect(),
        }
    }

    fn bound_argument_evidence(&self, expression: &Expression<'_>) -> BoundArgumentEvidence {
        BoundArgumentEvidence {
            targets: self.wrapper_callable_targets(expression),
            wrapper: self.inline_expression_returns_wrapper(expression),
            params: self
                .forwards_from_expression(expression)
                .into_iter()
                .filter_map(|forward| match forward {
                    TranslatorReturnForward::ParameterCall { param_index, .. } => Some(param_index),
                    _ => None,
                })
                .collect(),
        }
    }

    fn finite_bound_arguments(
        &self,
        expression: &Expression<'_>,
    ) -> Option<Vec<BoundArgumentEvidence>> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .finite_bound_argument_arrays
                .get(identifier.name.as_str())
                .and_then(|entry| entry.values.clone()),
            Expression::ArrayExpression(array) => {
                let mut values = Vec::new();
                for element in &array.elements {
                    match element {
                        ArrayExpressionElement::SpreadElement(spread) => {
                            values.extend(self.finite_bound_arguments(&spread.argument)?);
                        }
                        ArrayExpressionElement::Elision(_) => {
                            values.push(BoundArgumentEvidence::default());
                        }
                        _ => values.push(self.bound_argument_evidence(element.as_expression()?)),
                    }
                }
                Some(values)
            }
            Expression::ConditionalExpression(conditional) => {
                let mut consequent = self.finite_bound_arguments(&conditional.consequent)?;
                let alternate = self.finite_bound_arguments(&conditional.alternate)?;
                if consequent.len() != alternate.len() {
                    return None;
                }
                for (target, other) in consequent.iter_mut().zip(alternate) {
                    target.targets.extend(other.targets);
                    target.wrapper |= other.wrapper;
                    target.params.extend(other.params);
                }
                Some(consequent)
            }
            Expression::LogicalExpression(logical) => {
                let mut left = self.finite_bound_arguments(&logical.left)?;
                let right = self.finite_bound_arguments(&logical.right)?;
                if left.len() != right.len() {
                    return None;
                }
                for (target, other) in left.iter_mut().zip(right) {
                    target.targets.extend(other.targets);
                    target.wrapper |= other.wrapper;
                    target.params.extend(other.params);
                }
                Some(left)
            }
            _ => None,
        }
    }

    fn finite_bound_unknown_parameter(&self, expression: &Expression<'_>) -> Option<usize> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .finite_bound_argument_arrays
                .get(identifier.name.as_str())
                .and_then(|entry| entry.unknown_parameter),
            Expression::ConditionalExpression(conditional) => {
                let consequent = self.finite_bound_unknown_parameter(&conditional.consequent);
                let alternate = self.finite_bound_unknown_parameter(&conditional.alternate);
                (consequent == alternate).then_some(consequent).flatten()
            }
            Expression::LogicalExpression(logical) => {
                let left = self.finite_bound_unknown_parameter(&logical.left);
                let right = self.finite_bound_unknown_parameter(&logical.right);
                (left == right).then_some(left).flatten()
            }
            _ => None,
        }
    }

    fn finite_bound_argument_provenance(&self, expression: &Expression<'_>) -> BTreeSet<usize> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => {
                self.finite_bound_identifier_provenance(identifier.name.as_str())
            }
            Expression::ConditionalExpression(conditional) => {
                let mut provenance = self.finite_bound_argument_provenance(&conditional.consequent);
                provenance.extend(self.finite_bound_argument_provenance(&conditional.alternate));
                provenance
            }
            Expression::LogicalExpression(logical) => {
                let mut provenance = self.finite_bound_argument_provenance(&logical.left);
                provenance.extend(self.finite_bound_argument_provenance(&logical.right));
                provenance
            }
            Expression::StaticMemberExpression(member) => {
                self.finite_bound_argument_provenance(&member.object)
            }
            Expression::ComputedMemberExpression(member) => {
                self.finite_bound_argument_provenance(&member.object)
            }
            Expression::PrivateFieldExpression(member) => {
                self.finite_bound_argument_provenance(&member.object)
            }
            Expression::CallExpression(call) => call
                .arguments
                .iter()
                .flat_map(|argument| self.finite_bound_call_argument_provenance(argument))
                .collect(),
            Expression::NewExpression(new_expression) => new_expression
                .arguments
                .iter()
                .flat_map(|argument| self.finite_bound_call_argument_provenance(argument))
                .collect(),
            Expression::AssignmentExpression(assignment) => {
                if let AssignmentTarget::AssignmentTargetIdentifier(identifier) = &assignment.left
                    && let Some(entry) = self
                        .finite_bound_argument_arrays
                        .get(identifier.name.as_str())
                {
                    entry.provenance.clone()
                } else {
                    self.finite_bound_argument_provenance(&assignment.right)
                }
            }
            Expression::SequenceExpression(sequence) => sequence
                .expressions
                .last()
                .map(|expression| self.finite_bound_argument_provenance(expression))
                .unwrap_or_default(),
            Expression::AwaitExpression(await_expression) => {
                self.finite_bound_argument_provenance(&await_expression.argument)
            }
            Expression::ArrowFunctionExpression(_) | Expression::FunctionExpression(_) => {
                Self::finite_bound_capture_names(expression)
                    .map(|names| self.finite_bound_capture_provenance(&names))
                    .unwrap_or_default()
            }
            Expression::ArrayExpression(array) => array
                .elements
                .iter()
                .filter_map(ArrayExpressionElement::as_expression)
                .flat_map(|expression| self.finite_bound_argument_provenance(expression))
                .collect(),
            Expression::ObjectExpression(object) => object
                .properties
                .iter()
                .flat_map(|property| match property {
                    ObjectPropertyKind::ObjectProperty(property) => {
                        self.finite_bound_argument_provenance(&property.value)
                    }
                    ObjectPropertyKind::SpreadProperty(spread) => {
                        self.finite_bound_argument_provenance(&spread.argument)
                    }
                })
                .collect(),
            _ => BTreeSet::new(),
        }
    }

    fn finite_bound_identifier_provenance(&self, name: &str) -> BTreeSet<usize> {
        let mut provenance = self
            .finite_bound_argument_arrays
            .get(name)
            .map(|entry| entry.provenance.clone())
            .unwrap_or_default();
        if let Some(captured) = self.finite_bound_capture_provenance.get(name) {
            provenance.extend(captured.iter().copied());
        } else if let Some(names) = self.finite_bound_capture_callables.get(name) {
            provenance.extend(self.finite_bound_capture_provenance(names));
        }
        if let Some(aliases) = self.finite_bound_capture_aliases.get(name) {
            for alias in aliases {
                if let Some(captured) = self.finite_bound_capture_provenance.get(alias) {
                    provenance.extend(captured.iter().copied());
                }
            }
        }
        provenance
    }

    fn finite_bound_call_argument_provenance(&self, argument: &Argument<'_>) -> BTreeSet<usize> {
        match argument {
            Argument::SpreadElement(spread) => {
                self.finite_bound_spread_provenance(&spread.argument)
            }
            _ => argument
                .as_expression()
                .map(|argument| self.finite_bound_argument_provenance(argument))
                .unwrap_or_default(),
        }
    }

    fn finite_bound_spread_provenance(&self, expression: &Expression<'_>) -> BTreeSet<usize> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .finite_bound_argument_arrays
                .get(identifier.name.as_str())
                .map(|entry| entry.spread_provenance.clone())
                .unwrap_or_default(),
            Expression::ConditionalExpression(conditional) => {
                let mut provenance = self.finite_bound_spread_provenance(&conditional.consequent);
                provenance.extend(self.finite_bound_spread_provenance(&conditional.alternate));
                provenance
            }
            Expression::LogicalExpression(logical) => {
                let mut provenance = self.finite_bound_spread_provenance(&logical.left);
                provenance.extend(self.finite_bound_spread_provenance(&logical.right));
                provenance
            }
            Expression::ArrayExpression(array) => array
                .elements
                .iter()
                .flat_map(|element| match element {
                    ArrayExpressionElement::SpreadElement(spread) => {
                        self.finite_bound_spread_provenance(&spread.argument)
                    }
                    _ => element
                        .as_expression()
                        .map(|element| self.finite_bound_argument_provenance(element))
                        .unwrap_or_default(),
                })
                .collect(),
            Expression::StaticMemberExpression(member) => {
                self.finite_bound_spread_provenance(&member.object)
            }
            Expression::ComputedMemberExpression(member) => {
                self.finite_bound_spread_provenance(&member.object)
            }
            Expression::AwaitExpression(await_expression) => {
                self.finite_bound_spread_provenance(&await_expression.argument)
            }
            Expression::AssignmentExpression(assignment) => {
                if let AssignmentTarget::AssignmentTargetIdentifier(identifier) = &assignment.left
                    && let Some(entry) = self
                        .finite_bound_argument_arrays
                        .get(identifier.name.as_str())
                {
                    entry.spread_provenance.clone()
                } else {
                    self.finite_bound_spread_provenance(&assignment.right)
                }
            }
            Expression::SequenceExpression(sequence) => sequence
                .expressions
                .last()
                .map(|expression| self.finite_bound_spread_provenance(expression))
                .unwrap_or_default(),
            _ => BTreeSet::new(),
        }
    }

    fn finite_bound_expression_is_known_array(&self, expression: &Expression<'_>) -> bool {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .finite_bound_argument_arrays
                .get(identifier.name.as_str())
                .is_some_and(|entry| entry.values.is_some()),
            Expression::ArrayExpression(_) => true,
            Expression::ConditionalExpression(conditional) => {
                self.finite_bound_expression_is_known_array(&conditional.consequent)
                    && self.finite_bound_expression_is_known_array(&conditional.alternate)
            }
            Expression::LogicalExpression(logical) => {
                self.finite_bound_expression_is_known_array(&logical.left)
                    && self.finite_bound_expression_is_known_array(&logical.right)
            }
            Expression::AwaitExpression(await_expression) => {
                self.finite_bound_expression_is_known_array(&await_expression.argument)
            }
            _ => false,
        }
    }

    fn inline_expression_returns_wrapper(&self, expression: &Expression<'_>) -> bool {
        let (body, expression_body) = match expression.get_inner_expression() {
            Expression::ArrowFunctionExpression(arrow) => (&*arrow.body, arrow.expression),
            Expression::FunctionExpression(function) => {
                let Some(body) = &function.body else {
                    return false;
                };
                (&**body, false)
            }
            Expression::ConditionalExpression(conditional) => {
                return self.inline_expression_returns_wrapper(&conditional.consequent)
                    || self.inline_expression_returns_wrapper(&conditional.alternate);
            }
            Expression::LogicalExpression(logical) => {
                return self.inline_expression_returns_wrapper(&logical.left)
                    || self.inline_expression_returns_wrapper(&logical.right);
            }
            _ => return false,
        };
        if expression_body
            && let Some(Statement::ExpressionStatement(statement)) = body.statements.first()
            && body.statements.len() == 1
            && self.expression_returns_wrapper(&statement.expression)
        {
            return true;
        }
        let mut visitor = InlineWrapperReturnVisitor {
            collector: self,
            returns_wrapper: false,
        };
        visitor.visit_function_body(body);
        visitor.returns_wrapper
    }

    fn structured_member_path(&self, expression: &Expression<'_>) -> Option<(String, String)> {
        let mut path = Vec::new();
        let root = expression_static_member_path(expression, &mut path)?;
        Some((root.to_string(), path.join(".")))
    }

    fn structured_member_is_wrapper(&self, root: &str, path: &str) -> bool {
        self.structured_unknown_values.contains(root)
            || self
                .wrapper_member_values
                .iter()
                .any(|(candidate_root, candidate)| {
                    candidate_root == root
                        && (candidate == path
                            || path
                                .strip_prefix(candidate)
                                .is_some_and(|suffix| suffix.starts_with('.')))
                })
    }

    fn structured_member_forwards(
        &self,
        root: &str,
        path: &str,
    ) -> BTreeSet<TranslatorReturnForward> {
        self.forward_member_values
            .iter()
            .filter(|((candidate_root, candidate), _)| {
                candidate_root == root
                    && (candidate == path
                        || path
                            .strip_prefix(candidate)
                            .is_some_and(|suffix| suffix.starts_with('.')))
            })
            .flat_map(|(_, forwards)| forwards.iter().cloned())
            .collect()
    }

    fn record_structured_value(&mut self, root: &str, expression: &Expression<'_>, prefix: &str) {
        if let Expression::ObjectExpression(object) = expression.get_inner_expression() {
            for property in &object.properties {
                match property {
                    ObjectPropertyKind::ObjectProperty(property) if !property.computed => {
                        let Some(name) = property.key.static_name() else {
                            continue;
                        };
                        let path = if prefix.is_empty() {
                            name.to_string()
                        } else {
                            format!("{prefix}.{name}")
                        };
                        let path_prefix = format!("{path}.");
                        self.structured_resolved_values
                            .insert((root.to_string(), path.clone()));
                        self.wrapper_member_values
                            .retain(|(candidate_root, candidate)| {
                                candidate_root != root
                                    || (candidate != &path && !candidate.starts_with(&path_prefix))
                            });
                        self.forward_member_values
                            .retain(|(candidate_root, candidate), _| {
                                candidate_root != root
                                    || (candidate != &path && !candidate.starts_with(&path_prefix))
                            });
                        if matches!(
                            property.value.get_inner_expression(),
                            Expression::ObjectExpression(_)
                        ) {
                            self.record_structured_value(root, &property.value, &path);
                            continue;
                        }
                        let key = (root.to_string(), path);
                        if self.expression_returns_wrapper(&property.value) {
                            self.wrapper_member_values.insert(key.clone());
                        }
                        let forwards = self.forwards_from_expression(&property.value);
                        if !forwards.is_empty() {
                            self.forward_member_values.insert(key, forwards);
                        }
                    }
                    ObjectPropertyKind::ObjectProperty(property) => {
                        if self.expression_returns_wrapper(&property.value)
                            || !self.forwards_from_expression(&property.value).is_empty()
                        {
                            self.structured_unknown_values.insert(root.to_string());
                        }
                    }
                    ObjectPropertyKind::SpreadProperty(spread) => {
                        let Some(source) = spread.argument.get_identifier_reference() else {
                            self.structured_unknown_values.insert(root.to_string());
                            continue;
                        };
                        let source = source.name.as_str();
                        let wrappers = self
                            .wrapper_member_values
                            .iter()
                            .filter(|(candidate, _)| candidate == source)
                            .map(|(_, path)| path.clone())
                            .collect::<Vec<_>>();
                        let forwards = self
                            .forward_member_values
                            .iter()
                            .filter(|((candidate, _), _)| candidate == source)
                            .map(|((_, path), forwards)| (path.clone(), forwards.clone()))
                            .collect::<Vec<_>>();
                        let resolved = self
                            .structured_resolved_values
                            .iter()
                            .filter(|(candidate, _)| candidate == source)
                            .map(|(_, path)| path.clone())
                            .collect::<Vec<_>>();
                        for source_path in resolved {
                            let path = if prefix.is_empty() {
                                source_path
                            } else {
                                format!("{prefix}.{source_path}")
                            };
                            let path_prefix = format!("{path}.");
                            self.wrapper_member_values
                                .retain(|(candidate_root, candidate)| {
                                    candidate_root != root
                                        || (candidate != &path
                                            && !candidate.starts_with(&path_prefix))
                                });
                            self.forward_member_values
                                .retain(|(candidate_root, candidate), _| {
                                    candidate_root != root
                                        || (candidate != &path
                                            && !candidate.starts_with(&path_prefix))
                                });
                            self.structured_resolved_values
                                .insert((root.to_string(), path));
                        }
                        for source_path in wrappers {
                            let path = if prefix.is_empty() {
                                source_path
                            } else {
                                format!("{prefix}.{source_path}")
                            };
                            let path_prefix = format!("{path}.");
                            self.wrapper_member_values
                                .retain(|(candidate_root, candidate)| {
                                    candidate_root != root
                                        || (candidate != &path
                                            && !candidate.starts_with(&path_prefix))
                                });
                            self.wrapper_member_values.insert((root.to_string(), path));
                        }
                        for (source_path, values) in forwards {
                            let path = if prefix.is_empty() {
                                source_path
                            } else {
                                format!("{prefix}.{source_path}")
                            };
                            let path_prefix = format!("{path}.");
                            self.forward_member_values
                                .retain(|(candidate_root, candidate), _| {
                                    candidate_root != root
                                        || (candidate != &path
                                            && !candidate.starts_with(&path_prefix))
                                });
                            self.forward_member_values
                                .insert((root.to_string(), path), values);
                        }
                        if self.structured_unknown_values.contains(source) {
                            self.structured_unknown_values.insert(root.to_string());
                        }
                    }
                }
            }
        }
    }

    fn call_is_wrapper(&self, call: &CallExpression<'_>, name: &str) -> bool {
        if let Some(identifier) = call.callee.get_identifier_reference() {
            let names = if name == "useMemo" {
                &self.memo_identifiers
            } else {
                &self.state_identifiers
            };
            return names.contains(identifier.name.as_str());
        }
        call.callee.get_member_expr().is_some_and(|member| {
            member.static_property_name() == Some(name)
                && member
                    .object()
                    .get_identifier_reference()
                    .is_some_and(|identifier| self.namespaces.contains(identifier.name.as_str()))
        })
    }

    fn call_is_transparent_wrapper_container(&self, call: &CallExpression<'_>) -> bool {
        call.callee.get_member_expr().is_some_and(|member| {
            let owner = member
                .object()
                .get_identifier_reference()
                .map(|identifier| identifier.name.as_str());
            owner.is_some_and(|owner| self.transparent_namespaces.contains(owner))
                && matches!(
                    (owner, member.static_property_name()),
                    (Some("Promise"), Some("resolve" | "all" | "allSettled"))
                        | (Some("Array"), Some("from" | "of"))
                        | (Some("Object"), Some("freeze" | "seal"))
                )
        })
    }

    fn transparent_wrapper_arguments<'a>(
        &self,
        call: &'a CallExpression<'a>,
    ) -> impl Iterator<Item = &'a Expression<'a>> {
        call.arguments.iter().filter_map(|argument| match argument {
            Argument::SpreadElement(spread) => Some(&spread.argument),
            _ => argument.as_expression(),
        })
    }

    fn expression_returns_wrapper(&self, expression: &Expression<'_>) -> bool {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => {
                self.wrapper_values.contains(identifier.name.as_str())
            }
            Expression::CallExpression(call) => {
                self.call_is_wrapper(call, "useMemo")
                    || call
                        .callee
                        .get_identifier_reference()
                        .is_some_and(|identifier| {
                            self.known_wrapper_helpers
                                .contains(identifier.name.as_str())
                        })
                    || (self.call_is_transparent_wrapper_container(call)
                        && self
                            .transparent_wrapper_arguments(call)
                            .any(|argument| self.expression_returns_wrapper(argument)))
            }
            Expression::AwaitExpression(await_expression) => {
                self.expression_returns_wrapper(&await_expression.argument)
            }
            Expression::ArrayExpression(array) => array.elements.iter().any(|element| {
                element
                    .as_expression()
                    .is_some_and(|expression| self.expression_returns_wrapper(expression))
            }),
            Expression::ObjectExpression(object) => {
                object.properties.iter().any(|property| match property {
                    ObjectPropertyKind::ObjectProperty(property) => {
                        self.expression_returns_wrapper(&property.value)
                    }
                    ObjectPropertyKind::SpreadProperty(spread) => {
                        self.expression_returns_wrapper(&spread.argument)
                    }
                })
            }
            Expression::StaticMemberExpression(member) => {
                if let Some((root, path)) = self.structured_member_path(expression)
                    && self.structured_values.contains(&root)
                {
                    self.structured_member_is_wrapper(&root, &path)
                } else {
                    self.expression_returns_wrapper(&member.object)
                }
            }
            Expression::ComputedMemberExpression(member) => {
                if let Some(object) = member.object.get_identifier_reference()
                    && self.structured_values.contains(object.name.as_str())
                {
                    member.static_property_name().map_or_else(
                        || {
                            self.structured_unknown_values
                                .contains(object.name.as_str())
                                || self
                                    .wrapper_member_values
                                    .iter()
                                    .any(|(root, _)| root == object.name.as_str())
                        },
                        |property| {
                            self.structured_member_is_wrapper(
                                object.name.as_str(),
                                property.as_ref(),
                            )
                        },
                    )
                } else {
                    self.expression_returns_wrapper(&member.object)
                }
            }
            Expression::NewExpression(new_expression)
                if new_expression
                    .callee
                    .get_identifier_reference()
                    .is_some_and(|identifier| {
                        matches!(identifier.name.as_str(), "Map" | "Set")
                            && self
                                .transparent_namespaces
                                .contains(identifier.name.as_str())
                    }) =>
            {
                new_expression
                    .arguments
                    .iter()
                    .any(|argument| match argument {
                        Argument::SpreadElement(spread) => {
                            self.expression_returns_wrapper(&spread.argument)
                        }
                        _ => argument
                            .as_expression()
                            .is_some_and(|argument| self.expression_returns_wrapper(argument)),
                    })
            }
            Expression::ConditionalExpression(conditional) => {
                self.expression_returns_wrapper(&conditional.consequent)
                    || self.expression_returns_wrapper(&conditional.alternate)
            }
            Expression::LogicalExpression(logical) => {
                self.expression_returns_wrapper(&logical.left)
                    || self.expression_returns_wrapper(&logical.right)
            }
            _ => false,
        }
    }

    fn forwards_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> BTreeSet<TranslatorReturnForward> {
        let mut forwards = BTreeSet::new();
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => {
                if let Some(param_index) = self
                    .parameter_callables
                    .get(identifier.name.as_str())
                    .copied()
                {
                    forwards.insert(TranslatorReturnForward::ParameterCall {
                        param_index,
                        binding: dynamic_translator_binding(),
                    });
                }
                forwards.extend(
                    self.forward_values
                        .get(identifier.name.as_str())
                        .into_iter()
                        .flatten()
                        .cloned(),
                );
            }
            Expression::CallExpression(call)
                if self.call_is_transparent_wrapper_container(call) =>
            {
                for argument in self.transparent_wrapper_arguments(call) {
                    forwards.extend(self.forwards_from_expression(argument));
                }
            }
            Expression::CallExpression(call)
                if !self.call_is_wrapper(call, "useMemo")
                    && !self.call_is_wrapper(call, "useState") =>
            {
                if let Some(identifier) = call.callee.get_identifier_reference() {
                    if let Some(param_index) = self
                        .parameter_callables
                        .get(identifier.name.as_str())
                        .copied()
                    {
                        forwards.insert(TranslatorReturnForward::ParameterCall {
                            param_index,
                            binding: dynamic_translator_binding(),
                        });
                    } else {
                        forwards.extend(self.argument_param_combinations(call).into_iter().map(
                            |(argument_params, argument_targets, wrapper_arguments)| {
                                TranslatorReturnForward::ForwardCall {
                                    namespace: None,
                                    name: identifier.name.to_string(),
                                    argument_params,
                                    argument_targets,
                                    wrapper_arguments,
                                }
                            },
                        ));
                    }
                } else if let Some(member) = call.callee.get_member_expr()
                    && let (Some(namespace), Some(name)) = (
                        member.object().get_identifier_reference(),
                        member.static_property_name(),
                    )
                {
                    forwards.extend(self.argument_param_combinations(call).into_iter().map(
                        |(argument_params, argument_targets, wrapper_arguments)| {
                            TranslatorReturnForward::ForwardCall {
                                namespace: Some(namespace.name.to_string()),
                                name: name.to_string(),
                                argument_params,
                                argument_targets,
                                wrapper_arguments,
                            }
                        },
                    ));
                }
            }
            Expression::AwaitExpression(await_expression) => {
                forwards.extend(self.forwards_from_expression(&await_expression.argument));
            }
            Expression::ArrayExpression(array) => {
                for element in &array.elements {
                    if let Some(expression) = element.as_expression() {
                        forwards.extend(self.forwards_from_expression(expression));
                    }
                }
            }
            Expression::ObjectExpression(object) => {
                for property in &object.properties {
                    let expression = match property {
                        ObjectPropertyKind::ObjectProperty(property) => &property.value,
                        ObjectPropertyKind::SpreadProperty(spread) => &spread.argument,
                    };
                    forwards.extend(self.forwards_from_expression(expression));
                }
            }
            Expression::StaticMemberExpression(member) => {
                if let Some((root, path)) = self.structured_member_path(expression)
                    && self.structured_values.contains(&root)
                {
                    forwards.extend(self.structured_member_forwards(&root, &path));
                } else {
                    forwards.extend(self.forwards_from_expression(&member.object));
                }
            }
            Expression::ComputedMemberExpression(member) => {
                if let Some(object) = member.object.get_identifier_reference()
                    && self.structured_values.contains(object.name.as_str())
                {
                    if let Some(property) = member.static_property_name() {
                        forwards.extend(
                            self.structured_member_forwards(
                                object.name.as_str(),
                                property.as_ref(),
                            ),
                        );
                    } else {
                        forwards.extend(
                            self.forward_member_values
                                .iter()
                                .filter(|((root, _), _)| root == object.name.as_str())
                                .flat_map(|(_, values)| values.iter().cloned()),
                        );
                    }
                } else {
                    forwards.extend(self.forwards_from_expression(&member.object));
                }
            }
            Expression::NewExpression(new_expression)
                if new_expression
                    .callee
                    .get_identifier_reference()
                    .is_some_and(|identifier| {
                        matches!(identifier.name.as_str(), "Map" | "Set")
                            && self
                                .transparent_namespaces
                                .contains(identifier.name.as_str())
                    }) =>
            {
                for argument in &new_expression.arguments {
                    let expression = match argument {
                        Argument::SpreadElement(spread) => Some(&spread.argument),
                        _ => argument.as_expression(),
                    };
                    if let Some(expression) = expression {
                        forwards.extend(self.forwards_from_expression(expression));
                    }
                }
            }
            Expression::ConditionalExpression(conditional) => {
                forwards.extend(self.forwards_from_expression(&conditional.consequent));
                forwards.extend(self.forwards_from_expression(&conditional.alternate));
            }
            Expression::LogicalExpression(logical) => {
                forwards.extend(self.forwards_from_expression(&logical.left));
                forwards.extend(self.forwards_from_expression(&logical.right));
            }
            _ => {}
        }
        forwards
    }

    fn collect_forwards(&mut self, expression: &Expression<'_>) {
        self.forwards
            .extend(self.forwards_from_expression(expression));
    }

    fn array_summary_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> (
        BTreeSet<usize>,
        BTreeMap<usize, BTreeSet<TranslatorReturnForward>>,
    ) {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => (
                self.array_index_values
                    .get(identifier.name.as_str())
                    .cloned()
                    .unwrap_or_default(),
                self.array_index_forward_values
                    .get(identifier.name.as_str())
                    .cloned()
                    .unwrap_or_default(),
            ),
            Expression::AwaitExpression(await_expression) => {
                self.array_summary_from_expression(&await_expression.argument)
            }
            Expression::CallExpression(call)
                if call.callee.get_member_expr().is_some_and(|member| {
                    member.static_property_name() == Some("all")
                        && member
                            .object()
                            .get_identifier_reference()
                            .is_some_and(|identifier| identifier.name == "Promise")
                }) =>
            {
                let Some(Expression::ArrayExpression(array)) = call
                    .arguments
                    .first()
                    .and_then(Argument::as_expression)
                    .map(Expression::get_inner_expression)
                else {
                    return Default::default();
                };
                let mut indexes = BTreeSet::new();
                let mut forwards = BTreeMap::new();
                for (index, expression) in
                    array
                        .elements
                        .iter()
                        .enumerate()
                        .filter_map(|(index, element)| {
                            element
                                .as_expression()
                                .map(|expression| (index, expression))
                        })
                {
                    if self.expression_returns_wrapper(expression) {
                        indexes.insert(index);
                    } else {
                        let candidates = self.forwards_from_expression(expression);
                        if !candidates.is_empty() {
                            forwards.insert(index, candidates);
                        }
                    }
                }
                (indexes, forwards)
            }
            Expression::ConditionalExpression(conditional) => {
                let (mut indexes, mut forwards) =
                    self.array_summary_from_expression(&conditional.consequent);
                let (other_indexes, other_forwards) =
                    self.array_summary_from_expression(&conditional.alternate);
                indexes.extend(other_indexes);
                for (index, candidates) in other_forwards {
                    forwards.entry(index).or_default().extend(candidates);
                }
                (indexes, forwards)
            }
            Expression::LogicalExpression(logical) => {
                let (mut indexes, mut forwards) = self.array_summary_from_expression(&logical.left);
                let (other_indexes, other_forwards) =
                    self.array_summary_from_expression(&logical.right);
                indexes.extend(other_indexes);
                for (index, candidates) in other_forwards {
                    forwards.entry(index).or_default().extend(candidates);
                }
                (indexes, forwards)
            }
            _ => Default::default(),
        }
    }

    fn collect_array_summary(&mut self, expression: &Expression<'_>) {
        let (indexes, forwards) = self.array_summary_from_expression(expression);
        self.array_indexes.extend(indexes);
        for (index, candidates) in forwards {
            if !self.array_indexes.contains(&index) {
                self.array_index_forwards
                    .entry(index)
                    .or_default()
                    .extend(candidates);
            }
        }
    }
}

impl<'a> Visit<'a> for ReactWrapperReturnCollector {
    fn enter_node(&mut self, kind: AstKind<'a>) {
        if matches!(
            kind,
            AstKind::LogicalExpression(_)
                | AstKind::ConditionalExpression(_)
                | AstKind::IfStatement(_)
                | AstKind::DoWhileStatement(_)
                | AstKind::WhileStatement(_)
                | AstKind::ForStatement(_)
                | AstKind::ForInStatement(_)
                | AstKind::ForOfStatement(_)
                | AstKind::SwitchStatement(_)
                | AstKind::TryStatement(_)
        ) {
            self.conditional_control_flow_depth += 1;
        }
    }

    fn leave_node(&mut self, kind: AstKind<'a>) {
        if matches!(
            kind,
            AstKind::LogicalExpression(_)
                | AstKind::ConditionalExpression(_)
                | AstKind::IfStatement(_)
                | AstKind::DoWhileStatement(_)
                | AstKind::WhileStatement(_)
                | AstKind::ForStatement(_)
                | AstKind::ForInStatement(_)
                | AstKind::ForOfStatement(_)
                | AstKind::SwitchStatement(_)
                | AstKind::TryStatement(_)
        ) {
            self.conditional_control_flow_depth -= 1;
        }
    }

    fn enter_scope(&mut self, _flags: ScopeFlags, _scope_id: &Cell<Option<ScopeId>>) {
        self.finite_bound_argument_scopes
            .push(FiniteBoundArgumentScope::default());
    }

    fn leave_scope(&mut self) {
        if let Some(scope) = self.finite_bound_argument_scopes.pop() {
            self.invalidate_finite_bound_argument_provenance(scope.disposal_provenance);
            for (name, previous) in scope.previous {
                if let Some(previous) = previous {
                    if self
                        .invalidated_finite_bound_argument_provenance
                        .is_disjoint(&previous.provenance)
                    {
                        self.finite_bound_argument_arrays.insert(name, previous);
                    }
                } else {
                    self.finite_bound_argument_arrays.remove(&name);
                }
            }
            for (name, previous) in scope.previous_capture_callables {
                if let Some(previous) = previous {
                    self.finite_bound_capture_callables.insert(name, previous);
                } else {
                    self.finite_bound_capture_callables.remove(&name);
                }
            }
            for (name, previous) in scope.previous_capture_provenance {
                if let Some(previous) = previous {
                    self.finite_bound_capture_provenance.insert(name, previous);
                } else {
                    self.finite_bound_capture_provenance.remove(&name);
                }
            }
            for (name, previous) in scope.previous_resolved_capture_names {
                if let Some(previous) = previous {
                    self.finite_bound_resolved_capture_names
                        .insert(name, previous);
                } else {
                    self.finite_bound_resolved_capture_names.remove(&name);
                }
            }
        }
    }

    fn visit_catch_parameter(&mut self, parameter: &CatchParameter<'a>) {
        for identifier in parameter.pattern.get_binding_identifiers() {
            self.set_finite_bound_argument_declaration(identifier.name.as_str(), None);
            self.set_finite_bound_capture_declaration(identifier.name.as_str(), None);
        }
        walk::walk_catch_parameter(self, parameter);
    }

    fn visit_with_statement(&mut self, statement: &WithStatement<'a>) {
        self.visit_expression(&statement.object);
        let captures = self
            .finite_bound_capture_names_from_expression(&statement.object)
            .unwrap_or_default();
        self.record_escaped_finite_bound_captures(captures);
        let provenance = self.finite_bound_argument_provenance(&statement.object);
        self.invalidate_finite_bound_argument_provenance(provenance);
        self.enter_scope(ScopeFlags::With, &statement.scope_id);
        self.visit_statement(&statement.body);
        self.leave_scope();
    }

    fn visit_for_of_statement(&mut self, statement: &ForOfStatement<'a>) {
        let names = match &statement.left {
            ForStatementLeft::VariableDeclaration(declaration) => declaration
                .declarations
                .iter()
                .flat_map(|declarator| declarator.id.get_binding_identifiers())
                .map(|identifier| identifier.name.to_string())
                .collect::<Vec<_>>(),
            _ => {
                let mut names = Vec::new();
                if let Some(target) = statement.left.as_assignment_target() {
                    assignment_target_identifier_names(target, &mut names);
                }
                names
            }
        };
        let captures = self
            .finite_bound_capture_names_from_expression(&statement.right)
            .unwrap_or_default();
        let disposes_iteration_values = matches!(
            &statement.left,
            ForStatementLeft::VariableDeclaration(declaration)
                if matches!(
                    declaration.kind,
                    VariableDeclarationKind::Using | VariableDeclarationKind::AwaitUsing
                )
        );
        let mut iteration_provenance = BTreeSet::new();
        if !self.finite_bound_expression_is_known_array(&statement.right) {
            iteration_provenance.extend(self.finite_bound_argument_provenance(&statement.right));
        }
        if statement.r#await {
            iteration_provenance.extend(self.finite_bound_capture_provenance(&captures));
        }
        if disposes_iteration_values {
            iteration_provenance.extend(self.finite_bound_capture_provenance(&captures));
            self.record_escaped_finite_bound_captures(captures.clone());
        }
        self.invalidate_finite_bound_argument_provenance(iteration_provenance);
        let alias_sources = Self::finite_bound_capture_alias_sources(&statement.right);
        let assigns_existing_bindings =
            !matches!(statement.left, ForStatementLeft::VariableDeclaration(_));
        let previous = names
            .iter()
            .map(|name| {
                (
                    name.clone(),
                    self.finite_bound_capture_callables.get(name).cloned(),
                    self.finite_bound_capture_provenance.get(name).cloned(),
                    self.finite_bound_resolved_capture_names.get(name).cloned(),
                )
            })
            .collect::<Vec<_>>();
        for name in &names {
            for source in &alias_sources {
                self.link_finite_bound_capture_aliases(name, source);
            }
            let captures = (!captures.is_empty()).then(|| captures.clone());
            if assigns_existing_bindings {
                if let Some(captures) = captures {
                    self.merge_finite_bound_capture_value(name, captures);
                }
            } else {
                self.replace_finite_bound_capture_value(name, captures);
            }
        }
        walk::walk_for_of_statement(self, statement);
        if disposes_iteration_values {
            let provenance = self.finite_bound_capture_provenance(&captures);
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
        if !assigns_existing_bindings {
            for (name, captures, provenance, resolved_names) in previous {
                if let Some(captures) = captures {
                    self.finite_bound_capture_callables
                        .insert(name.clone(), captures);
                } else {
                    self.finite_bound_capture_callables.remove(&name);
                }
                if let Some(provenance) = provenance {
                    self.finite_bound_capture_provenance
                        .insert(name.clone(), provenance);
                } else {
                    self.finite_bound_capture_provenance.remove(&name);
                }
                if let Some(resolved_names) = resolved_names {
                    self.finite_bound_resolved_capture_names
                        .insert(name, resolved_names);
                } else {
                    self.finite_bound_resolved_capture_names.remove(&name);
                }
            }
        }
    }

    fn visit_call_expression(&mut self, call: &CallExpression<'a>) {
        let suppressed_span = call.callee.get_member_expr().map(GetSpan::span);
        if let Some(span) = suppressed_span {
            self.suppressed_member_read_spans
                .push((span.start, span.end));
        }
        walk::walk_call_expression(self, call);
        if suppressed_span.is_some() {
            self.suppressed_member_read_spans.pop();
        }
        let mut escaped_captures = self
            .finite_bound_capture_names_from_expression(&call.callee)
            .unwrap_or_default();
        for argument in &call.arguments {
            let argument = match argument {
                Argument::SpreadElement(spread) => Some(&spread.argument),
                _ => argument.as_expression(),
            };
            if let Some(argument) = argument {
                escaped_captures.extend(
                    self.finite_bound_capture_names_from_expression(argument)
                        .unwrap_or_default(),
                );
            }
        }
        self.record_escaped_finite_bound_captures(escaped_captures);
        let mut invalidated_provenance = BTreeSet::new();
        if call.callee.get_member_expr().is_none() {
            invalidated_provenance.extend(self.finite_bound_argument_provenance(&call.callee));
        }
        if let Some(member) = call.callee.get_member_expr() {
            let receiver_provenance = self.finite_bound_argument_provenance(member.object());
            let known_nonmutating = self.finite_bound_expression_is_known_array(member.object())
                && member.static_property_name().is_some_and(|method| {
                    matches!(
                        method,
                        "at" | "entries"
                            | "includes"
                            | "indexOf"
                            | "keys"
                            | "lastIndexOf"
                            | "slice"
                            | "toReversed"
                            | "toSpliced"
                            | "values"
                            | "with"
                    )
                });
            if !known_nonmutating {
                invalidated_provenance.extend(receiver_provenance);
            }
        }
        for argument in &call.arguments {
            invalidated_provenance.extend(self.finite_bound_call_argument_provenance(argument));
        }
        if !invalidated_provenance.is_empty() {
            self.invalidate_finite_bound_argument_provenance(invalidated_provenance);
        }
        if let Some(member) = call.callee.get_member_expr()
            && member.static_property_name() == Some("assign")
            && member
                .object()
                .get_identifier_reference()
                .is_some_and(|identifier| identifier.name == "Object")
            && let Some(target) = call
                .arguments
                .first()
                .and_then(Argument::as_expression)
                .and_then(Expression::get_identifier_reference)
        {
            let root = target.name.to_string();
            self.structured_values.insert(root.clone());
            for source in call
                .arguments
                .iter()
                .skip(1)
                .filter_map(Argument::as_expression)
            {
                if let Expression::ObjectExpression(object) = source.get_inner_expression() {
                    for property in &object.properties {
                        if let ObjectPropertyKind::ObjectProperty(property) = property
                            && !property.computed
                            && let Some(name) = property.key.static_name()
                        {
                            let name = name.to_string();
                            let prefix = format!("{name}.");
                            self.wrapper_member_values
                                .retain(|(candidate_root, candidate)| {
                                    candidate_root != &root
                                        || (candidate != &name && !candidate.starts_with(&prefix))
                                });
                            self.forward_member_values
                                .retain(|(candidate_root, candidate), _| {
                                    candidate_root != &root
                                        || (candidate != &name && !candidate.starts_with(&prefix))
                                });
                        }
                    }
                    self.record_structured_value(&root, source, "");
                } else {
                    self.structured_unknown_values.insert(root.clone());
                }
            }
        }
    }

    fn visit_new_expression(&mut self, expression: &NewExpression<'a>) {
        walk::walk_new_expression(self, expression);
        let mut escaped_captures = self
            .finite_bound_capture_names_from_expression(&expression.callee)
            .unwrap_or_default();
        for argument in &expression.arguments {
            let argument = match argument {
                Argument::SpreadElement(spread) => Some(&spread.argument),
                _ => argument.as_expression(),
            };
            if let Some(argument) = argument {
                escaped_captures.extend(
                    self.finite_bound_capture_names_from_expression(argument)
                        .unwrap_or_default(),
                );
            }
        }
        self.record_escaped_finite_bound_captures(escaped_captures);
        let mut provenance = self.finite_bound_argument_provenance(&expression.callee);
        provenance.extend(
            expression
                .arguments
                .iter()
                .flat_map(|argument| self.finite_bound_call_argument_provenance(argument))
                .collect::<BTreeSet<_>>(),
        );
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_spread_element(&mut self, spread: &SpreadElement<'a>) {
        walk::walk_spread_element(self, spread);
        if !self.finite_bound_expression_is_known_array(&spread.argument) {
            let provenance = self.finite_bound_argument_provenance(&spread.argument);
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
    }

    fn visit_await_expression(&mut self, expression: &AwaitExpression<'a>) {
        walk::walk_await_expression(self, expression);
        if !self.finite_bound_expression_is_known_array(&expression.argument) {
            let provenance = self.finite_bound_argument_provenance(&expression.argument);
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
    }

    fn visit_import_expression(&mut self, expression: &ImportExpression<'a>) {
        walk::walk_import_expression(self, expression);
        let mut provenance = self.finite_bound_argument_provenance(&expression.source);
        if let Some(options) = &expression.options {
            provenance.extend(self.finite_bound_argument_provenance(options));
        }
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_throw_statement(&mut self, statement: &ThrowStatement<'a>) {
        walk::walk_throw_statement(self, statement);
        let captures = self
            .finite_bound_capture_names_from_expression(&statement.argument)
            .unwrap_or_default();
        self.record_escaped_finite_bound_captures(captures);
        let provenance = self.finite_bound_argument_provenance(&statement.argument);
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_yield_expression(&mut self, expression: &YieldExpression<'a>) {
        walk::walk_yield_expression(self, expression);
        let Some(argument) = &expression.argument else {
            return;
        };
        let captures = self
            .finite_bound_capture_names_from_expression(argument)
            .unwrap_or_default();
        self.record_escaped_finite_bound_captures(captures);
        let provenance = self.finite_bound_argument_provenance(argument);
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_tagged_template_expression(&mut self, expression: &TaggedTemplateExpression<'a>) {
        walk::walk_tagged_template_expression(self, expression);
        let mut escaped_captures = self
            .finite_bound_capture_names_from_expression(&expression.tag)
            .unwrap_or_default();
        for substitution in &expression.quasi.expressions {
            escaped_captures.extend(
                self.finite_bound_capture_names_from_expression(substitution)
                    .unwrap_or_default(),
            );
        }
        self.record_escaped_finite_bound_captures(escaped_captures);
        let mut provenance = self.finite_bound_argument_provenance(&expression.tag);
        for substitution in &expression.quasi.expressions {
            provenance.extend(self.finite_bound_argument_provenance(substitution));
        }
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_jsx_opening_element(&mut self, opening: &JSXOpeningElement<'a>) {
        walk::walk_jsx_opening_element(self, opening);
        let mut captures = BTreeSet::new();
        let mut provenance = BTreeSet::new();
        for attribute in &opening.attributes {
            let expression = match attribute {
                JSXAttributeItem::Attribute(attribute) => match &attribute.value {
                    Some(JSXAttributeValue::ExpressionContainer(container))
                        if !matches!(container.expression, JSXExpression::EmptyExpression(_)) =>
                    {
                        Some(container.expression.to_expression())
                    }
                    _ => None,
                },
                JSXAttributeItem::SpreadAttribute(spread) => Some(&spread.argument),
            };
            if let Some(expression) = expression {
                provenance.extend(self.finite_bound_argument_provenance(expression));
                captures.extend(
                    self.finite_bound_capture_names_from_expression(expression)
                        .unwrap_or_default(),
                );
            }
        }
        self.invalidate_finite_bound_argument_provenance(provenance);
        self.record_escaped_finite_bound_captures(captures);
    }

    fn visit_jsx_element(&mut self, element: &JSXElement<'a>) {
        walk::walk_jsx_element(self, element);
        let mut captures = match &element.opening_element.name {
            JSXElementName::Identifier(identifier) => {
                self.finite_bound_capture_names_for_identifier(identifier.name.as_str())
            }
            JSXElementName::IdentifierReference(identifier) => {
                self.finite_bound_capture_names_for_identifier(identifier.name.as_str())
            }
            JSXElementName::MemberExpression(member) => match &member.object {
                JSXMemberExpressionObject::IdentifierReference(identifier) => {
                    self.finite_bound_capture_names_for_identifier(identifier.name.as_str())
                }
                _ => BTreeSet::new(),
            },
            _ => BTreeSet::new(),
        };
        let mut provenance = match &element.opening_element.name {
            JSXElementName::Identifier(identifier) => {
                self.finite_bound_identifier_provenance(identifier.name.as_str())
            }
            JSXElementName::IdentifierReference(identifier) => {
                self.finite_bound_identifier_provenance(identifier.name.as_str())
            }
            JSXElementName::MemberExpression(member) => match &member.object {
                JSXMemberExpressionObject::IdentifierReference(identifier) => {
                    self.finite_bound_identifier_provenance(identifier.name.as_str())
                }
                _ => BTreeSet::new(),
            },
            _ => BTreeSet::new(),
        };
        for child in &element.children {
            let expression = match child {
                JSXChild::ExpressionContainer(container)
                    if !matches!(container.expression, JSXExpression::EmptyExpression(_)) =>
                {
                    Some(container.expression.to_expression())
                }
                JSXChild::Spread(spread) => Some(&spread.expression),
                _ => None,
            };
            if let Some(expression) = expression {
                provenance.extend(self.finite_bound_argument_provenance(expression));
                captures.extend(
                    self.finite_bound_capture_names_from_expression(expression)
                        .unwrap_or_default(),
                );
            }
        }
        self.invalidate_finite_bound_argument_provenance(provenance);
        self.record_escaped_finite_bound_captures(captures);
    }

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        walk::walk_return_statement(self, statement);
        if let Some(argument) = &statement.argument {
            self.direct |= self.expression_returns_wrapper(argument);
            self.collect_forwards(argument);
            self.collect_array_summary(argument);
        }
    }

    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        let Some(init) = &declarator.init else {
            return;
        };
        walk::walk_variable_declarator(self, declarator);
        if matches!(
            declarator.kind,
            VariableDeclarationKind::Using | VariableDeclarationKind::AwaitUsing
        ) {
            let captures = self
                .finite_bound_capture_names_from_expression(init)
                .unwrap_or_default();
            self.record_escaped_finite_bound_captures(captures);
            let provenance = self.finite_bound_argument_provenance(init);
            if let Some(scope) = self.finite_bound_argument_scopes.last_mut() {
                scope.disposal_provenance.extend(provenance.iter().copied());
            }
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
        let wrapper = self.expression_returns_wrapper(init);
        let forwards = self.forwards_from_expression(init);
        let (array_indexes, array_index_forwards) = self.array_summary_from_expression(init);
        if let BindingPattern::BindingIdentifier(identifier) = &declarator.id
            && let Expression::ObjectExpression(object) = init.get_inner_expression()
        {
            let name = identifier.name.to_string();
            self.structured_values.insert(name.clone());
            let _ = object;
            self.record_structured_value(&name, init, "");
        }
        let state = matches!(init.get_inner_expression(), Expression::CallExpression(call) if self.call_is_wrapper(call, "useState"));
        if wrapper {
            self.wrapper_values.extend(
                declarator
                    .id
                    .get_binding_identifiers()
                    .into_iter()
                    .map(|identifier| identifier.name.to_string()),
            );
        } else if state
            && let BindingPattern::ArrayPattern(pattern) = &declarator.id
            && let Some(Some(element)) = pattern.elements.first()
        {
            self.wrapper_values.extend(
                element
                    .get_binding_identifiers()
                    .into_iter()
                    .map(|identifier| identifier.name.to_string()),
            );
        }
        if !forwards.is_empty() {
            for identifier in declarator.id.get_binding_identifiers() {
                self.forward_values
                    .insert(identifier.name.to_string(), forwards.clone());
            }
        }
        if let BindingPattern::BindingIdentifier(identifier) = &declarator.id {
            let name = identifier.name.to_string();
            for source in Self::finite_bound_capture_alias_sources(init) {
                self.link_finite_bound_capture_aliases(&name, &source);
            }
            let captures = self
                .finite_bound_capture_names_from_expression(init)
                .unwrap_or_default();
            let captures = (!captures.is_empty()).then_some(captures);
            self.set_finite_bound_capture_declaration(&name, captures);
            let arguments = if self.escaped_finite_bound_capture_names.contains(&name) {
                None
            } else {
                self.finite_bound_argument_entry(init)
            };
            self.set_finite_bound_argument_declaration(&name, arguments);
            if !array_indexes.is_empty() {
                self.array_index_values
                    .insert(name.clone(), array_indexes.clone());
            }
            if !array_index_forwards.is_empty() {
                self.array_index_forward_values
                    .insert(name, array_index_forwards.clone());
            }
        } else {
            let mut provenance = self.finite_bound_argument_provenance(init);
            let invalidated_source = if self.finite_bound_expression_is_known_array(init) {
                BTreeSet::new()
            } else {
                provenance.clone()
            };
            self.invalidate_finite_bound_argument_provenance(invalidated_source.clone());
            provenance.extend(self.finite_bound_binding_default_provenance(&declarator.id));
            provenance.retain(|id| !invalidated_source.contains(id));
            let mut captures = self
                .finite_bound_capture_names_from_expression(init)
                .unwrap_or_default();
            captures.extend(Self::finite_bound_binding_capture_names(&declarator.id));
            let captures = (!captures.is_empty()).then_some(captures);
            let alias_sources = Self::finite_bound_capture_alias_sources(init);
            for identifier in declarator.id.get_binding_identifiers() {
                for source in &alias_sources {
                    self.link_finite_bound_capture_aliases(identifier.name.as_str(), source);
                }
                self.set_finite_bound_capture_declaration(
                    identifier.name.as_str(),
                    captures.clone(),
                );
                self.set_finite_bound_argument_declaration(
                    identifier.name.as_str(),
                    if self
                        .escaped_finite_bound_capture_names
                        .contains(identifier.name.as_str())
                    {
                        None
                    } else {
                        Self::finite_bound_carrier_entry(&provenance)
                    },
                );
            }
        }
    }

    fn visit_assignment_expression(&mut self, expression: &AssignmentExpression<'a>) {
        walk::walk_assignment_expression(self, expression);
        if expression.operator == AssignmentOperator::Assign
            && let AssignmentTarget::AssignmentTargetIdentifier(identifier) = &expression.left
        {
            let name = identifier.name.to_string();
            for source in Self::finite_bound_capture_alias_sources(&expression.right) {
                self.link_finite_bound_capture_aliases(&name, &source);
            }
            let captures = self
                .finite_bound_capture_names_from_expression(&expression.right)
                .unwrap_or_default();
            let captures = (!captures.is_empty()).then_some(captures);
            if self.conditional_control_flow_depth > 0 {
                if let Some(captures) = captures {
                    self.merge_finite_bound_capture_value(&name, captures);
                }
            } else {
                self.replace_finite_bound_capture_value_and_refresh(&name, captures);
            }
        }
        if matches!(
            expression.left,
            AssignmentTarget::ArrayAssignmentTarget(_)
                | AssignmentTarget::ObjectAssignmentTarget(_)
        ) {
            let mut names = Vec::new();
            assignment_target_identifier_names(&expression.left, &mut names);
            let mut captures = self
                .finite_bound_capture_names_from_expression(&expression.right)
                .unwrap_or_default();
            captures.extend(Self::finite_bound_assignment_capture_names(
                &expression.left,
            ));
            let captures = (!captures.is_empty()).then_some(captures);
            let alias_sources = Self::finite_bound_capture_alias_sources(&expression.right);
            for name in &names {
                for source in &alias_sources {
                    self.link_finite_bound_capture_aliases(name, source);
                }
            }
            if expression.operator == AssignmentOperator::Assign
                && self.conditional_control_flow_depth == 0
            {
                let mut provenance = self.finite_bound_argument_provenance(&expression.right);
                let invalidated_source =
                    if self.finite_bound_expression_is_known_array(&expression.right) {
                        BTreeSet::new()
                    } else {
                        provenance.clone()
                    };
                self.invalidate_finite_bound_argument_provenance(invalidated_source.clone());
                provenance
                    .extend(self.finite_bound_assignment_default_provenance(&expression.left));
                provenance.retain(|id| !invalidated_source.contains(id));
                for name in names {
                    self.replace_finite_bound_capture_value_and_refresh(&name, captures.clone());
                    if self.escaped_finite_bound_capture_names.contains(&name) {
                        self.finite_bound_argument_arrays.remove(&name);
                    } else if let Some(entry) = Self::finite_bound_carrier_entry(&provenance) {
                        self.finite_bound_argument_arrays.insert(name, entry);
                    } else {
                        self.finite_bound_argument_arrays.remove(&name);
                    }
                }
            } else {
                if let Some(captures) = captures {
                    for name in &names {
                        self.merge_finite_bound_capture_value(name, captures.clone());
                    }
                }
                let provenance = names
                    .iter()
                    .filter_map(|name| self.finite_bound_argument_arrays.get(name))
                    .flat_map(|entry| entry.provenance.iter().copied())
                    .collect();
                self.invalidate_finite_bound_argument_provenance(provenance);
            }
        }
        let uncertain_identifier_provenance = match &expression.left {
            AssignmentTarget::AssignmentTargetIdentifier(identifier)
                if expression.operator != AssignmentOperator::Assign
                    || self.conditional_control_flow_depth > 0 =>
            {
                self.finite_bound_argument_arrays
                    .get(identifier.name.as_str())
                    .map(|entry| entry.provenance.clone())
            }
            _ => None,
        };
        if let Some(provenance) = uncertain_identifier_provenance {
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
        let mutated_provenance = match &expression.left {
            AssignmentTarget::StaticMemberExpression(member) => {
                self.finite_bound_argument_provenance(&member.object)
            }
            AssignmentTarget::ComputedMemberExpression(member) => {
                self.finite_bound_argument_provenance(&member.object)
            }
            _ => BTreeSet::new(),
        };
        if !mutated_provenance.is_empty() {
            self.invalidate_finite_bound_argument_provenance(mutated_provenance);
        }
        if expression.operator == AssignmentOperator::Assign
            && let Some(root) = assignment_target_member_object_name(&expression.left)
            && let Some(captures) =
                self.finite_bound_capture_names_from_expression(&expression.right)
        {
            let provenance = self.finite_bound_argument_provenance(&expression.right);
            self.invalidate_finite_bound_argument_provenance(provenance);
            self.record_escaped_finite_bound_captures(captures.clone());
            let aliases = self
                .finite_bound_capture_aliases
                .get(root)
                .cloned()
                .unwrap_or_else(|| BTreeSet::from([root.to_string()]));
            for alias in aliases {
                self.merge_finite_bound_capture_value(&alias, captures.clone());
            }
        }
        if expression.operator == AssignmentOperator::Assign
            && self.conditional_control_flow_depth == 0
            && let AssignmentTarget::AssignmentTargetIdentifier(identifier) = &expression.left
        {
            let name = identifier.name.to_string();
            if self.escaped_finite_bound_capture_names.contains(&name) {
                self.finite_bound_argument_arrays.remove(&name);
            } else if let Some(arguments) = self.finite_bound_argument_entry(&expression.right) {
                self.finite_bound_argument_arrays
                    .insert(name.clone(), arguments);
            } else {
                self.finite_bound_argument_arrays.remove(&name);
            }
            let (array_indexes, array_index_forwards) =
                self.array_summary_from_expression(&expression.right);
            if self.expression_returns_wrapper(&expression.right) {
                self.wrapper_values.insert(name.clone());
            }
            let forwards = self.forwards_from_expression(&expression.right);
            if !forwards.is_empty() {
                self.forward_values.insert(name.clone(), forwards);
            }
            if array_indexes.is_empty() {
                self.array_index_values.remove(&name);
            } else {
                self.array_index_values.insert(name.clone(), array_indexes);
            }
            if array_index_forwards.is_empty() {
                self.array_index_forward_values.remove(&name);
            } else {
                self.array_index_forward_values
                    .insert(name, array_index_forwards);
            }
        } else if expression.operator == AssignmentOperator::Assign
            && let Some((root, path)) = assignment_target_static_member_path(&expression.left)
        {
            let root = root.to_string();
            let path = path.join(".");
            let prefix = format!("{path}.");
            self.structured_values.insert(root.clone());
            self.wrapper_member_values
                .retain(|(candidate_root, candidate)| {
                    candidate_root != &root
                        || (candidate != &path && !candidate.starts_with(&prefix))
                });
            self.forward_member_values
                .retain(|(candidate_root, candidate), _| {
                    candidate_root != &root
                        || (candidate != &path && !candidate.starts_with(&prefix))
                });
            if matches!(
                expression.right.get_inner_expression(),
                Expression::ObjectExpression(_)
            ) {
                self.record_structured_value(&root, &expression.right, &path);
            } else {
                if self.expression_returns_wrapper(&expression.right) {
                    self.wrapper_member_values
                        .insert((root.clone(), path.clone()));
                }
                let forwards = self.forwards_from_expression(&expression.right);
                if !forwards.is_empty() {
                    self.forward_member_values.insert((root, path), forwards);
                }
            }
        } else if expression.operator == AssignmentOperator::Assign
            && let Some((root, prefix)) = assignment_target_unknown_container_path(&expression.left)
        {
            let root = root.to_string();
            let forwards = self.forwards_from_expression(&expression.right);
            let wrapper = self.expression_returns_wrapper(&expression.right);
            let properties = match &expression.left {
                AssignmentTarget::ComputedMemberExpression(member) => {
                    match member.expression.get_inner_expression() {
                        Expression::StringLiteral(literal) => Some(vec![literal.value.to_string()]),
                        _ => None,
                    }
                }
                _ => None,
            };
            if let Some(properties) = properties {
                for property in properties {
                    let mut path = prefix.clone();
                    path.push(property);
                    let path = path.join(".");
                    let path_prefix = format!("{path}.");
                    self.wrapper_member_values
                        .retain(|(candidate_root, candidate)| {
                            candidate_root != &root
                                || (candidate != &path && !candidate.starts_with(&path_prefix))
                        });
                    self.forward_member_values
                        .retain(|(candidate_root, candidate), _| {
                            candidate_root != &root
                                || (candidate != &path && !candidate.starts_with(&path_prefix))
                        });
                    if wrapper {
                        self.wrapper_member_values
                            .insert((root.clone(), path.clone()));
                    }
                    if !forwards.is_empty() {
                        self.forward_member_values
                            .insert((root.clone(), path), forwards.clone());
                    }
                }
            } else if wrapper || !forwards.is_empty() {
                self.structured_unknown_values.insert(root);
            }
        }
    }

    fn visit_unary_expression(&mut self, expression: &UnaryExpression<'a>) {
        walk::walk_unary_expression(self, expression);
        match expression.operator {
            UnaryOperator::UnaryPlus | UnaryOperator::UnaryNegation | UnaryOperator::BitwiseNot => {
                let provenance = self.finite_bound_argument_provenance(&expression.argument);
                self.invalidate_finite_bound_argument_provenance(provenance);
            }
            UnaryOperator::Delete => {
                if let Some(member) = expression.argument.get_member_expr() {
                    let provenance = self.finite_bound_argument_provenance(member.object());
                    self.invalidate_finite_bound_argument_provenance(provenance);
                }
            }
            UnaryOperator::LogicalNot | UnaryOperator::Typeof | UnaryOperator::Void => {}
        }
    }

    fn visit_binary_expression(&mut self, expression: &BinaryExpression<'a>) {
        walk::walk_binary_expression(self, expression);
        if !matches!(
            expression.operator,
            BinaryOperator::StrictEquality | BinaryOperator::StrictInequality
        ) {
            let mut provenance = self.finite_bound_argument_provenance(&expression.left);
            provenance.extend(self.finite_bound_argument_provenance(&expression.right));
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
    }

    fn visit_template_literal(&mut self, template: &TemplateLiteral<'a>) {
        walk::walk_template_literal(self, template);
        let provenance = template
            .expressions
            .iter()
            .flat_map(|expression| self.finite_bound_argument_provenance(expression))
            .collect();
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_property_key(&mut self, key: &PropertyKey<'a>) {
        walk::walk_property_key(self, key);
        if let Some(expression) = key.as_expression() {
            let provenance = self.finite_bound_argument_provenance(expression);
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
    }

    fn visit_member_expression(&mut self, expression: &MemberExpression<'a>) {
        walk::walk_member_expression(self, expression);
        if let MemberExpression::ComputedMemberExpression(member) = expression {
            let provenance = self.finite_bound_argument_provenance(&member.expression);
            self.invalidate_finite_bound_argument_provenance(provenance);
        }
        let span = expression.span();
        if self
            .suppressed_member_read_spans
            .contains(&(span.start, span.end))
            || self.finite_bound_expression_is_known_array(expression.object())
        {
            return;
        }
        let provenance = self.finite_bound_argument_provenance(expression.object());
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_update_expression(&mut self, expression: &UpdateExpression<'a>) {
        walk::walk_update_expression(self, expression);
        let provenance = match &expression.argument {
            SimpleAssignmentTarget::AssignmentTargetIdentifier(identifier) => {
                self.finite_bound_identifier_provenance(identifier.name.as_str())
            }
            SimpleAssignmentTarget::StaticMemberExpression(member) => {
                self.finite_bound_argument_provenance(&member.object)
            }
            SimpleAssignmentTarget::ComputedMemberExpression(member) => {
                let mut provenance = self.finite_bound_argument_provenance(&member.object);
                provenance.extend(self.finite_bound_argument_provenance(&member.expression));
                provenance
            }
            target => target
                .get_expression()
                .map(|expression| self.finite_bound_argument_provenance(expression))
                .unwrap_or_default(),
        };
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_decorator(&mut self, decorator: &Decorator<'a>) {
        walk::walk_decorator(self, decorator);
        let captures = self
            .finite_bound_capture_names_from_expression(&decorator.expression)
            .unwrap_or_default();
        self.record_escaped_finite_bound_captures(captures);
        let provenance = self.finite_bound_argument_provenance(&decorator.expression);
        self.invalidate_finite_bound_argument_provenance(provenance);
    }

    fn visit_class(&mut self, class: &Class<'a>) {
        if class.r#type == ClassType::ClassDeclaration
            && let Some(identifier) = &class.id
        {
            self.set_finite_bound_capture_declaration(
                identifier.name.as_str(),
                Some(Self::finite_bound_class_capture_names(class)),
            );
        }
        walk::walk_class(self, class);
    }

    fn visit_function(&mut self, function: &Function<'a>, _flags: ScopeFlags) {
        if function.r#type == FunctionType::FunctionDeclaration
            && let Some(identifier) = &function.id
        {
            self.set_finite_bound_capture_declaration(
                identifier.name.as_str(),
                Some(Self::finite_bound_function_capture_names(function)),
            );
        }
        for parameter in &function.params.items {
            for decorator in &parameter.decorators {
                self.visit_decorator(decorator);
            }
        }
        if let Some(rest) = &function.params.rest {
            for decorator in &rest.decorators {
                self.visit_decorator(decorator);
            }
        }
    }

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

impl<'a> Visit<'a> for MessageKeyHelperCollector {
    fn visit_call_expression(&mut self, call: &CallExpression<'a>) {
        let Some(callee) = call
            .callee
            .get_inner_expression()
            .get_identifier_reference()
            .map(|identifier| identifier.name.as_str())
        else {
            walk::walk_call_expression(self, call);
            return;
        };
        if callee == "getMessage" {
            if let Some(Argument::Identifier(identifier)) = call.arguments.get(1) {
                if let Some(index) = self.param_names.get(identifier.name.as_str()) {
                    self.param_indexes.insert(*index);
                }
            }
        }
        walk::walk_call_expression(self, call);
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

impl HelperBodyCollector {
    fn record_dynamic_jsx_param_refs(&mut self, expression: &Expression<'_>) {
        for name in forwarded_identifier_names(expression) {
            if let Some(param_index) = self.param_names.get(&name) {
                self.jsx_dynamic_params.insert(*param_index);
            }
        }
    }

    fn record_binding_before_change(&mut self, name: &str) {
        if self
            .binding_scopes
            .last()
            .is_none_or(|scope| scope.bindings.contains_key(name))
        {
            return;
        }
        let values = HelperBindingValues {
            param_index: self.param_names.remove(name),
            param_path: self.param_paths.remove(name),
            helper: self.helpers.remove(name),
            finite_constant: self.finite_constants.remove(name),
            finite_iterable: self.finite_iterables.remove(name),
            finite_object_map: self.finite_object_maps.remove(name),
            finite_record_constant: self.finite_record_constants.remove(name),
            finite_record_iterable: self.finite_record_iterables.remove(name),
            finite_record_map: self.finite_record_maps.remove(name),
            enum_member_domain: self.enum_member_domains.remove(name),
            param_argument_array: self.param_argument_arrays.remove(name),
        };
        if let Some(scope) = self.binding_scopes.last_mut() {
            scope.bindings.insert(name.to_string(), values);
        }
    }

    fn record_enum_domain_before_change(&mut self, name: &str) {
        let Some(scope) = self.binding_scopes.last() else {
            return;
        };
        if scope.bindings.contains_key(name) || scope.enum_domains.contains_key(name) {
            return;
        }
        let previous = self.enum_member_domains.remove(name);
        if let Some(scope) = self.binding_scopes.last_mut() {
            scope.enum_domains.insert(name.to_string(), previous);
        }
    }

    fn restore_scope(&mut self, scope: HelperScopeFrame) {
        fn restore<T>(map: &mut BTreeMap<String, T>, name: &str, value: Option<T>) {
            match value {
                Some(value) => {
                    map.insert(name.to_string(), value);
                }
                None => {
                    map.remove(name);
                }
            }
        }

        for (name, values) in scope.bindings {
            restore(&mut self.param_names, &name, values.param_index);
            restore(&mut self.param_paths, &name, values.param_path);
            restore(&mut self.helpers, &name, values.helper);
            restore(&mut self.finite_constants, &name, values.finite_constant);
            restore(&mut self.finite_iterables, &name, values.finite_iterable);
            restore(
                &mut self.finite_object_maps,
                &name,
                values.finite_object_map,
            );
            restore(
                &mut self.finite_record_constants,
                &name,
                values.finite_record_constant,
            );
            restore(
                &mut self.finite_record_iterables,
                &name,
                values.finite_record_iterable,
            );
            restore(
                &mut self.finite_record_maps,
                &name,
                values.finite_record_map,
            );
            restore(
                &mut self.enum_member_domains,
                &name,
                values.enum_member_domain,
            );
            restore(
                &mut self.param_argument_arrays,
                &name,
                values.param_argument_array,
            );
        }
        for (name, values) in scope.enum_domains {
            restore(&mut self.enum_member_domains, &name, values);
        }
    }

    fn mask_outer_binding_name(&mut self, name: &str) {
        self.record_binding_before_change(name);
        self.helpers.remove(name);
        self.finite_constants.remove(name);
        self.finite_iterables.remove(name);
        self.finite_object_maps.remove(name);
        self.finite_record_constants.remove(name);
        self.finite_record_iterables.remove(name);
        self.finite_record_maps.remove(name);
        self.enum_member_domains.remove(name);
        self.param_argument_arrays.remove(name);
    }

    fn mask_binding_name(&mut self, name: &str) {
        self.mask_outer_binding_name(name);
        self.param_names.remove(name);
        self.param_paths.remove(name);
    }

    fn mask_binding_pattern(&mut self, pattern: &BindingPattern<'_>) {
        for identifier in pattern.get_binding_identifiers() {
            let name = identifier.name.as_str();
            if !self.injected_bindings.remove(name) {
                self.mask_binding_name(name);
            }
        }
    }

    fn callee_param_index(&self, expression: &Expression<'_>) -> Option<usize> {
        if let Some(identifier) = expression.get_identifier_reference() {
            return self.param_names.get(identifier.name.as_str()).copied();
        }

        let member = expression.get_member_expr()?;
        let method = member.static_property_name()?;
        if !TRANSLATOR_METHODS.contains(&method) {
            return None;
        }
        let object = member.object().get_identifier_reference()?;
        self.param_names.get(object.name.as_str()).copied()
    }

    fn callee_param_name<'b>(&self, expression: &'b Expression<'b>) -> Option<&'b str> {
        if let Some(identifier) = expression.get_identifier_reference() {
            return Some(identifier.name.as_str());
        }
        expression
            .get_member_expr()?
            .object()
            .get_identifier_reference()
            .map(|identifier| identifier.name.as_str())
    }

    fn helper_summary_for_callee(&self, expression: &Expression<'_>) -> Option<HelperSummary> {
        let callee = expression
            .get_inner_expression()
            .get_identifier_reference()
            .map(|identifier| identifier.name.as_str())?;
        self.helpers.get(callee).cloned()
    }

    fn param_indexes_from_argument(&self, argument: &Argument<'_>) -> ParamIndexes {
        argument
            .as_expression()
            .map(|expression| self.param_indexes_from_expression(expression))
            .unwrap_or_default()
    }

    fn param_indexes_from_expression(&self, expression: &Expression<'_>) -> ParamIndexes {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .param_names
                .get(identifier.name.as_str())
                .copied()
                .into_iter()
                .collect(),
            Expression::ConditionalExpression(conditional) => {
                let mut indexes = self.param_indexes_from_expression(&conditional.consequent);
                indexes.extend(self.param_indexes_from_expression(&conditional.alternate));
                indexes
            }
            _ => BTreeSet::new(),
        }
    }

    fn param_argument_array_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<ParamArgumentArray> {
        match expression.get_inner_expression() {
            Expression::ArrayExpression(array) => Some(self.param_argument_array_from_array(array)),
            Expression::Identifier(identifier) => self
                .param_argument_arrays
                .get(identifier.name.as_str())
                .cloned(),
            Expression::ConditionalExpression(conditional) => {
                let consequent = self.param_argument_array_from_expression(&conditional.consequent);
                let alternate = self.param_argument_array_from_expression(&conditional.alternate);
                match (consequent, alternate) {
                    (Some(consequent), Some(alternate)) => {
                        Some(merge_param_argument_arrays(consequent, alternate))
                    }
                    (Some(mut array), None) | (None, Some(mut array)) => {
                        array.safe_layout = false;
                        Some(array)
                    }
                    (None, None) => None,
                }
            }
            Expression::LogicalExpression(logical) => {
                let left = self.param_argument_array_from_expression(&logical.left);
                let right = self.param_argument_array_from_expression(&logical.right);
                match logical.operator {
                    LogicalOperator::And => match (left, right) {
                        (Some(left), right) if left.safe_layout => right,
                        (_, Some(mut right)) => {
                            right.safe_layout = false;
                            Some(right)
                        }
                        (_, None) => None,
                    },
                    LogicalOperator::Or | LogicalOperator::Coalesce => match (left, right) {
                        (Some(left), _) if left.safe_layout => Some(left),
                        (Some(left), Some(right)) => Some(merge_param_argument_arrays(left, right)),
                        (Some(mut left), None) => {
                            left.safe_layout = false;
                            Some(left)
                        }
                        (None, Some(mut right)) => {
                            right.safe_layout = false;
                            Some(right)
                        }
                        (None, None) => None,
                    },
                }
            }
            _ => None,
        }
    }

    fn param_argument_array_from_array(
        &self,
        array: &oxc_ast::ast::ArrayExpression<'_>,
    ) -> ParamArgumentArray {
        let mut bindings = Vec::new();
        let mut safe_layout = true;
        for element in &array.elements {
            match element {
                ArrayExpressionElement::SpreadElement(spread) => {
                    if let Some(spread_array) =
                        self.param_argument_array_from_expression(&spread.argument)
                    {
                        bindings.extend(spread_array.bindings);
                        safe_layout &= spread_array.safe_layout;
                    } else {
                        safe_layout = false;
                    }
                }
                _ => bindings.push(
                    element
                        .as_expression()
                        .map(|expression| self.param_indexes_from_expression(expression))
                        .unwrap_or_default(),
                ),
            }
        }
        ParamArgumentArray {
            bindings,
            safe_layout,
        }
    }

    fn param_argument_array_from_arguments(
        &self,
        arguments: &[Argument<'_>],
        offset: usize,
    ) -> ParamArgumentArray {
        let mut bindings = Vec::new();
        let mut safe_layout = true;
        for argument in arguments.iter().skip(offset) {
            match argument {
                Argument::SpreadElement(spread) => {
                    if let Some(spread_array) =
                        self.param_argument_array_from_expression(&spread.argument)
                    {
                        bindings.extend(spread_array.bindings);
                        safe_layout &= spread_array.safe_layout;
                    } else {
                        safe_layout = false;
                    }
                }
                _ => bindings.push(self.param_indexes_from_argument(argument)),
            }
        }
        ParamArgumentArray {
            bindings,
            safe_layout,
        }
    }

    fn invalidate_escaped_param_argument_arrays(&mut self, call: &CallExpression<'_>) {
        let safe_apply_index = call.callee.get_member_expr().and_then(|member| {
            (member.static_property_name().as_deref() == Some("apply")
                && self.helper_summary_for_callee(member.object()).is_some())
            .then_some(1)
        });
        for (index, argument) in call.arguments.iter().enumerate() {
            if safe_apply_index == Some(index) {
                continue;
            }
            let Some(expression) = argument.as_expression() else {
                continue;
            };
            for name in referenced_identifier_names(expression) {
                if let Some(array) = self.param_argument_arrays.get_mut(&name) {
                    array.safe_layout = false;
                }
            }
        }
    }

    fn record_helper_usage_for_params(&mut self, indexes: &ParamIndexes, usage: &HelperParamUsage) {
        for param_index in indexes {
            self.usages.push(HelperParamUsage {
                param_index: *param_index,
                param_path: usage.param_path.clone(),
                keys: usage.keys.clone(),
                query: usage.query.clone(),
                translator_like: usage.translator_like,
                direct_translator: usage.direct_translator,
            });
        }
    }

    fn record_unresolved_helper_argument_usages(&mut self, call: &CallExpression<'_>) {
        if let Some(callee) = call
            .callee
            .get_inner_expression()
            .get_identifier_reference()
            .map(|identifier| identifier.name.to_string())
        {
            let argument_array = self.param_argument_array_from_arguments(&call.arguments, 0);
            let fallback_params = if argument_array.safe_layout {
                argument_array
                    .bindings
                    .iter()
                    .flat_map(|indexes| indexes.iter().copied())
                    .collect()
            } else {
                self.param_names.values().copied().collect()
            };
            self.forwards.push(HelperForward {
                callee,
                argument_array,
                fallback_params,
            });
            return;
        }

        let mut indexes = BTreeSet::new();
        for argument in &call.arguments {
            match argument {
                Argument::SpreadElement(spread) => {
                    if let Some(array) = self.param_argument_array_from_expression(&spread.argument)
                    {
                        if array.safe_layout {
                            for element in array.bindings {
                                indexes.extend(element);
                            }
                        } else {
                            indexes.extend(self.param_names.values().copied());
                        }
                    } else {
                        indexes.extend(self.param_names.values().copied());
                    }
                }
                _ => {
                    let Some(expression) = argument.as_expression() else {
                        continue;
                    };
                    for name in forwarded_identifier_names(expression) {
                        if let Some(index) = self.param_names.get(&name) {
                            indexes.insert(*index);
                        }
                    }
                }
            }
        }
        for param_index in indexes {
            self.usages.push(HelperParamUsage {
                param_index,
                param_path: Vec::new(),
                keys: None,
                query: None,
                translator_like: true,
                direct_translator: false,
            });
        }
    }

    fn apply_helper_summary_with_offset(
        &mut self,
        call: &CallExpression<'_>,
        summary: &HelperSummary,
        offset: usize,
    ) {
        let argument_array = self.param_argument_array_from_arguments(&call.arguments, offset);
        self.apply_helper_summary_from_param_array(&argument_array, summary);
    }

    fn apply_helper_summary_from_param_array(
        &mut self,
        argument_array: &ParamArgumentArray,
        summary: &HelperSummary,
    ) {
        if !argument_array.safe_layout {
            let indexes = self.param_names.values().copied().collect();
            for usage in &summary.param_usages {
                self.record_helper_usage_for_params(&indexes, usage);
            }
            self.forwards
                .extend(summary.forwards.iter().map(|forward| HelperForward {
                    callee: forward.callee.clone(),
                    argument_array: ParamArgumentArray {
                        bindings: Vec::new(),
                        safe_layout: false,
                    },
                    fallback_params: indexes.clone(),
                }));
            return;
        }
        for usage in &summary.param_usages {
            let Some(indexes) = argument_array.bindings.get(usage.param_index) else {
                continue;
            };
            self.record_helper_usage_for_params(indexes, usage);
        }
        self.forwards.extend(summary.forwards.iter().map(|forward| {
            remap_helper_forward(forward, true, |index| {
                argument_array
                    .bindings
                    .get(index)
                    .cloned()
                    .unwrap_or_default()
            })
        }));
    }

    fn visit_callback_arguments(&mut self, call: &CallExpression<'_>) {
        for argument in &call.arguments {
            match argument {
                Argument::ArrowFunctionExpression(arrow) => {
                    self.binding_scopes.push(HelperScopeFrame {
                        bindings: BTreeMap::new(),
                        enum_domains: BTreeMap::new(),
                    });
                    for name in function_var_bindings(&arrow.body) {
                        self.mask_binding_name(&name);
                    }
                    for parameter in &arrow.params.items {
                        self.mask_binding_pattern(&parameter.pattern);
                    }
                    for statement in &arrow.body.statements {
                        self.visit_statement(statement);
                    }
                    if let Some(scope) = self.binding_scopes.pop() {
                        self.restore_scope(scope);
                    }
                }
                Argument::FunctionExpression(function) => {
                    self.binding_scopes.push(HelperScopeFrame {
                        bindings: BTreeMap::new(),
                        enum_domains: BTreeMap::new(),
                    });
                    if let Some(id) = &function.id {
                        self.mask_binding_name(id.name.as_str());
                    }
                    if let Some(body) = &function.body {
                        for name in function_var_bindings(body) {
                            self.mask_binding_name(&name);
                        }
                    }
                    for parameter in &function.params.items {
                        self.mask_binding_pattern(&parameter.pattern);
                    }
                    if let Some(body) = &function.body {
                        for statement in &body.statements {
                            self.visit_statement(statement);
                        }
                    }
                    if let Some(scope) = self.binding_scopes.pop() {
                        self.restore_scope(scope);
                    }
                }
                _ => {}
            }
        }
    }

    fn finite_iterable_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<FiniteStrings> {
        finite_iterable_from_expression(
            expression,
            &self.finite_constants,
            &self.finite_iterables,
            &self.finite_object_maps,
            &self.enum_member_domains,
        )
    }

    fn finite_record_iterable_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<FiniteRecords> {
        match expression.get_inner_expression() {
            Expression::StaticMemberExpression(member) => {
                let object = member.object.get_identifier_reference()?;
                let records = self.finite_record_constants.get(object.name.as_str())?;
                finite_record_property_iterable(records, member.property.name.as_str())
            }
            _ => finite_record_iterable_from_expression(
                expression,
                &self.finite_constants,
                &self.finite_object_maps,
                &self.enum_member_domains,
                &self.finite_record_iterables,
                &self.finite_record_maps,
            ),
        }
    }

    fn finite_record_from_expression(&self, expression: &Expression<'_>) -> Option<FiniteRecords> {
        match expression.get_inner_expression() {
            Expression::LogicalExpression(logical)
                if logical.operator == LogicalOperator::Coalesce =>
            {
                let left = self.finite_record_from_expression(&logical.left);
                let right = self.finite_record_from_expression(&logical.right);
                return match (left, right) {
                    (Some(left), Some(right)) => merge_finite_records(left, right),
                    (Some(values), None) | (None, Some(values)) => Some(values),
                    (None, None) => None,
                };
            }
            Expression::ConditionalExpression(conditional) => {
                let consequent = self.finite_record_from_expression(&conditional.consequent);
                let alternate = self.finite_record_from_expression(&conditional.alternate);
                return match (consequent, alternate) {
                    (Some(consequent), Some(alternate)) => {
                        merge_finite_records(consequent, alternate)
                    }
                    (Some(values), None) | (None, Some(values)) => Some(values),
                    (None, None) => None,
                };
            }
            _ => {}
        }
        finite_record_from_expression(
            expression,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
            &self.finite_record_iterables,
            &self.finite_record_maps,
        )
        .or_else(|| {
            if let Expression::Identifier(identifier) = expression.get_inner_expression() {
                self.finite_record_constants
                    .get(identifier.name.as_str())
                    .cloned()
            } else {
                None
            }
        })
    }

    fn finite_strings_from_argument(&self, argument: &Argument<'_>) -> Option<FiniteStrings> {
        match argument {
            Argument::StaticMemberExpression(member) => {
                let object = member.object.get_identifier_reference()?;
                let records = self.finite_record_constants.get(object.name.as_str())?;
                finite_record_property_strings(records, member.property.name.as_str())
            }
            _ => finite_strings_from_argument(
                argument,
                &self.finite_constants,
                &self.finite_object_maps,
                &self.enum_member_domains,
            ),
        }
    }

    fn with_finite_constant(
        &mut self,
        name: &str,
        values: FiniteStrings,
        visit: impl FnOnce(&mut Self),
    ) {
        let previous = self.finite_constants.insert(name.to_string(), values);
        self.injected_bindings.insert(name.to_string());
        visit(self);
        self.injected_bindings.remove(name);
        match previous {
            Some(values) => {
                self.finite_constants.insert(name.to_string(), values);
            }
            None => {
                self.finite_constants.remove(name);
            }
        }
    }

    fn with_finite_record_constant(
        &mut self,
        name: &str,
        values: FiniteRecords,
        visit: impl FnOnce(&mut Self),
    ) {
        let previous = self
            .finite_record_constants
            .insert(name.to_string(), values);
        self.injected_bindings.insert(name.to_string());
        visit(self);
        self.injected_bindings.remove(name);
        match previous {
            Some(values) => {
                self.finite_record_constants
                    .insert(name.to_string(), values);
            }
            None => {
                self.finite_record_constants.remove(name);
            }
        }
    }

    fn visit_finite_iteration_callback(
        &mut self,
        callback: &Argument<'_>,
        values: FiniteStrings,
    ) -> bool {
        match callback {
            Argument::ArrowFunctionExpression(arrow) => {
                let Some(param) = arrow
                    .params
                    .items
                    .first()
                    .and_then(|param| binding_identifier_name(&param.pattern))
                else {
                    return false;
                };
                self.with_finite_constant(param, values, |collector| {
                    collector.pending_var_bindings = Some(function_var_bindings(&arrow.body));
                    walk::walk_arrow_function_expression(collector, arrow);
                });
                true
            }
            Argument::FunctionExpression(function) => {
                let Some(param) = function
                    .params
                    .items
                    .first()
                    .and_then(|param| binding_identifier_name(&param.pattern))
                else {
                    return false;
                };
                self.with_finite_constant(param, values, |collector| {
                    collector.pending_var_bindings = function
                        .body
                        .as_ref()
                        .map(|body| function_var_bindings(body));
                    walk::walk_function(collector, function, ScopeFlags::Function);
                });
                true
            }
            _ => false,
        }
    }

    fn visit_finite_iteration_call(&mut self, call: &CallExpression<'_>) -> bool {
        let Some(member) = call.callee.get_member_expr() else {
            return false;
        };
        let Some(method) = member.static_property_name() else {
            return false;
        };
        if !matches!(method.as_ref(), "map" | "flatMap" | "forEach") {
            return false;
        }
        let Some(values) = self.finite_iterable_from_expression(member.object()) else {
            return false;
        };
        let Some(callback) = call.arguments.first() else {
            return false;
        };
        self.visit_finite_iteration_callback(callback, values)
    }

    fn visit_finite_record_iteration_callback(
        &mut self,
        callback: &Argument<'_>,
        values: FiniteRecords,
    ) -> bool {
        match callback {
            Argument::ArrowFunctionExpression(arrow) => {
                let Some(param) = arrow
                    .params
                    .items
                    .first()
                    .and_then(|param| binding_identifier_name(&param.pattern))
                else {
                    return false;
                };
                self.with_finite_record_constant(param, values, |collector| {
                    collector.pending_var_bindings = Some(function_var_bindings(&arrow.body));
                    walk::walk_arrow_function_expression(collector, arrow);
                });
                true
            }
            Argument::FunctionExpression(function) => {
                let Some(param) = function
                    .params
                    .items
                    .first()
                    .and_then(|param| binding_identifier_name(&param.pattern))
                else {
                    return false;
                };
                self.with_finite_record_constant(param, values, |collector| {
                    collector.pending_var_bindings = function
                        .body
                        .as_ref()
                        .map(|body| function_var_bindings(body));
                    walk::walk_function(collector, function, ScopeFlags::Function);
                });
                true
            }
            _ => false,
        }
    }

    fn visit_finite_record_iteration_call(&mut self, call: &CallExpression<'_>) -> bool {
        let Some(member) = call.callee.get_member_expr() else {
            return false;
        };
        let Some(method) = member.static_property_name() else {
            return false;
        };
        if !matches!(method.as_ref(), "map" | "flatMap" | "forEach") {
            return false;
        }
        let Some(values) = self.finite_record_iterable_from_expression(member.object()) else {
            return false;
        };
        let Some(callback) = call.arguments.first() else {
            return false;
        };
        self.visit_finite_record_iteration_callback(callback, values)
    }

    fn for_of_binding_name<'a>(&self, statement: &'a ForOfStatement<'a>) -> Option<&'a str> {
        match &statement.left {
            ForStatementLeft::VariableDeclaration(declaration) => declaration
                .declarations
                .first()
                .and_then(|declarator| binding_identifier_name(&declarator.id)),
            ForStatementLeft::AssignmentTargetIdentifier(identifier) => {
                Some(identifier.name.as_str())
            }
            _ => None,
        }
    }
}

impl<'a> Visit<'a> for HelperBodyCollector {
    fn enter_scope(&mut self, _flags: ScopeFlags, _scope_id: &Cell<Option<ScopeId>>) {
        self.binding_scopes.push(HelperScopeFrame {
            bindings: BTreeMap::new(),
            enum_domains: BTreeMap::new(),
        });
        if let Some(bindings) = self.pending_var_bindings.take() {
            for name in bindings {
                if !self.injected_bindings.contains(&name) {
                    self.mask_binding_name(&name);
                }
            }
        }
    }

    fn leave_scope(&mut self) {
        if let Some(scope) = self.binding_scopes.pop() {
            self.restore_scope(scope);
        }
    }

    fn visit_formal_parameter(&mut self, parameter: &oxc_ast::ast::FormalParameter<'a>) {
        self.mask_binding_pattern(&parameter.pattern);
        walk::walk_formal_parameter(self, parameter);
    }

    fn visit_catch_parameter(&mut self, parameter: &CatchParameter<'a>) {
        self.mask_binding_pattern(&parameter.pattern);
        walk::walk_catch_parameter(self, parameter);
    }

    fn visit_jsx_element(&mut self, element: &JSXElement<'a>) {
        for child in &element.children {
            match child {
                JSXChild::ExpressionContainer(container)
                    if !matches!(&container.expression, JSXExpression::EmptyExpression(_)) =>
                {
                    self.record_dynamic_jsx_param_refs(container.expression.to_expression());
                }
                JSXChild::Spread(spread) => {
                    self.record_dynamic_jsx_param_refs(&spread.expression);
                }
                _ => {}
            }
        }
        walk::walk_jsx_element(self, element);
    }

    fn visit_jsx_opening_element(&mut self, opening: &JSXOpeningElement<'a>) {
        let component = match &opening.name {
            JSXElementName::Identifier(identifier) => Some((None, identifier.name.as_str())),
            JSXElementName::IdentifierReference(identifier) => {
                Some((None, identifier.name.as_str()))
            }
            JSXElementName::MemberExpression(member) => match &member.object {
                JSXMemberExpressionObject::IdentifierReference(namespace) => {
                    Some((Some(namespace.name.as_str()), member.property.name.as_str()))
                }
                _ => None,
            },
            _ => None,
        };
        for attribute in &opening.attributes {
            let JSXAttributeItem::Attribute(attribute) = attribute else {
                if let JSXAttributeItem::SpreadAttribute(spread) = attribute {
                    self.record_dynamic_jsx_param_refs(&spread.argument);
                }
                continue;
            };
            let JSXAttributeName::Identifier(target_prop) = &attribute.name else {
                continue;
            };
            let Some(JSXAttributeValue::ExpressionContainer(container)) = &attribute.value else {
                continue;
            };
            let JSXExpression::Identifier(identifier) = &container.expression else {
                if !matches!(&container.expression, JSXExpression::EmptyExpression(_)) {
                    self.record_dynamic_jsx_param_refs(container.expression.to_expression());
                }
                continue;
            };
            let Some(param_index) = self.param_names.get(identifier.name.as_str()).copied() else {
                continue;
            };
            if let Some((component_namespace, component_name)) = component {
                self.jsx_forwards.push(HelperJsxForward {
                    param_index,
                    component_namespace: component_namespace.map(str::to_string),
                    component_name: component_name.to_string(),
                    target_prop: target_prop.name.to_string(),
                });
            } else {
                self.jsx_dynamic_params.insert(param_index);
            }
        }
        walk::walk_jsx_opening_element(self, opening);
    }

    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        let aliased_param = declarator
            .init
            .as_ref()
            .and_then(Expression::get_identifier_reference)
            .and_then(|source| self.param_names.get(source.name.as_str()).copied());
        let aliased_param_path = declarator
            .init
            .as_ref()
            .and_then(Expression::get_identifier_reference)
            .and_then(|source| self.param_paths.get(source.name.as_str()).cloned());
        let derived_helper = declarator.init.as_ref().and_then(|init| {
            helper_summary_from_expression_with_context(
                init,
                &self.helpers,
                &self.finite_constants,
                &self.finite_iterables,
                &self.finite_object_maps,
                &self.finite_record_constants,
                &self.finite_record_iterables,
                &self.finite_record_maps,
                &self.enum_member_domains,
                self.source_context.as_ref(),
            )
        });
        let param_argument_array = (declarator.kind == VariableDeclarationKind::Const)
            .then(|| declarator.init.as_ref())
            .flatten()
            .and_then(|init| self.param_argument_array_from_expression(init));
        let param_argument_array_alias = declarator
            .init
            .as_ref()
            .and_then(|init| init.get_inner_expression().get_identifier_reference())
            .map(|identifier| identifier.name.to_string());
        let param_argument_array = param_argument_array.map(|mut array| {
            if let Some(source) = &param_argument_array_alias {
                array.safe_layout = false;
                if let Some(source_array) = self.param_argument_arrays.get_mut(source) {
                    source_array.safe_layout = false;
                }
            }
            array
        });
        self.mask_binding_pattern(&declarator.id);
        if let Some(param_index) = aliased_param {
            for identifier in declarator.id.get_binding_identifiers() {
                self.param_names
                    .insert(identifier.name.to_string(), param_index);
                if let Some(path) = &aliased_param_path {
                    self.param_paths
                        .insert(identifier.name.to_string(), path.clone());
                }
            }
        }
        if let (Some(name), Some(summary)) =
            (binding_identifier_name(&declarator.id), derived_helper)
        {
            self.helpers.insert(name.to_string(), summary);
        }
        if let (Some(name), Some(bindings)) = (
            binding_identifier_name(&declarator.id),
            param_argument_array,
        ) {
            self.param_argument_arrays
                .insert(name.to_string(), bindings);
        }
        if declarator.kind == VariableDeclarationKind::Const {
            if let Some(name) = binding_identifier_name(&declarator.id) {
                if let Some(init) = &declarator.init {
                    let mut domains = BTreeMap::new();
                    record_enum_member_domains_from_expression(init, &mut domains);
                    for (name, values) in domains {
                        self.record_enum_domain_before_change(&name);
                        self.enum_member_domains
                            .entry(name)
                            .or_default()
                            .extend(values);
                    }
                    if let Some(values) = finite_strings_from_expression(
                        init,
                        &self.finite_constants,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                    ) {
                        self.finite_constants.insert(name.to_string(), values);
                    }
                    if let Some(values) = self.finite_iterable_from_expression(init) {
                        self.finite_iterables.insert(name.to_string(), values);
                    }
                    if let Some(values) = finite_object_map_from_expression(
                        init,
                        &self.finite_constants,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                    ) {
                        self.finite_object_maps.insert(name.to_string(), values);
                    }
                    if let Some(values) = self.finite_record_iterable_from_expression(init) {
                        self.finite_record_iterables
                            .insert(name.to_string(), values);
                    }
                    if let Some(values) = self.finite_record_from_expression(init) {
                        self.finite_record_constants
                            .insert(name.to_string(), values);
                    }
                    if let Some(values) = finite_record_map_from_expression(
                        init,
                        &self.finite_constants,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                        &self.finite_record_iterables,
                        &self.finite_record_maps,
                    ) {
                        self.finite_record_maps.insert(name.to_string(), values);
                    }
                }
            }
        }
        walk::walk_variable_declarator(self, declarator);
    }

    fn visit_call_expression(&mut self, call: &CallExpression<'a>) {
        if let Some(member) = call.callee.get_member_expr() {
            if let Some(method) = member.static_property_name()
                && ARRAY_MUTATING_METHODS.contains(&method.as_ref())
            {
                if let Some(identifier) = member.object().get_identifier_reference() {
                    if let Some(array) =
                        self.param_argument_arrays.get_mut(identifier.name.as_str())
                    {
                        array.safe_layout = false;
                    }
                }
            }
        }

        self.invalidate_escaped_param_argument_arrays(call);

        if self.visit_finite_record_iteration_call(call) {
            if let Some(member) = call.callee.get_member_expr() {
                self.visit_expression(member.object());
            }
            return;
        }

        if self.visit_finite_iteration_call(call) {
            if let Some(member) = call.callee.get_member_expr() {
                self.visit_expression(member.object());
            }
            return;
        }

        let member_helper = call.callee.get_member_expr().and_then(|member| {
            let method = member.static_property_name()?;
            let summary = self.helper_summary_for_callee(member.object())?;
            Some((method.to_string(), summary))
        });
        let helper_usage_resolved = if let Some((method, summary)) = member_helper {
            match method.as_str() {
                "call" | "bind" => {
                    self.apply_helper_summary_with_offset(call, &summary, 1);
                    true
                }
                "apply" => {
                    let argument_array = call
                        .arguments
                        .get(1)
                        .and_then(Argument::as_expression)
                        .and_then(|expression| {
                            self.param_argument_array_from_expression(expression)
                        })
                        .unwrap_or(ParamArgumentArray {
                            bindings: Vec::new(),
                            safe_layout: false,
                        });
                    self.apply_helper_summary_from_param_array(&argument_array, &summary);
                    true
                }
                _ => false,
            }
        } else if let Some(summary) = self.helper_summary_for_callee(&call.callee) {
            self.apply_helper_summary_with_offset(call, &summary, 0);
            true
        } else {
            false
        };
        if !helper_usage_resolved {
            self.record_unresolved_helper_argument_usages(call);
        }

        if let Some(param_index) = self.callee_param_index(&call.callee) {
            let callee_name = self.callee_param_name(&call.callee);
            let param_path = callee_name
                .and_then(|name| self.param_paths.get(name))
                .cloned()
                .unwrap_or_default();
            let translator_like = callee_name.is_some_and(is_translator_like_name);
            let argument = call.arguments.first();
            let keys = argument.and_then(|argument| self.finite_strings_from_argument(argument));
            let query = if keys.is_none() {
                argument.and_then(|argument| {
                    self.source_context
                        .as_ref()
                        .map(|context| context.key_query(call.span.start, argument))
                })
            } else {
                None
            };
            self.usages.push(HelperParamUsage {
                param_index,
                direct_translator: translator_like,
                param_path,
                keys,
                query,
                translator_like,
            });
        }
        self.visit_callback_arguments(call);
        walk::walk_call_expression(self, call);
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}

    fn visit_assignment_expression(&mut self, expression: &AssignmentExpression<'a>) {
        if let Some(name) = assignment_target_member_object_name(&expression.left) {
            if let Some(array) = self.param_argument_arrays.get_mut(name) {
                array.safe_layout = false;
            }
        }
        walk::walk_assignment_expression(self, expression);
    }

    fn visit_for_of_statement(&mut self, statement: &ForOfStatement<'a>) {
        if let Some(values) = self.finite_record_iterable_from_expression(&statement.right) {
            if let Some(binding) = self.for_of_binding_name(statement).map(str::to_string) {
                self.with_finite_record_constant(&binding, values, |collector| {
                    collector.visit_statement(&statement.body);
                });
                return;
            }
        }

        let Some(values) = self.finite_iterable_from_expression(&statement.right) else {
            walk::walk_for_of_statement(self, statement);
            return;
        };
        let Some(binding) = self.for_of_binding_name(statement).map(str::to_string) else {
            walk::walk_for_of_statement(self, statement);
            return;
        };
        self.with_finite_constant(&binding, values, |collector| {
            collector.visit_statement(&statement.body);
        });
    }
}

struct ReturnValueCollector {
    finite_constants: BTreeMap<String, FiniteStrings>,
    finite_iterables: BTreeMap<String, FiniteStrings>,
    finite_object_maps: FiniteObjectMaps,
    enum_member_domains: TypeDomains,
    return_values: FiniteStrings,
    unknown_return: bool,
}

struct ReturnRecordCollector {
    finite_constants: BTreeMap<String, FiniteStrings>,
    finite_iterables: BTreeMap<String, FiniteStrings>,
    finite_object_maps: FiniteObjectMaps,
    finite_record_constants: FiniteRecordBindings,
    finite_record_iterables: FiniteRecordBindings,
    finite_record_maps: FiniteRecordMaps,
    enum_member_domains: TypeDomains,
    react_use_memo_identifiers: BTreeSet<String>,
    react_namespaces: BTreeSet<String>,
    return_records: FiniteRecords,
    unknown_return: bool,
}

impl ReturnRecordCollector {
    fn finite_record_iterable_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<FiniteRecords> {
        if let Expression::CallExpression(call) = expression.get_inner_expression() {
            let react_memo =
                call.callee
                    .get_identifier_reference()
                    .is_some_and(|identifier| {
                        self.react_use_memo_identifiers
                            .contains(identifier.name.as_str())
                    })
                    || call.callee.get_member_expr().is_some_and(|member| {
                        member.static_property_name() == Some("useMemo")
                            && member.object().get_identifier_reference().is_some_and(
                                |identifier| {
                                    self.react_namespaces.contains(identifier.name.as_str())
                                },
                            )
                    });
            if react_memo {
                return call.arguments.first().and_then(|callback| {
                    finite_records_from_callback_argument(
                        callback,
                        &self.finite_constants,
                        &self.finite_iterables,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                        &self.finite_record_iterables,
                        &self.finite_record_maps,
                    )
                });
            }
        }
        finite_record_iterable_from_expression(
            expression,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
            &self.finite_record_iterables,
            &self.finite_record_maps,
        )
    }

    fn finite_record_from_expression(&self, expression: &Expression<'_>) -> Option<FiniteRecords> {
        finite_record_from_expression(
            expression,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
            &self.finite_record_iterables,
            &self.finite_record_maps,
        )
        .or_else(|| {
            if let Expression::Identifier(identifier) = expression.get_inner_expression() {
                self.finite_record_constants
                    .get(identifier.name.as_str())
                    .cloned()
            } else {
                None
            }
        })
    }

    fn record_const_init(&mut self, name: &str, init: &Expression<'_>) {
        record_enum_member_domains_from_expression(init, &mut self.enum_member_domains);
        if let Some(values) = finite_strings_from_expression(
            init,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
        ) {
            self.finite_constants.insert(name.to_string(), values);
        }
        if let Some(values) = finite_iterable_from_expression(
            init,
            &self.finite_constants,
            &self.finite_iterables,
            &self.finite_object_maps,
            &self.enum_member_domains,
        ) {
            self.finite_iterables.insert(name.to_string(), values);
        }
        if let Some(values) = finite_object_map_from_expression(
            init,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
        ) {
            self.finite_object_maps.insert(name.to_string(), values);
        }
        if let Some(values) = self.finite_record_iterable_from_expression(init) {
            self.finite_record_iterables
                .insert(name.to_string(), values);
        }
        if let Some(values) = finite_record_map_from_expression(
            init,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
            &self.finite_record_iterables,
            &self.finite_record_maps,
        ) {
            self.finite_record_maps.insert(name.to_string(), values);
        }
    }
}

impl<'a> Visit<'a> for ReturnRecordCollector {
    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        for identifier in declarator.id.get_binding_identifiers() {
            self.react_use_memo_identifiers
                .remove(identifier.name.as_str());
            self.react_namespaces.remove(identifier.name.as_str());
        }
        if declarator.kind == VariableDeclarationKind::Const {
            if let Some(name) = binding_identifier_name(&declarator.id) {
                if let Some(init) = &declarator.init {
                    self.record_const_init(name, init);
                }
            }
        }
        walk::walk_variable_declarator(self, declarator);
    }

    fn visit_call_expression(&mut self, call: &CallExpression<'a>) {
        let Some(member) = call.callee.get_member_expr() else {
            walk::walk_call_expression(self, call);
            return;
        };
        if member
            .static_property_name()
            .is_some_and(|method| method == "push")
        {
            if let Some(object) = member.object().get_identifier_reference() {
                let mut appended = Vec::new();
                for argument in &call.arguments {
                    let Argument::ObjectExpression(object) = argument else {
                        continue;
                    };
                    if let Some(record) = finite_record_from_object(
                        object,
                        &self.finite_constants,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                        &self.finite_record_iterables,
                        &self.finite_record_maps,
                    ) {
                        appended.push(record);
                    }
                }
                if !appended.is_empty() {
                    self.finite_record_iterables
                        .entry(object.name.to_string())
                        .or_default()
                        .extend(appended);
                    return;
                }
            }
        }
        walk::walk_call_expression(self, call);
    }

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        let Some(argument) = &statement.argument else {
            self.unknown_return = true;
            return;
        };
        let Some(records) = self
            .finite_record_from_expression(argument)
            .or_else(|| self.finite_record_iterable_from_expression(argument))
        else {
            self.unknown_return = true;
            return;
        };
        if let Some(records) = merge_finite_records(self.return_records.clone(), records) {
            self.return_records = records;
        } else {
            self.unknown_return = true;
        }
    }

    fn visit_function(&mut self, function: &Function<'a>, _flags: ScopeFlags) {
        if let Some(identifier) = &function.id {
            self.react_use_memo_identifiers
                .remove(identifier.name.as_str());
            self.react_namespaces.remove(identifier.name.as_str());
        }
    }

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

impl ReturnValueCollector {
    fn finite_iterable_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<FiniteStrings> {
        finite_iterable_from_expression(
            expression,
            &self.finite_constants,
            &self.finite_iterables,
            &self.finite_object_maps,
            &self.enum_member_domains,
        )
    }
}

impl<'a> Visit<'a> for ReturnValueCollector {
    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        if declarator.kind == VariableDeclarationKind::Const {
            if let Some(name) = binding_identifier_name(&declarator.id) {
                if let Some(init) = &declarator.init {
                    record_enum_member_domains_from_expression(init, &mut self.enum_member_domains);
                    if let Some(values) = finite_strings_from_expression(
                        init,
                        &self.finite_constants,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                    ) {
                        self.finite_constants.insert(name.to_string(), values);
                    }
                    if let Some(values) = self.finite_iterable_from_expression(init) {
                        self.finite_iterables.insert(name.to_string(), values);
                    }
                    if let Some(values) = finite_object_map_from_expression(
                        init,
                        &self.finite_constants,
                        &self.finite_object_maps,
                        &self.enum_member_domains,
                    ) {
                        self.finite_object_maps.insert(name.to_string(), values);
                    }
                }
            }
        }
        walk::walk_variable_declarator(self, declarator);
    }

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        let Some(argument) = &statement.argument else {
            self.unknown_return = true;
            return;
        };
        if matches!(argument.get_inner_expression(), Expression::NullLiteral(_))
            || argument
                .get_inner_expression()
                .get_identifier_reference()
                .is_some_and(|identifier| identifier.name == "undefined")
        {
            return;
        }
        let Some(values) = finite_strings_from_expression(
            argument,
            &self.finite_constants,
            &self.finite_object_maps,
            &self.enum_member_domains,
        ) else {
            self.unknown_return = true;
            return;
        };
        self.return_values.extend(values);
        if self.return_values.len() > MAX_FINITE_STRINGS {
            self.unknown_return = true;
        }
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}
}

fn static_factory_namespace_arg(call: &CallExpression<'_>) -> NamespaceArg {
    let Some(argument) = call.arguments.first() else {
        return NamespaceArg::Unscoped;
    };
    match argument {
        Argument::StringLiteral(literal) => NamespaceArg::Scoped(literal.value.to_string()),
        Argument::ObjectExpression(object) => object
            .properties
            .iter()
            .find_map(|property| {
                let ObjectPropertyKind::ObjectProperty(property) = property else {
                    return None;
                };
                (property.key.static_name().as_deref() == Some("namespace")).then(
                    || match &property.value {
                        Expression::StringLiteral(literal) => {
                            NamespaceArg::Scoped(literal.value.to_string())
                        }
                        _ => NamespaceArg::Dynamic,
                    },
                )
            })
            .unwrap_or(NamespaceArg::Unscoped),
        _ => NamespaceArg::Dynamic,
    }
}

fn translator_factory_binding_from_expression(
    expression: &Expression<'_>,
    factories: &BTreeSet<String>,
    client_namespaces: &BTreeSet<String>,
    server_namespaces: &BTreeSet<String>,
) -> Option<TranslatorBinding> {
    match expression.get_inner_expression() {
        Expression::CallExpression(call) => {
            let is_factory = call
                .callee
                .get_identifier_reference()
                .is_some_and(|identifier| factories.contains(identifier.name.as_str()))
                || call.callee.get_member_expr().is_some_and(|member| {
                    let Some(object) = member.object().get_identifier_reference() else {
                        return false;
                    };
                    match member.static_property_name() {
                        Some("useTranslations") => client_namespaces.contains(object.name.as_str()),
                        Some("getTranslations") => server_namespaces.contains(object.name.as_str()),
                        _ => false,
                    }
                });
            is_factory
                .then(|| translator_binding_from_namespace_arg(static_factory_namespace_arg(call)))
        }
        Expression::AwaitExpression(await_expression) => {
            translator_factory_binding_from_expression(
                &await_expression.argument,
                factories,
                client_namespaces,
                server_namespaces,
            )
        }
        Expression::ConditionalExpression(conditional) => {
            let consequent = translator_factory_binding_from_expression(
                &conditional.consequent,
                factories,
                client_namespaces,
                server_namespaces,
            );
            let alternate = translator_factory_binding_from_expression(
                &conditional.alternate,
                factories,
                client_namespaces,
                server_namespaces,
            );
            match (consequent, alternate) {
                (Some(left), Some(right)) => Some(merge_translator_bindings(&left, &right)),
                (Some(_), None) | (None, Some(_)) => {
                    Some(translator_binding_from_namespace_arg(NamespaceArg::Dynamic))
                }
                (None, None) => None,
            }
        }
        _ => None,
    }
}

fn jsx_alias_targets_from_expression(expression: &Expression<'_>) -> Vec<JsxAliasTarget> {
    let mut targets = match expression.get_inner_expression() {
        Expression::Identifier(identifier) => vec![JsxAliasTarget {
            namespace: None,
            name: identifier.name.to_string(),
        }],
        Expression::StaticMemberExpression(member) => member
            .object
            .get_identifier_reference()
            .map(|namespace| {
                vec![JsxAliasTarget {
                    namespace: Some(namespace.name.to_string()),
                    name: member.property.name.to_string(),
                }]
            })
            .unwrap_or_default(),
        Expression::ConditionalExpression(conditional) => {
            let mut targets = jsx_alias_targets_from_expression(&conditional.consequent);
            targets.extend(jsx_alias_targets_from_expression(&conditional.alternate));
            targets
        }
        Expression::LogicalExpression(logical) => {
            let mut targets = jsx_alias_targets_from_expression(&logical.left);
            targets.extend(jsx_alias_targets_from_expression(&logical.right));
            targets
        }
        _ => Vec::new(),
    };
    targets.sort();
    targets.dedup();
    targets
}

struct TranslatorReturnCollector {
    factories: BTreeSet<String>,
    client_namespaces: BTreeSet<String>,
    server_namespaces: BTreeSet<String>,
    shadowed_builtins: BTreeSet<String>,
    bindings: Vec<TranslatorBinding>,
    array_bindings: Vec<TranslatorBinding>,
    array_param_indexes: ParamIndexes,
    forwards: BTreeSet<TranslatorReturnForward>,
    local_bindings: BTreeMap<String, TranslatorBinding>,
    local_array_bindings: BTreeMap<String, TranslatorBinding>,
    local_array_params: BTreeMap<String, ParamIndexes>,
    local_set_arrays: BTreeSet<String>,
    local_object_bindings: BTreeMap<String, TranslatorBinding>,
    local_parameter_calls: BTreeMap<String, BTreeSet<TranslatorReturnForward>>,
    dynamic_callables: BTreeSet<String>,
    parameter_callables: BTreeMap<String, usize>,
    binding_scopes: Vec<TranslatorReturnScopeFrame>,
}

#[derive(Default)]
struct TranslatorReturnScopeFrame {
    previous: BTreeMap<String, TranslatorReturnNameState>,
}

struct TranslatorReturnNameState {
    factory: bool,
    client_namespace: bool,
    server_namespace: bool,
    local_binding: Option<TranslatorBinding>,
    local_array_binding: Option<TranslatorBinding>,
    local_array_params: Option<ParamIndexes>,
    local_set_array: bool,
    local_object_binding: Option<TranslatorBinding>,
    local_parameter_calls: Option<BTreeSet<TranslatorReturnForward>>,
    dynamic_callable: bool,
    parameter_callable: Option<usize>,
}

fn translator_return_forward_callees(
    expression: &Expression<'_>,
) -> BTreeSet<TranslatorReturnForward> {
    match expression.get_inner_expression() {
        Expression::CallExpression(call) => {
            if let Some(identifier) = call.callee.get_identifier_reference() {
                return BTreeSet::from([TranslatorReturnForward::Local(
                    identifier.name.to_string(),
                )]);
            }
            let Some(member) = call.callee.get_member_expr() else {
                return BTreeSet::new();
            };
            let Some(namespace) = member.object().get_identifier_reference() else {
                return BTreeSet::new();
            };
            let Some(name) = member.static_property_name() else {
                return BTreeSet::new();
            };
            BTreeSet::from([TranslatorReturnForward::NamespaceMember {
                namespace: namespace.name.to_string(),
                name: name.to_string(),
            }])
        }
        Expression::AwaitExpression(await_expression) => {
            translator_return_forward_callees(&await_expression.argument)
        }
        Expression::ConditionalExpression(conditional) => {
            let mut forwards = translator_return_forward_callees(&conditional.consequent);
            forwards.extend(translator_return_forward_callees(&conditional.alternate));
            forwards
        }
        _ => BTreeSet::new(),
    }
}

fn translator_return_callable_forwards(
    expression: &Expression<'_>,
) -> BTreeSet<TranslatorReturnForward> {
    match expression.get_inner_expression() {
        Expression::Identifier(identifier) => {
            BTreeSet::from([TranslatorReturnForward::Local(identifier.name.to_string())])
        }
        Expression::StaticMemberExpression(member) => member
            .object
            .get_identifier_reference()
            .map(|namespace| {
                BTreeSet::from([TranslatorReturnForward::NamespaceMember {
                    namespace: namespace.name.to_string(),
                    name: member.property.name.to_string(),
                }])
            })
            .unwrap_or_default(),
        Expression::ConditionalExpression(conditional) => {
            let mut forwards = translator_return_callable_forwards(&conditional.consequent);
            forwards.extend(translator_return_callable_forwards(&conditional.alternate));
            forwards
        }
        Expression::LogicalExpression(logical) => {
            let mut forwards = translator_return_callable_forwards(&logical.left);
            forwards.extend(translator_return_callable_forwards(&logical.right));
            forwards
        }
        Expression::CallExpression(call) => call
            .callee
            .get_member_expr()
            .filter(|member| member.static_property_name() == Some("bind"))
            .map(|member| translator_return_callable_forwards(member.object()))
            .unwrap_or_default(),
        _ => BTreeSet::new(),
    }
}

impl TranslatorReturnCollector {
    fn is_set_array_expression(&self, expression: &Expression<'_>) -> bool {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => {
                self.local_set_arrays.contains(identifier.name.as_str())
            }
            Expression::NewExpression(new_expression) => {
                is_identifier_expression(&new_expression.callee, "Set")
                    && !self.shadowed_builtins.contains("Set")
            }
            Expression::ConditionalExpression(conditional) => {
                self.is_set_array_expression(&conditional.consequent)
                    && self.is_set_array_expression(&conditional.alternate)
            }
            Expression::LogicalExpression(logical) => {
                self.is_set_array_expression(&logical.left)
                    && self.is_set_array_expression(&logical.right)
            }
            _ => false,
        }
    }

    fn forwards_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> BTreeSet<TranslatorReturnForward> {
        let mut forwards = translator_return_forward_callees(expression);
        forwards.retain(|forward| match forward {
            TranslatorReturnForward::Local(name) => !self.parameter_callables.contains_key(name),
            _ => true,
        });
        forwards.extend(self.parameter_calls_from_expression(expression));
        match expression.get_inner_expression() {
            Expression::AwaitExpression(await_expression) => {
                forwards.extend(self.forwards_from_expression(&await_expression.argument));
            }
            Expression::ConditionalExpression(conditional) => {
                forwards.extend(self.forwards_from_expression(&conditional.consequent));
                forwards.extend(self.forwards_from_expression(&conditional.alternate));
            }
            Expression::LogicalExpression(logical) => {
                forwards.extend(self.forwards_from_expression(&logical.left));
                forwards.extend(self.forwards_from_expression(&logical.right));
            }
            _ => {}
        }
        if let Expression::CallExpression(call) = expression.get_inner_expression()
            && let Some(member) = call.callee.get_member_expr()
            && let Some(method) = member.static_property_name()
        {
            forwards.extend(self.forwards_from_expression(member.object()));
            let callback_index =
                if method == "from" && is_identifier_expression(member.object(), "Array") {
                    Some(1)
                } else if matches!(
                    method,
                    "map" | "flatMap" | "reduce" | "reduceRight" | "then" | "catch"
                ) {
                    Some(0)
                } else {
                    None
                };
            if let Some(callback) = callback_index
                .and_then(|index| call.arguments.get(index))
                .and_then(|callback| self.callback_summary_from_argument(callback))
            {
                forwards.extend(callback.forwards);
            }
        }
        forwards
    }

    fn parameter_calls_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> BTreeSet<TranslatorReturnForward> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .local_parameter_calls
                .get(identifier.name.as_str())
                .cloned()
                .unwrap_or_default(),
            Expression::CallExpression(call) => {
                if let Some(param_index) =
                    call.callee
                        .get_identifier_reference()
                        .and_then(|identifier| {
                            self.parameter_callables
                                .get(identifier.name.as_str())
                                .copied()
                        })
                {
                    return BTreeSet::from([TranslatorReturnForward::ParameterCall {
                        param_index,
                        binding: translator_binding_from_namespace_arg(
                            static_factory_namespace_arg(call),
                        ),
                    }]);
                }
                let target = if let Some(identifier) = call.callee.get_identifier_reference() {
                    Some((None, identifier.name.to_string()))
                } else {
                    call.callee.get_member_expr().and_then(|member| {
                        Some((
                            Some(member.object().get_identifier_reference()?.name.to_string()),
                            member.static_property_name()?.to_string(),
                        ))
                    })
                };
                let Some((namespace, name)) = target else {
                    return BTreeSet::new();
                };
                let argument_params = call
                    .arguments
                    .iter()
                    .map(|argument| {
                        argument
                            .as_expression()?
                            .get_identifier_reference()
                            .and_then(|identifier| {
                                self.parameter_callables
                                    .get(identifier.name.as_str())
                                    .copied()
                            })
                    })
                    .collect::<Vec<_>>();
                argument_params
                    .iter()
                    .any(Option::is_some)
                    .then(|| {
                        BTreeSet::from([TranslatorReturnForward::ForwardCall {
                            namespace,
                            name,
                            argument_params,
                            argument_targets: BTreeMap::new(),
                            wrapper_arguments: BTreeSet::new(),
                        }])
                    })
                    .unwrap_or_default()
            }
            Expression::AwaitExpression(await_expression) => {
                self.parameter_calls_from_expression(&await_expression.argument)
            }
            Expression::ConditionalExpression(conditional) => {
                let mut calls = self.parameter_calls_from_expression(&conditional.consequent);
                calls.extend(self.parameter_calls_from_expression(&conditional.alternate));
                calls
            }
            Expression::LogicalExpression(logical) => {
                let mut calls = self.parameter_calls_from_expression(&logical.left);
                calls.extend(self.parameter_calls_from_expression(&logical.right));
                calls
            }
            Expression::ArrowFunctionExpression(_) | Expression::FunctionExpression(_) => self
                .callback_summary_from_expression(expression)
                .map(|summary| summary.forwards)
                .unwrap_or_default(),
            _ => BTreeSet::new(),
        }
    }

    fn binding_from_expression(&self, expression: &Expression<'_>) -> Option<TranslatorBinding> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => {
                self.local_bindings.get(identifier.name.as_str()).cloned()
            }
            Expression::AwaitExpression(await_expression) => {
                self.binding_from_expression(&await_expression.argument)
            }
            Expression::ConditionalExpression(conditional) => {
                let consequent = self.binding_from_expression(&conditional.consequent);
                let alternate = self.binding_from_expression(&conditional.alternate);
                match (consequent, alternate) {
                    (Some(left), Some(right)) => Some(merge_translator_bindings(&left, &right)),
                    (Some(_), None) | (None, Some(_)) => {
                        Some(translator_binding_from_namespace_arg(NamespaceArg::Dynamic))
                    }
                    (None, None) => None,
                }
            }
            Expression::LogicalExpression(logical) => {
                let left = self.binding_from_expression(&logical.left);
                let right = self.binding_from_expression(&logical.right);
                match (left, right) {
                    (Some(left), Some(right)) => Some(merge_translator_bindings(&left, &right)),
                    (Some(_), None) | (None, Some(_)) => {
                        Some(translator_binding_from_namespace_arg(NamespaceArg::Dynamic))
                    }
                    (None, None) => None,
                }
            }
            Expression::CallExpression(call) => {
                let dynamic = call
                    .callee
                    .get_identifier_reference()
                    .is_some_and(|identifier| {
                        self.dynamic_callables.contains(identifier.name.as_str())
                    })
                    || call.callee.get_member_expr().is_some_and(|member| {
                        member
                            .object()
                            .get_identifier_reference()
                            .is_some_and(|identifier| {
                                self.dynamic_callables.contains(identifier.name.as_str())
                            })
                    });
                if dynamic {
                    Some(translator_binding_from_namespace_arg(NamespaceArg::Dynamic))
                } else {
                    translator_factory_binding_from_expression(
                        expression,
                        &self.factories,
                        &self.client_namespaces,
                        &self.server_namespaces,
                    )
                }
            }
            _ => translator_factory_binding_from_expression(
                expression,
                &self.factories,
                &self.client_namespaces,
                &self.server_namespaces,
            ),
        }
    }

    fn array_binding_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<TranslatorBinding> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .local_array_bindings
                .get(identifier.name.as_str())
                .cloned(),
            Expression::ArrayExpression(array) => {
                merge_translator_binding_iter(array.elements.iter().filter_map(|element| {
                    match element {
                        ArrayExpressionElement::SpreadElement(spread) => {
                            self.array_binding_from_expression(&spread.argument)
                        }
                        _ => element.as_expression().and_then(|expression| {
                            self.binding_from_expression(expression)
                                .or_else(|| self.array_binding_from_expression(expression))
                        }),
                    }
                }))
            }
            Expression::AwaitExpression(await_expression) => {
                self.array_binding_from_expression(&await_expression.argument)
            }
            Expression::ConditionalExpression(conditional) => merge_optional_translator_bindings(
                self.array_binding_from_expression(&conditional.consequent),
                self.array_binding_from_expression(&conditional.alternate),
            ),
            Expression::LogicalExpression(logical) => merge_optional_translator_bindings(
                self.array_binding_from_expression(&logical.left),
                self.array_binding_from_expression(&logical.right),
            ),
            Expression::NewExpression(new_expression)
                if is_identifier_expression(&new_expression.callee, "Set")
                    && !self.shadowed_builtins.contains("Set") =>
            {
                new_expression
                    .arguments
                    .first()
                    .and_then(Argument::as_expression)
                    .and_then(|expression| self.array_binding_from_expression(expression))
            }
            Expression::CallExpression(call) => {
                let member = call.callee.get_member_expr()?;
                let method = member.static_property_name()?;
                if method == "all" && is_identifier_expression(member.object(), "Promise") {
                    return call
                        .arguments
                        .first()
                        .and_then(Argument::as_expression)
                        .and_then(|expression| self.array_binding_from_expression(expression));
                }
                if method == "of" && is_identifier_expression(member.object(), "Array") {
                    return merge_translator_binding_iter(call.arguments.iter().filter_map(
                        |argument| {
                            argument.as_expression().and_then(|expression| {
                                self.binding_from_expression(expression)
                                    .or_else(|| self.array_binding_from_expression(expression))
                            })
                        },
                    ));
                }
                if method == "from" && is_identifier_expression(member.object(), "Array") {
                    let source = call
                        .arguments
                        .first()
                        .and_then(Argument::as_expression)
                        .and_then(|expression| self.array_binding_from_expression(expression));
                    let callback = call
                        .arguments
                        .get(1)
                        .and_then(|callback| self.callback_binding_from_argument(callback));
                    return merge_translator_binding_iter(source.into_iter().chain(callback));
                }
                if method == "values" && is_identifier_expression(member.object(), "Object") {
                    return call
                        .arguments
                        .first()
                        .and_then(Argument::as_expression)
                        .and_then(|expression| self.object_binding_from_expression(expression));
                }
                let receiver = self.array_binding_from_expression(member.object());
                match method.as_ref() {
                    "concat" => {
                        let arguments = call.arguments.iter().filter_map(|argument| {
                            argument.as_expression().and_then(|expression| {
                                self.binding_from_expression(expression)
                                    .or_else(|| self.array_binding_from_expression(expression))
                            })
                        });
                        merge_translator_binding_iter(receiver.into_iter().chain(arguments))
                    }
                    "map" | "flatMap" | "reduce" | "reduceRight" => {
                        let callback = call
                            .arguments
                            .first()
                            .and_then(|callback| self.callback_binding_from_argument(callback));
                        merge_translator_binding_iter(receiver.into_iter().chain(callback))
                    }
                    "then" | "catch" => call
                        .arguments
                        .first()
                        .and_then(|callback| self.callback_binding_from_argument(callback)),
                    "toSpliced" | "with" => {
                        let arguments = call.arguments.iter().filter_map(|argument| {
                            argument
                                .as_expression()
                                .and_then(|expression| self.binding_from_expression(expression))
                        });
                        merge_translator_binding_iter(receiver.into_iter().chain(arguments))
                    }
                    "slice" | "filter" | "splice" | "copyWithin" | "fill" | "reverse" | "sort"
                    | "toReversed" | "toSorted" | "values" => receiver,
                    "keys" if self.is_set_array_expression(member.object()) => receiver,
                    _ => None,
                }
            }
            _ => None,
        }
    }

    fn callback_binding_from_argument(&self, callback: &Argument<'_>) -> Option<TranslatorBinding> {
        let summary = self.callback_summary_from_argument(callback)?;
        merge_translator_binding_iter(summary.binding.into_iter().chain(summary.array_binding))
    }

    fn callback_summary_from_argument(
        &self,
        callback: &Argument<'_>,
    ) -> Option<TranslatorReturnSummary> {
        let (params, body, expression) = match callback {
            Argument::ArrowFunctionExpression(arrow) => {
                (&arrow.params, Some(&arrow.body), arrow.expression)
            }
            Argument::FunctionExpression(function) => {
                (&function.params, function.body.as_ref(), false)
            }
            _ => {
                let expression = callback.as_expression()?;
                if let Some(identifier) = expression.get_identifier_reference()
                    && let Some(forwards) = self
                        .local_parameter_calls
                        .get(identifier.name.as_str())
                        .cloned()
                {
                    return Some(TranslatorReturnSummary {
                        forwards,
                        ..TranslatorReturnSummary::default()
                    });
                }
                let mut forwards = translator_return_callable_forwards(expression);
                forwards.retain(|forward| match forward {
                    TranslatorReturnForward::Local(name) => {
                        !self.parameter_callables.contains_key(name)
                    }
                    _ => true,
                });
                if !forwards.is_empty() {
                    return Some(TranslatorReturnSummary {
                        forwards,
                        ..TranslatorReturnSummary::default()
                    });
                }
                return self.callback_summary_from_expression(expression);
            }
        };
        self.callback_summary_from_parts(params, body.map(|body| &**body), expression)
    }

    fn callback_summary_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<TranslatorReturnSummary> {
        match expression.get_inner_expression() {
            Expression::ArrowFunctionExpression(arrow) => {
                self.callback_summary_from_parts(&arrow.params, Some(&arrow.body), arrow.expression)
            }
            Expression::FunctionExpression(function) => self.callback_summary_from_parts(
                &function.params,
                function.body.as_ref().map(|body| &**body),
                false,
            ),
            _ => None,
        }
    }

    fn callback_summary_from_parts(
        &self,
        params: &oxc_ast::ast::FormalParameters<'_>,
        body: Option<&FunctionBody<'_>>,
        expression: bool,
    ) -> Option<TranslatorReturnSummary> {
        let mut collector = TranslatorReturnCollector {
            factories: self.factories.clone(),
            client_namespaces: self.client_namespaces.clone(),
            server_namespaces: self.server_namespaces.clone(),
            shadowed_builtins: self.shadowed_builtins.clone(),
            bindings: Vec::new(),
            array_bindings: Vec::new(),
            array_param_indexes: BTreeSet::new(),
            forwards: BTreeSet::new(),
            local_bindings: self.local_bindings.clone(),
            local_array_bindings: self.local_array_bindings.clone(),
            local_array_params: self.local_array_params.clone(),
            local_set_arrays: self.local_set_arrays.clone(),
            local_object_bindings: self.local_object_bindings.clone(),
            local_parameter_calls: self.local_parameter_calls.clone(),
            dynamic_callables: self.dynamic_callables.clone(),
            parameter_callables: self.parameter_callables.clone(),
            binding_scopes: Vec::new(),
        };
        for parameter in &params.items {
            for identifier in parameter.pattern.get_binding_identifiers() {
                collector.mask_name(identifier.name.as_str());
            }
        }
        if let Some(rest) = &params.rest {
            for identifier in rest.rest.argument.get_binding_identifiers() {
                collector.mask_name(identifier.name.as_str());
            }
        }
        let body = body?;
        if expression
            && let Some(Statement::ExpressionStatement(statement)) = body.statements.first()
        {
            let forwards = collector.forwards_from_expression(&statement.expression);
            return Some(TranslatorReturnSummary {
                binding: collector.binding_from_expression(&statement.expression),
                array_binding: collector.array_binding_from_expression(&statement.expression),
                array_param_indexes: collector.array_params_from_expression(&statement.expression),
                forwards,
            });
        }
        collector.hoist_var_bindings(body);
        for statement in &body.statements {
            collector.visit_statement(statement);
        }
        Some(collector.summary())
    }

    fn object_binding_from_expression(
        &self,
        expression: &Expression<'_>,
    ) -> Option<TranslatorBinding> {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .local_object_bindings
                .get(identifier.name.as_str())
                .cloned(),
            Expression::ObjectExpression(object) => {
                merge_translator_binding_iter(object.properties.iter().filter_map(|property| {
                    match property {
                        ObjectPropertyKind::ObjectProperty(property) => self
                            .binding_from_expression(&property.value)
                            .or_else(|| self.array_binding_from_expression(&property.value))
                            .or_else(|| self.object_binding_from_expression(&property.value)),
                        ObjectPropertyKind::SpreadProperty(spread) => {
                            self.object_binding_from_expression(&spread.argument)
                        }
                    }
                }))
            }
            Expression::ConditionalExpression(conditional) => merge_optional_translator_bindings(
                self.object_binding_from_expression(&conditional.consequent),
                self.object_binding_from_expression(&conditional.alternate),
            ),
            Expression::LogicalExpression(logical) => merge_optional_translator_bindings(
                self.object_binding_from_expression(&logical.left),
                self.object_binding_from_expression(&logical.right),
            ),
            _ => None,
        }
    }

    fn array_params_from_expression(&self, expression: &Expression<'_>) -> ParamIndexes {
        match expression.get_inner_expression() {
            Expression::Identifier(identifier) => self
                .local_array_params
                .get(identifier.name.as_str())
                .cloned()
                .or_else(|| {
                    self.parameter_callables
                        .get(identifier.name.as_str())
                        .copied()
                        .map(|index| BTreeSet::from([index]))
                })
                .unwrap_or_default(),
            Expression::ArrayExpression(array) => {
                let mut indexes = BTreeSet::new();
                for element in &array.elements {
                    let expression = match element {
                        ArrayExpressionElement::SpreadElement(spread) => &spread.argument,
                        _ => {
                            let Some(expression) = element.as_expression() else {
                                continue;
                            };
                            expression
                        }
                    };
                    indexes.extend(self.array_params_from_expression(expression));
                }
                indexes
            }
            Expression::AwaitExpression(await_expression) => {
                self.array_params_from_expression(&await_expression.argument)
            }
            Expression::ConditionalExpression(conditional) => {
                let mut indexes = self.array_params_from_expression(&conditional.consequent);
                indexes.extend(self.array_params_from_expression(&conditional.alternate));
                indexes
            }
            Expression::LogicalExpression(logical) => {
                let mut indexes = self.array_params_from_expression(&logical.left);
                indexes.extend(self.array_params_from_expression(&logical.right));
                indexes
            }
            Expression::NewExpression(new_expression)
                if is_identifier_expression(&new_expression.callee, "Set")
                    && !self.shadowed_builtins.contains("Set") =>
            {
                new_expression
                    .arguments
                    .first()
                    .and_then(Argument::as_expression)
                    .map(|expression| self.array_params_from_expression(expression))
                    .unwrap_or_default()
            }
            Expression::CallExpression(call) => {
                let Some(member) = call.callee.get_member_expr() else {
                    return BTreeSet::new();
                };
                let Some(method) = member.static_property_name() else {
                    return BTreeSet::new();
                };
                let recognized = (is_identifier_expression(member.object(), "Promise")
                    && method == "all")
                    || (is_identifier_expression(member.object(), "Array")
                        && matches!(method, "from" | "of"))
                    || (is_identifier_expression(member.object(), "Object") && method == "values")
                    || matches!(
                        method,
                        "concat"
                            | "map"
                            | "flatMap"
                            | "reduce"
                            | "reduceRight"
                            | "then"
                            | "catch"
                            | "slice"
                            | "filter"
                            | "splice"
                            | "copyWithin"
                            | "fill"
                            | "reverse"
                            | "sort"
                            | "toReversed"
                            | "toSorted"
                            | "toSpliced"
                            | "with"
                            | "values"
                    );
                let recognized = recognized
                    || (method == "keys" && self.is_set_array_expression(member.object()));
                if !recognized {
                    return BTreeSet::new();
                }
                let mut indexes = self.array_params_from_expression(member.object());
                for argument in &call.arguments {
                    if matches!(
                        argument,
                        Argument::ArrowFunctionExpression(_) | Argument::FunctionExpression(_)
                    ) {
                        if let Some(summary) = self.callback_summary_from_argument(argument) {
                            indexes.extend(summary.array_param_indexes);
                        }
                    } else if let Some(expression) = argument.as_expression() {
                        indexes.extend(self.array_params_from_expression(expression));
                    }
                }
                indexes
            }
            Expression::ArrowFunctionExpression(arrow)
                if arrow.expression
                    && matches!(
                        arrow.body.statements.first(),
                        Some(Statement::ExpressionStatement(_))
                    ) =>
            {
                let Some(Statement::ExpressionStatement(statement)) = arrow.body.statements.first()
                else {
                    return BTreeSet::new();
                };
                self.array_params_from_expression(&statement.expression)
            }
            _ => BTreeSet::new(),
        }
    }

    fn mask_name(&mut self, name: &str) {
        let previous = TranslatorReturnNameState {
            factory: self.factories.contains(name),
            client_namespace: self.client_namespaces.contains(name),
            server_namespace: self.server_namespaces.contains(name),
            local_binding: self.local_bindings.get(name).cloned(),
            local_array_binding: self.local_array_bindings.get(name).cloned(),
            local_array_params: self.local_array_params.get(name).cloned(),
            local_set_array: self.local_set_arrays.contains(name),
            local_object_binding: self.local_object_bindings.get(name).cloned(),
            local_parameter_calls: self.local_parameter_calls.get(name).cloned(),
            dynamic_callable: self.dynamic_callables.contains(name),
            parameter_callable: self.parameter_callables.get(name).copied(),
        };
        if let Some(scope) = self.binding_scopes.last_mut() {
            scope.previous.entry(name.to_string()).or_insert(previous);
        }
        self.factories.remove(name);
        self.client_namespaces.remove(name);
        self.server_namespaces.remove(name);
        self.local_bindings.remove(name);
        self.local_array_bindings.remove(name);
        self.local_array_params.remove(name);
        self.local_set_arrays.remove(name);
        self.local_object_bindings.remove(name);
        self.local_parameter_calls.remove(name);
        self.dynamic_callables.remove(name);
        self.parameter_callables.remove(name);
    }

    fn mask_name_unscoped(&mut self, name: &str) {
        self.factories.remove(name);
        self.client_namespaces.remove(name);
        self.server_namespaces.remove(name);
        self.local_bindings.remove(name);
        self.local_array_bindings.remove(name);
        self.local_array_params.remove(name);
        self.local_set_arrays.remove(name);
        self.local_object_bindings.remove(name);
        self.local_parameter_calls.remove(name);
        self.dynamic_callables.remove(name);
        self.parameter_callables.remove(name);
    }

    fn hoist_var_bindings(&mut self, body: &FunctionBody<'_>) {
        for name in function_var_bindings(body) {
            let shadows_translator_source = self.factories.contains(&name)
                || self.client_namespaces.contains(&name)
                || self.server_namespaces.contains(&name)
                || self.local_bindings.contains_key(&name)
                || self.dynamic_callables.contains(&name);
            self.mask_name_unscoped(&name);
            if shadows_translator_source {
                self.dynamic_callables.insert(name);
            }
        }
    }

    fn summary(self) -> TranslatorReturnSummary {
        TranslatorReturnSummary {
            binding: merge_translator_binding_iter(self.bindings),
            array_binding: merge_translator_binding_iter(self.array_bindings),
            array_param_indexes: self.array_param_indexes,
            forwards: self.forwards,
        }
    }
}

#[derive(Clone, Default)]
struct WrapperReturnSummary {
    direct: bool,
    forwards: BTreeSet<TranslatorReturnForward>,
    array_indexes: BTreeSet<usize>,
    array_index_forwards: BTreeMap<usize, BTreeSet<TranslatorReturnForward>>,
    bound_calls: Vec<WrapperBoundCall>,
}

#[derive(Default)]
struct TranslatorReturnSummary {
    binding: Option<TranslatorBinding>,
    array_binding: Option<TranslatorBinding>,
    array_param_indexes: ParamIndexes,
    forwards: BTreeSet<TranslatorReturnForward>,
}

impl<'a> Visit<'a> for TranslatorReturnCollector {
    fn enter_scope(&mut self, _flags: ScopeFlags, _scope_id: &Cell<Option<ScopeId>>) {
        self.binding_scopes
            .push(TranslatorReturnScopeFrame::default());
    }

    fn leave_scope(&mut self) {
        if let Some(scope) = self.binding_scopes.pop() {
            for (name, state) in scope.previous {
                if state.factory {
                    self.factories.insert(name.clone());
                } else {
                    self.factories.remove(&name);
                }
                if state.client_namespace {
                    self.client_namespaces.insert(name.clone());
                } else {
                    self.client_namespaces.remove(&name);
                }
                if state.server_namespace {
                    self.server_namespaces.insert(name.clone());
                } else {
                    self.server_namespaces.remove(&name);
                }
                if let Some(binding) = state.local_binding {
                    self.local_bindings.insert(name.clone(), binding);
                } else {
                    self.local_bindings.remove(&name);
                }
                if let Some(binding) = state.local_array_binding {
                    self.local_array_bindings.insert(name.clone(), binding);
                } else {
                    self.local_array_bindings.remove(&name);
                }
                if let Some(indexes) = state.local_array_params {
                    self.local_array_params.insert(name.clone(), indexes);
                } else {
                    self.local_array_params.remove(&name);
                }
                if state.local_set_array {
                    self.local_set_arrays.insert(name.clone());
                } else {
                    self.local_set_arrays.remove(&name);
                }
                if let Some(binding) = state.local_object_binding {
                    self.local_object_bindings.insert(name.clone(), binding);
                } else {
                    self.local_object_bindings.remove(&name);
                }
                if let Some(calls) = state.local_parameter_calls {
                    self.local_parameter_calls.insert(name.clone(), calls);
                } else {
                    self.local_parameter_calls.remove(&name);
                }
                if state.dynamic_callable {
                    self.dynamic_callables.insert(name.clone());
                } else {
                    self.dynamic_callables.remove(&name);
                }
                if let Some(param_index) = state.parameter_callable {
                    self.parameter_callables.insert(name, param_index);
                } else {
                    self.parameter_callables.remove(&name);
                }
            }
        }
    }

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        let binding = statement
            .argument
            .as_ref()
            .and_then(|argument| self.binding_from_expression(argument));
        let array_binding = statement
            .argument
            .as_ref()
            .and_then(|argument| self.array_binding_from_expression(argument));
        if let Some(argument) = &statement.argument {
            self.array_param_indexes
                .extend(self.array_params_from_expression(argument));
        }
        let unresolved = binding.is_none() && array_binding.is_none();
        if let Some(binding) = binding {
            self.bindings.push(binding);
        }
        if let Some(binding) = array_binding {
            self.array_bindings.push(binding);
        }
        if unresolved && let Some(argument) = &statement.argument {
            self.forwards
                .extend(self.forwards_from_expression(argument));
        }
    }

    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _arrow: &ArrowFunctionExpression<'a>) {}

    fn visit_catch_parameter(&mut self, parameter: &CatchParameter<'a>) {
        for identifier in parameter.pattern.get_binding_identifiers() {
            self.mask_name(identifier.name.as_str());
        }
        walk::walk_catch_parameter(self, parameter);
    }

    fn visit_variable_declarator(&mut self, declarator: &VariableDeclarator<'a>) {
        if let (Some(name), Some(init)) = (
            binding_identifier_name(&declarator.id),
            declarator.init.as_ref(),
        ) {
            let shadows_translator_source = self.factories.contains(name)
                || self.client_namespaces.contains(name)
                || self.server_namespaces.contains(name)
                || self.local_bindings.contains_key(name)
                || self.dynamic_callables.contains(name);
            let binding = self.binding_from_expression(init);
            let has_binding = binding.is_some();
            let array_binding = self.array_binding_from_expression(init);
            let array_params = self.array_params_from_expression(init);
            let set_array = self.is_set_array_expression(init);
            let object_binding = self.object_binding_from_expression(init);
            let parameter_calls = self.parameter_calls_from_expression(init);
            if declarator.kind == VariableDeclarationKind::Var {
                if let Some(binding) = binding {
                    self.local_bindings
                        .entry(name.to_string())
                        .and_modify(|existing| {
                            *existing = merge_translator_bindings(existing, &binding)
                        })
                        .or_insert(binding);
                } else if self.local_bindings.contains_key(name) {
                    self.local_bindings.insert(
                        name.to_string(),
                        translator_binding_from_namespace_arg(NamespaceArg::Dynamic),
                    );
                }
                if !parameter_calls.is_empty() {
                    self.local_parameter_calls
                        .entry(name.to_string())
                        .or_default()
                        .extend(parameter_calls);
                }
                if let Some(binding) = array_binding {
                    self.local_array_bindings
                        .entry(name.to_string())
                        .and_modify(|existing| {
                            *existing = merge_translator_bindings(existing, &binding)
                        })
                        .or_insert(binding);
                } else {
                    self.local_array_bindings.remove(name);
                }
                if array_params.is_empty() {
                    self.local_array_params.remove(name);
                } else {
                    self.local_array_params
                        .entry(name.to_string())
                        .or_default()
                        .extend(array_params);
                }
                if set_array {
                    self.local_set_arrays.insert(name.to_string());
                } else {
                    self.local_set_arrays.remove(name);
                }
                if let Some(binding) = object_binding {
                    self.local_object_bindings
                        .entry(name.to_string())
                        .and_modify(|existing| {
                            *existing = merge_translator_bindings(existing, &binding)
                        })
                        .or_insert(binding);
                } else {
                    self.local_object_bindings.remove(name);
                }
            } else {
                self.mask_name(name);
                if let Some(binding) = binding {
                    self.local_bindings.insert(name.to_string(), binding);
                }
                if let Some(binding) = array_binding {
                    self.local_array_bindings.insert(name.to_string(), binding);
                }
                if !array_params.is_empty() {
                    self.local_array_params
                        .insert(name.to_string(), array_params);
                }
                if set_array {
                    self.local_set_arrays.insert(name.to_string());
                }
                if let Some(binding) = object_binding {
                    self.local_object_bindings.insert(name.to_string(), binding);
                }
                if !parameter_calls.is_empty() {
                    self.local_parameter_calls
                        .insert(name.to_string(), parameter_calls);
                } else if !has_binding && shadows_translator_source {
                    self.dynamic_callables.insert(name.to_string());
                }
            }
        }
        walk::walk_variable_declarator(self, declarator);
    }

    fn visit_assignment_expression(&mut self, expression: &AssignmentExpression<'a>) {
        if expression.operator == AssignmentOperator::Assign
            && let AssignmentTarget::AssignmentTargetIdentifier(identifier) = &expression.left
        {
            let name = identifier.name.as_str();
            let binding = self.binding_from_expression(&expression.right);
            let array_binding = self.array_binding_from_expression(&expression.right);
            let array_params = self.array_params_from_expression(&expression.right);
            let set_array = self.is_set_array_expression(&expression.right);
            let object_binding = self.object_binding_from_expression(&expression.right);
            let parameter_calls = self.parameter_calls_from_expression(&expression.right);
            if let Some(binding) = binding {
                self.local_bindings
                    .entry(name.to_string())
                    .and_modify(|existing| {
                        *existing = merge_translator_bindings(existing, &binding)
                    })
                    .or_insert(binding);
            } else if self.local_bindings.contains_key(name) {
                self.local_bindings.insert(
                    name.to_string(),
                    translator_binding_from_namespace_arg(NamespaceArg::Dynamic),
                );
            }
            if !parameter_calls.is_empty() {
                self.local_parameter_calls
                    .entry(name.to_string())
                    .or_default()
                    .extend(parameter_calls);
            }
            if let Some(binding) = array_binding {
                self.local_array_bindings
                    .entry(name.to_string())
                    .and_modify(|existing| {
                        *existing = merge_translator_bindings(existing, &binding)
                    })
                    .or_insert(binding);
            } else {
                self.local_array_bindings.remove(name);
            }
            if array_params.is_empty() {
                self.local_array_params.remove(name);
            } else {
                self.local_array_params
                    .entry(name.to_string())
                    .or_default()
                    .extend(array_params);
            }
            if set_array {
                self.local_set_arrays.insert(name.to_string());
            } else {
                self.local_set_arrays.remove(name);
            }
            if let Some(binding) = object_binding {
                self.local_object_bindings
                    .entry(name.to_string())
                    .and_modify(|existing| {
                        *existing = merge_translator_bindings(existing, &binding)
                    })
                    .or_insert(binding);
            } else {
                self.local_object_bindings.remove(name);
            }
        }
        walk::walk_assignment_expression(self, expression);
    }
}

