    #[test]
    fn checker_results_for_unknown_jsx_namespaces_protect_suffixes() {
        let mut scan = scan(
            r#"
            function Child({tSettings}) {
              return tSettings(runtimeKey);
            }
            <Child {...props} />;
            "#,
        );
        let usage = scan.dynamic_usages.first().expect("dynamic JSX usage");
        assert!(usage.namespace_unknown);

        apply_ts_checker_results(
            &mut scan,
            vec![TsCheckerResult {
                index: 0,
                keys: vec!["navigation.title".to_string()],
            }],
        );

        assert!(scan.used_key_suffixes.contains("navigation.title"));
        assert!(!scan.used_ids.contains("navigation.title"));
        assert!(scan.dynamic_usages.is_empty());
    }

    #[test]
    fn jsx_forward_cache_distinguishes_same_alias_from_different_parents() {
        fn forward(prop_name: &str, component_name: &str, target_prop: &str) -> JsxPropForward {
            JsxPropForward {
                prop_name: prop_name.to_string(),
                component_namespace: None,
                component_name: component_name.to_string(),
                target_prop: target_prop.to_string(),
            }
        }

        fn usage(prop_name: &str) -> JsxPropUsage {
            JsxPropUsage {
                prop_name: prop_name.to_string(),
                keys: None,
                query: None,
                translator_like: false,
            }
        }

        let dir = tempfile::tempdir().expect("tempdir");
        let root = dir.path().join("root.tsx");
        let a = dir.path().join("a.tsx");
        let b = dir.path().join("b.tsx");
        let children = dir.path().join("children.tsx");
        for path in [&root, &a, &b, &children] {
            fs::write(path, "").expect("create source file");
        }
        let import = |source: &str, imported: &str| ImportTarget {
            source: source.to_string(),
            imported: ImportedName::Named(imported.to_string()),
        };

        let project = ProjectIndex {
            files: BTreeMap::from([
                (
                    root.clone(),
                    SourceFileIndex {
                        imports: BTreeMap::from([
                            ("A".to_string(), import("./a", "A")),
                            ("B".to_string(), import("./b", "B")),
                        ]),
                        jsx_components: BTreeMap::from([(
                            "Root".to_string(),
                            JsxComponentSummary {
                                usages: Vec::new(),
                                forwards: vec![
                                    forward("fooFn", "A", "fooFn"),
                                    forward("barFn", "B", "barFn"),
                                ],
                            },
                        )]),
                        ..SourceFileIndex::default()
                    },
                ),
                (
                    a.clone(),
                    SourceFileIndex {
                        imports: BTreeMap::from([(
                            "Child".to_string(),
                            import("./children", "Foo"),
                        )]),
                        named_jsx_exports: BTreeMap::from([(
                            "A".to_string(),
                            JsxComponentSummary {
                                usages: Vec::new(),
                                forwards: vec![forward("fooFn", "Child", "fooTranslator")],
                            },
                        )]),
                        ..SourceFileIndex::default()
                    },
                ),
                (
                    b.clone(),
                    SourceFileIndex {
                        imports: BTreeMap::from([(
                            "Child".to_string(),
                            import("./children", "Bar"),
                        )]),
                        named_jsx_exports: BTreeMap::from([(
                            "B".to_string(),
                            JsxComponentSummary {
                                usages: Vec::new(),
                                forwards: vec![forward("barFn", "Child", "barTranslator")],
                            },
                        )]),
                        ..SourceFileIndex::default()
                    },
                ),
                (
                    children.clone(),
                    SourceFileIndex {
                        named_jsx_exports: BTreeMap::from([
                            (
                                "Foo".to_string(),
                                JsxComponentSummary {
                                    usages: vec![usage("fooTranslator")],
                                    forwards: Vec::new(),
                                },
                            ),
                            (
                                "Bar".to_string(),
                                JsxComponentSummary {
                                    usages: vec![usage("barTranslator")],
                                    forwards: Vec::new(),
                                },
                            ),
                        ]),
                        ..SourceFileIndex::default()
                    },
                ),
            ]),
            source_files: BTreeSet::from([root.clone(), a, b, children]),
            ..ProjectIndex::default()
        };

        let summary = project
            .jsx_component_for_name(&root, "Root")
            .expect("expanded root summary");
        let props = summary
            .usages
            .into_iter()
            .map(|usage| usage.prop_name)
            .collect::<BTreeSet<_>>();
        assert_eq!(
            props,
            BTreeSet::from(["barFn".to_string(), "fooFn".to_string()])
        );
    }

    #[test]
    fn ts_checker_query_offsets_use_utf16_positions_after_non_ascii_source() {
        let source = r#"
            import {useTranslations} from 'next-intl';
            const description = 'Møppe (valgfritt)';
            const t = useTranslations('common');
            t(labelKey);
        "#;
        let scan = scan(source);
        let usage = scan.dynamic_usages.first().expect("dynamic usage");
        let byte_start = source.find("labelKey").expect("labelKey");
        let byte_end = byte_start + "labelKey".len();

        assert_eq!(
            usage.key_start,
            Some(source[..byte_start].encode_utf16().count())
        );
        assert_eq!(
            usage.key_end,
            Some(source[..byte_end].encode_utf16().count())
        );
        assert_ne!(usage.key_start, Some(byte_start));
    }

