    #[test]
    fn namespace_jsx_forwards_preserve_exact_component_usages() {
        let dir = tempfile::tempdir().expect("tempdir");
        let card = dir.path().join("card.tsx");
        let main = dir.path().join("main.tsx");
        fs::write(
            &card,
            r#"
            export function Card({format}) {
              return format('title');
            }
            "#,
        )
        .expect("write card");
        fs::write(
            &main,
            r#"
            import {useTranslations} from 'next-intl';
            import * as Cards from './card';
            function Wrapper({format}) {
              format('known');
              return <Cards.Card format={format} />;
            }
            const format = useTranslations('common');
            <Wrapper format={format} />;
            "#,
        )
        .expect("write source");

        let scan = collect_usage_from_files(dir.path(), &[main]).expect("scan project");

        assert!(scan.used_ids.contains("common.known"));
        assert!(scan.used_ids.contains("common.title"));
        assert!(scan.dynamic_usages.is_empty());
    }

    #[test]
    fn nested_jsx_forwards_are_not_treated_as_direct_escapes() {
        let dir = tempfile::tempdir().expect("tempdir");
        let main = dir.path().join("main.tsx");
        fs::write(
            &main,
            r#"
            import {useTranslations} from 'next-intl';
            function Child({format}) {
              return format('title');
            }
            function Wrapper({format, enabled}) {
              return <Shell header={<Child format={format} />}>
                {enabled ? <Child format={format} /> : null}
              </Shell>;
            }
            const format = useTranslations('common');
            <Wrapper enabled format={format} />;
            "#,
        )
        .expect("write source");

        let scan = collect_usage_from_files(dir.path(), &[main]).expect("scan project");

        assert!(scan.used_ids.contains("common.title"));
        assert!(scan.dynamic_usages.is_empty());
    }

    #[test]
    fn unknown_later_jsx_spreads_protect_dynamic_translator_namespaces() {
        let dir = tempfile::tempdir().expect("tempdir");
        let main = dir.path().join("main.tsx");
        fs::write(
            &main,
            r#"
            import {useTranslations} from 'next-intl';
            function Card({format, messageKey}) {
              return format(messageKey);
            }
            const common = useTranslations('common');
            <Card format={common} {...runtimeProps} messageKey={runtimeKey} />;
            "#,
        )
        .expect("write source");

        let scan = collect_usage_from_files(dir.path(), &[main]).expect("scan project");

        assert!(
            scan.dynamic_usages
                .iter()
                .any(|usage| usage.namespace_unknown)
        );
    }

    #[test]
    fn explicit_jsx_props_after_unknown_spreads_keep_known_namespaces() {
        let dir = tempfile::tempdir().expect("tempdir");
        let main = dir.path().join("main.tsx");
        fs::write(
            &main,
            r#"
            import {useTranslations} from 'next-intl';
            function Card({format, messageKey}) {
              return format(messageKey);
            }
            const common = useTranslations('common');
            <Card {...runtimeProps} format={common} messageKey={runtimeKey} />;
            "#,
        )
        .expect("write source");

        let scan = collect_usage_from_files(dir.path(), &[main]).expect("scan project");

        assert!(
            scan.dynamic_usages
                .iter()
                .any(|usage| usage.namespace == "common")
        );
        assert!(
            !scan
                .dynamic_usages
                .iter()
                .any(|usage| usage.namespace_unknown)
        );
    }

